#[derive(Clone, Debug, Default)]
struct NestedPathChildIndex {
    children: Vec<NestedChildDocument>,
    field_terms: BTreeMap<String, BTreeMap<String, Vec<usize>>>,
    field_string_terms: BTreeMap<String, BTreeMap<String, Vec<usize>>>,
    field_scalar_values: BTreeMap<String, Vec<(Value, usize)>>,
    field_exists: BTreeMap<String, std::collections::BTreeSet<usize>>,
}

#[derive(Clone, Debug)]
struct NestedChildDocument {
    parent_id: String,
    parent_seq_no: i64,
    source: Value,
}

impl NestedChildIndex {
    fn from_documents(
        documents: &BTreeMap<String, StoredDocument>,
        refreshed_seq_no: i64,
    ) -> Self {
        let mut index = Self::default();
        for (parent_id, document) in documents {
            if document.metadata.seq_no > refreshed_seq_no {
                continue;
            }
            collect_nested_child_documents_for_source(
                parent_id,
                document.metadata.seq_no,
                &document.source,
                "",
                &mut index,
            );
        }
        index
    }

    fn append_documents(&mut self, documents: &[StoredDocument]) {
        for document in documents {
            collect_nested_child_documents_for_source(
                &document.metadata.id,
                document.metadata.seq_no,
                &document.source,
                "",
                self,
            );
        }
    }
}

impl NestedPathChildIndex {
    fn push_child(&mut self, child: NestedChildDocument) {
        let ordinal = self.children.len();
        index_nested_child_terms(
            "",
            &child.source,
            ordinal,
            &mut self.field_terms,
            &mut self.field_string_terms,
            &mut self.field_scalar_values,
            &mut self.field_exists,
        );
        self.children.push(child);
    }
}

