impl<'a> ReusableQueryContext<'a> {
    fn with_total_hits(total_hits: u64) -> Self {
        Self {
            total_hits: Some(total_hits),
            ..Self::default()
        }
    }

    fn with_existing_total_hits_and_documents(
        total_hits: Option<u64>,
        documents: Vec<&'a StoredDocument>,
    ) -> Self {
        Self {
            total_hits,
            documents: Some(documents),
            ..Self::default()
        }
    }

    fn with_existing_total_hits_documents_and_optional_all_documents(
        total_hits: Option<u64>,
        documents: Vec<&'a StoredDocument>,
        all_documents: Option<Vec<&'a StoredDocument>>,
    ) -> Self {
        let mut reusable = Self::with_existing_total_hits_and_documents(total_hits, documents);
        if let Some(all_documents) = all_documents {
            reusable.all_documents = Some(all_documents);
        }
        reusable
    }

    fn with_all_documents(all_documents: Vec<&'a StoredDocument>) -> Self {
        Self {
            all_documents: Some(all_documents),
            ..Self::default()
        }
    }
}

impl<'a> NativeQueryContext<'a> {
    fn with_total_hits(total_hits: u64) -> Self {
        Self {
            total_hits: Some(total_hits),
            ..Self::default()
        }
    }

    fn with_existing_total_hits(total_hits: u64) -> Self {
        Self::with_total_hits(total_hits)
    }

    fn with_existing_total_hits_and_documents(
        total_hits: Option<u64>,
        documents: Vec<&'a StoredDocument>,
    ) -> Self {
        Self {
            total_hits,
            documents: Some(documents),
            ..Self::default()
        }
    }

    fn with_optional_all_documents(mut self, all_documents: Option<Vec<&'a StoredDocument>>) -> Self {
        self.all_documents = all_documents;
        self
    }

    fn with_existing_total_hits_documents_and_optional_all_documents(
        total_hits: Option<u64>,
        documents: Vec<&'a StoredDocument>,
        all_documents: Option<Vec<&'a StoredDocument>>,
    ) -> Self {
        Self::with_existing_total_hits_and_documents(total_hits, documents)
            .with_optional_all_documents(all_documents.clone())
    }

}

impl<'a> VectorCandidateWindowContext<'a> {
    fn new(
        kind: VectorCandidateWindowContextKind,
        context: NativeQueryContext<'a>,
        exact_hits: Option<Vec<SearchHit>>,
    ) -> Self {
        let exact_documents = context.documents.clone();
        Self {
            kind,
            candidate_ids: exact_documents
                .as_ref()
                .map(|documents| {
                    documents
                        .iter()
                        .map(|document| document.metadata.id.clone())
                        .collect()
                })
                .or_else(|| {
                    exact_hits.as_ref().map(|hits| {
                        hits.iter().map(|hit| hit.metadata.id.clone()).collect()
                    })
                }),
            exact_documents,
            exact_hits,
            context,
        }
    }

    fn total_hits(&self) -> Option<u64> {
        self.context
            .total_hits
            .or_else(|| self.context.documents.as_ref().map(|documents| documents.len() as u64))
    }

    fn documents(&self) -> Option<Vec<&'a StoredDocument>> {
        self.exact_documents.clone()
    }

    fn candidate_ids(&self) -> Option<std::collections::BTreeSet<String>> {
        self.candidate_ids.clone()
    }

    fn hits(&self) -> Option<Vec<SearchHit>> {
        self.exact_hits.clone()
    }

    fn with_optional_all_documents(
        mut self,
        all_documents: Option<Vec<&'a StoredDocument>>,
    ) -> Self {
        self.context = self.context.with_optional_all_documents(all_documents.clone());
        self
    }
}

impl MaterializedMultiIndexHitContext {
    fn with_exact_hits_and_all_hits(hits: &[SearchHit], all_hits: &[SearchHit]) -> Self {
        let mut hits = hits.to_vec();
        let mut all_hits = all_hits.to_vec();
        if hits.len() > 1 {
            hits.sort_by(compare_relevance_hits);
        }
        if all_hits.len() > 1 {
            all_hits.sort_by(compare_relevance_hits);
        }
        Self {
            hits,
            all_hits,
        }
    }
}

impl<'a> MaterializedMultiIndexPerIndexNativeQueryContext<'a> {
    fn new(index_name: &str, context: NativeQueryContext<'a>) -> Self {
        Self {
            index_name: index_name.to_string(),
            context,
        }
    }

    fn hits_from_documents(&self, documents: &[&StoredDocument]) -> Vec<SearchHit> {
        documents
            .iter()
            .map(|document| SearchHit {
                index: self.index_name.to_string(),
                metadata: document.metadata.clone(),
                score: 0.0,
                source: document.source.clone(),
                fields: None,
                highlight: None,
                explanation: None,
                sort: None,
            })
            .collect()
    }
}

