    fn count_documents_for_query_with_context(
        &self,
        query: &Query,
        reusable: ReusableQueryContext<'_>,
    ) -> EngineResult<u64> {
        if let Some(total_hits) = reusable.total_hits {
            return Ok(total_hits);
        }
        if let Some(documents) = reusable.documents {
            return Ok(documents.len() as u64);
        }
        if let Some(documents) = self.search_documents_for_query_native_readonly(self.name(), query)? {
            return Ok(documents.len() as u64);
        }
        Err(invalid_request("query cannot be counted through native document path"))
    }

