    fn search_documents_for_query_native_readonly(
        &self,
        index_name: &str,
        query: &Query,
    ) -> EngineResult<Option<Vec<&StoredDocument>>> {
        if self.search_state.is_none() {
            return Ok(None);
        }
        if Self::query_contains_knn(query) {
            let Some(candidate_ids) = self.search_candidate_ids_for_query_reduced(index_name, query)? else {
                return Ok(None);
            };
            return Ok(Some(
                candidate_ids
                    .iter()
                    .filter_map(|candidate_id| self.refreshed_document_by_id(candidate_id))
                    .filter(|document| {
                        self.score_document_query(query, document)
                            .ok()
                            .flatten()
                            .is_some()
                    })
                    .collect(),
            ));
        }
        if let Query::Nested { path, query } = query {
            return Ok(Some(
                self.search_documents_for_native_nested_query(path, query),
            ));
        }
        let Some(documents) = self.search_documents_for_tantivy_query(query)? else {
            return Ok(None);
        };
        if !query_requires_native_candidate_post_filter(query) {
            return Ok(Some(documents));
        }
        Ok(Some(
            documents
                .into_iter()
                .filter(|document| {
                    self.score_document_query(query, document)
                        .ok()
                        .flatten()
                        .is_some()
                })
                .collect(),
        ))
    }

    fn search_documents_for_query_native_index_aware(
        &mut self,
        index_name: &str,
        query: &Query,
    ) -> EngineResult<Option<Vec<&StoredDocument>>> {
        if self.search_state.is_none() {
            return Ok(None);
        }
        if Self::query_contains_knn(query) {
            let Some(candidate_ids) = self.search_candidate_ids_for_query_reduced(index_name, query)? else {
                return Ok(None);
            };
            return Ok(Some(
                candidate_ids
                    .iter()
                    .filter_map(|candidate_id| self.refreshed_document_by_id(candidate_id))
                    .filter(|document| {
                        self.score_document_query(query, document)
                            .ok()
                            .flatten()
                            .is_some()
                    })
                    .collect(),
            ));
        }
        if let Query::Nested { path, query } = query {
            return Ok(Some(
                self.search_documents_for_native_nested_query(path, query),
            ));
        }
        let Some(documents) = self.search_documents_for_tantivy_query(query)? else {
            return Ok(None);
        };
        if !query_requires_native_candidate_post_filter(query) {
            return Ok(Some(documents));
        }
        Ok(Some(
            documents
                .into_iter()
                .filter(|document| {
                    self.score_document_query(query, document)
                        .ok()
                        .flatten()
                        .is_some()
                })
                .collect(),
        ))
    }

    fn count_documents_for_tantivy_query(&self, query: &Query) -> EngineResult<Option<u64>> {
        let Some(search_state) = &self.search_state else {
            return Ok(None);
        };
        let Some(tantivy_query) = build_tantivy_query(search_state, query)? else {
            if query_requires_native_candidate_post_filter(query)
                && query_allows_source_candidate_scan_for_native_post_filter(query)
            {
                let count = self
                    .refreshed_documents()
                    .into_iter()
                    .filter(|document| {
                        self.score_document_query(query, document)
                            .ok()
                            .flatten()
                            .is_some()
                    })
                    .count();
                return Ok(Some(count as u64));
            }
            return Ok(None);
        };
        let searcher = search_state.reader.searcher();
        let count = searcher
            .search(tantivy_query.as_ref(), &Count)
            .map_err(tantivy_error)?;
        Ok(Some(count as u64))
    }

    fn search_documents_for_tantivy_query(
        &self,
        query: &Query,
    ) -> EngineResult<Option<Vec<&StoredDocument>>> {
        let Some(search_state) = &self.search_state else {
            return Ok(None);
        };
        let Some(tantivy_query) = build_tantivy_query(search_state, query)? else {
            if query_requires_native_candidate_post_filter(query)
                && query_allows_source_candidate_scan_for_native_post_filter(query)
            {
                return Ok(Some(self.refreshed_documents()));
            }
            return Ok(None);
        };
        let searcher = search_state.reader.searcher();
        let limit = self
            .documents
            .values()
            .filter(|document| document.metadata.seq_no <= self.refreshed_seq_no)
            .count();
        let top_docs = searcher
            .search(tantivy_query.as_ref(), &TopDocs::with_limit(limit))
            .map_err(tantivy_error)?;
        let Some(id_field) = search_state.fields.get("_id") else {
            return Ok(None);
        };
        let mut documents = Vec::with_capacity(top_docs.len());
        for (_, address) in top_docs {
            let stored_document = searcher.doc(address).map_err(tantivy_error)?;
            let Some(document_id) = stored_document
                .get_first(id_field.field)
                .and_then(|value| value.as_text())
            else {
                continue;
            };
            if let Some(document) = self.refreshed_document_by_id(document_id) {
                documents.push(document);
            }
        }
        Ok(Some(documents))
    }

    #[cfg(test)]
    fn search_documents_for_query_with_vector_candidate_window_context(
        &self,
        query: &Query,
        context: VectorCandidateWindowContext<'_>,
    ) -> EngineResult<Vec<&StoredDocument>> {
        if let Some(documents) = context.documents() {
            return Ok(documents
                .iter()
                .filter_map(|document| self.documents.get(&document.metadata.id))
                .collect());
        }
        if let Some(hits) = context.hits() {
            return Ok(self.documents_for_search_hits(&hits));
        }
        if let Some(candidate_ids) = context.candidate_ids() {
            return Ok(self.documents_for_candidate_ids(candidate_ids));
        }
        Err(invalid_request("test vector candidate context did not carry native documents"))
    }

