fn nested_child_source_match_ordinals(
    path_index: &NestedPathChildIndex,
    path: &str,
    query: &Query,
) -> Option<std::collections::BTreeSet<usize>> {
    let local_query = localize_query_fields_for_nested_child(query, path);
    let mut ordinals = std::collections::BTreeSet::new();
    for (ordinal, child) in path_index.children.iter().enumerate() {
        if document_matches_query(&local_query, &child.parent_id, &child.source) {
            ordinals.insert(ordinal);
        }
    }
    Some(ordinals)
}

fn nested_child_match_ordinals(
    path_index: &NestedPathChildIndex,
    path: &str,
    field: &str,
    query: &Value,
) -> Option<std::collections::BTreeSet<usize>> {
    let mut ordinals = std::collections::BTreeSet::new();
    if field == "_id" {
        for (ordinal, child) in path_index.children.iter().enumerate() {
            if matches_match_query(Some(&Value::String(child.parent_id.clone())), query) {
                ordinals.insert(ordinal);
            }
        }
        return Some(ordinals);
    }

    let field = nested_child_local_field_name(path, field);
    for (ordinal, child) in path_index.children.iter().enumerate() {
        if matches_match_query(source_value_for_highlight_field(&child.source, &field), query) {
            ordinals.insert(ordinal);
        }
    }
    Some(ordinals)
}

