fn nested_child_local_fields(path: &str, fields: Option<&[String]>) -> Option<Vec<String>> {
    fields.map(|fields| {
        fields
            .iter()
            .map(|field| nested_child_local_field_name(path, field))
            .collect()
    })
}

fn nested_child_exists_ordinals(
    path_index: &NestedPathChildIndex,
    path: &str,
    field: &str,
) -> Option<std::collections::BTreeSet<usize>> {
    if field == "_id" {
        return Some((0..path_index.children.len()).collect());
    }
    let field = nested_child_local_field_name(path, field);
    Some(
        path_index
            .field_exists
            .get(&field)
            .cloned()
            .unwrap_or_default(),
    )
}

fn nested_child_local_field_name(path: &str, field: &str) -> String {
    field
        .strip_prefix(&format!("{path}."))
        .unwrap_or(field)
        .to_string()
}

fn span_query_ranges(id: &str, source: &Value, query: &Query) -> Option<(String, Vec<(usize, usize)>)> {
    match query {
        Query::SpanTerm { field, value } => {
            if field == "_id" {
                return None;
            }
            let field_value = source_value_for_highlight_field(source, field)?;
            Some((field.clone(), span_term_ranges(field_value, value)))
        }
        Query::SpanOr { clauses } => {
            let mut field_name: Option<String> = None;
            let mut ranges = Vec::new();
            for clause in clauses {
                let (field, clause_ranges) = span_query_ranges(id, source, clause)?;
                match &field_name {
                    Some(existing) if existing != &field => return None,
                    None => field_name = Some(field),
                    _ => {}
                }
                ranges.extend(clause_ranges);
            }
            Some((field_name?, ranges))
        }
        Query::SpanFirst { match_query, end } => {
            let (field, ranges) = span_query_ranges(id, source, match_query)?;
            Some((
                field,
                ranges
                    .into_iter()
                    .filter(|(_, range_end)| *range_end <= *end)
                    .collect(),
            ))
        }
        Query::SpanNear {
            clauses,
            slop,
            in_order,
        } => {
            let (field, alternatives) = span_near_clause_term_alternatives(clauses)?;
            if field == "_id" {
                return None;
            }
            let field_value = source_value_for_highlight_field(source, &field)?;
            Some((field, span_near_ranges(field_value, &alternatives, *slop, *in_order)))
        }
        Query::SpanNot { include, exclude } => {
            let (field, include_ranges) = span_query_ranges(id, source, include)?;
            let (exclude_field, exclude_ranges) = span_query_ranges(id, source, exclude)?;
            if field != exclude_field {
                return None;
            }
            Some((
                field,
                include_ranges
                    .into_iter()
                    .filter(|(include_start, include_end)| {
                        !exclude_ranges.iter().any(|(exclude_start, exclude_end)| {
                            exclude_start < include_end && exclude_end > include_start
                        })
                    })
                    .collect(),
            ))
        }
        Query::SpanContaining { big, .. } => span_query_ranges(id, source, big),
        Query::SpanWithin { little, .. } => span_query_ranges(id, source, little),
        _ => None,
    }
}

fn span_term_ranges(field_value: &Value, value: &Value) -> Vec<(usize, usize)> {
    match (field_value, value) {
        (Value::Array(items), value) => items
            .iter()
            .flat_map(|item| span_term_ranges(item, value))
            .collect(),
        (Value::String(field_text), Value::String(term_text)) => tokenize_phrase_text(field_text)
            .iter()
            .enumerate()
            .filter_map(|(index, token)| (token == term_text).then_some((index, index + 1)))
            .collect(),
        _ => Vec::new(),
    }
}

fn span_near_ranges(
    field_value: &Value,
    alternatives: &[Vec<String>],
    slop: usize,
    in_order: bool,
) -> Vec<(usize, usize)> {
    match field_value {
        Value::Array(items) => items
            .iter()
            .flat_map(|item| span_near_ranges(item, alternatives, slop, in_order))
            .collect(),
        Value::String(text) => {
            let tokens = tokenize_phrase_text(text);
            if tokens.is_empty() || alternatives.is_empty() {
                return Vec::new();
            }
            if in_order {
                span_near_in_order_ranges(&tokens, alternatives, slop)
            } else {
                span_near_unordered_ranges(&tokens, alternatives, slop)
            }
        }
        _ => Vec::new(),
    }
}

fn span_near_in_order_ranges(
    tokens: &[String],
    alternatives: &[Vec<String>],
    slop: usize,
) -> Vec<(usize, usize)> {
    let mut ranges = Vec::new();
    for start in 0..tokens.len() {
        if !alternatives[0].iter().any(|term| term == &tokens[start]) {
            continue;
        }
        let mut last = start;
        let mut total_gap = 0usize;
        let mut matched = true;
        for clause_alternatives in &alternatives[1..] {
            let mut next_match = None;
            for idx in (last + 1)..tokens.len() {
                if clause_alternatives.iter().any(|term| term == &tokens[idx]) {
                    next_match = Some(idx);
                    break;
                }
            }
            let Some(next_idx) = next_match else {
                matched = false;
                break;
            };
            total_gap = total_gap.saturating_add(next_idx.saturating_sub(last + 1));
            if total_gap > slop {
                matched = false;
                break;
            }
            last = next_idx;
        }
        if matched {
            ranges.push((start, last + 1));
        }
    }
    ranges
}

fn span_near_unordered_ranges(
    tokens: &[String],
    alternatives: &[Vec<String>],
    slop: usize,
) -> Vec<(usize, usize)> {
    let mut ranges = Vec::new();
    let required = alternatives.len();
    if required == 0 {
        return ranges;
    }
    let max_window = required.saturating_add(slop);
    for start in 0..tokens.len() {
        let end = (start + max_window).min(tokens.len());
        let window = &tokens[start..end];
        if alternatives
            .iter()
            .all(|clause_alternatives| window.iter().any(|token| clause_alternatives.iter().any(|term| term == token)))
        {
            ranges.push((start, end));
        }
    }
    ranges
}

fn span_near_clause_term_alternatives(clauses: &[Query]) -> Option<(String, Vec<Vec<String>>)> {
    let mut field_name: Option<String> = None;
    let mut alternatives = Vec::new();
    for clause in clauses {
        let (field, clause_alternatives) = span_near_single_clause_alternatives(clause)?;
        match &field_name {
            Some(existing) if existing != &field => return None,
            None => field_name = Some(field),
            _ => {}
        }
        alternatives.push(clause_alternatives);
    }
    Some((field_name?, alternatives))
}

fn span_near_single_clause_alternatives(query: &Query) -> Option<(String, Vec<String>)> {
    match query {
        Query::SpanTerm { field, value } => Some((field.clone(), vec![value.as_str()?.to_string()])),
        Query::SpanOr { clauses } => {
            let mut field_name: Option<String> = None;
            let mut alternatives = Vec::new();
            for clause in clauses {
                let (field, nested_alternatives) = span_near_single_clause_alternatives(clause)?;
                match &field_name {
                    Some(existing) if existing != &field => return None,
                    None => field_name = Some(field),
                    _ => {}
                }
                alternatives.extend(nested_alternatives);
            }
            Some((field_name?, alternatives))
        }
        _ => None,
    }
}

fn span_near_value_matches(
    field_value: &Value,
    alternatives: &[Vec<String>],
    slop: usize,
    in_order: bool,
) -> bool {
    match field_value {
        Value::Array(items) => items
            .iter()
            .any(|item| span_near_value_matches(item, alternatives, slop, in_order)),
        Value::String(text) => {
            let tokens = tokenize_phrase_text(text);
            if tokens.is_empty() || alternatives.is_empty() {
                return false;
            }
            if in_order {
                span_near_in_order_matches(&tokens, alternatives, slop)
            } else {
                span_near_unordered_matches(&tokens, alternatives, slop)
            }
        }
        _ => false,
    }
}

fn span_near_in_order_matches(tokens: &[String], alternatives: &[Vec<String>], slop: usize) -> bool {
    for start in 0..tokens.len() {
        if !alternatives[0].iter().any(|term| term == &tokens[start]) {
            continue;
        }
        let mut last = start;
        let mut total_gap = 0usize;
        let mut matched = true;
        for clause_alternatives in &alternatives[1..] {
            let mut next_match = None;
            for idx in (last + 1)..tokens.len() {
                if clause_alternatives.iter().any(|term| term == &tokens[idx]) {
                    next_match = Some(idx);
                    break;
                }
            }
            let Some(next_idx) = next_match else {
                matched = false;
                break;
            };
            total_gap = total_gap.saturating_add(next_idx.saturating_sub(last + 1));
            if total_gap > slop {
                matched = false;
                break;
            }
            last = next_idx;
        }
        if matched {
            return true;
        }
    }
    false
}

fn span_near_unordered_matches(tokens: &[String], alternatives: &[Vec<String>], slop: usize) -> bool {
    let required = alternatives.len();
    if required == 0 {
        return false;
    }
    let max_window = required.saturating_add(slop);
    for start in 0..tokens.len() {
        let end = (start + max_window).min(tokens.len());
        let window = &tokens[start..end];
        if alternatives
            .iter()
            .all(|clause_alternatives| window.iter().any(|token| clause_alternatives.iter().any(|term| term == token)))
        {
            return true;
        }
    }
    false
}

fn text_tokens_from_value(value: &Value) -> Vec<String> {
    match value {
        Value::String(text) => tokenize_phrase_text(text),
        Value::Array(items) => items.iter().flat_map(text_tokens_from_value).collect(),
        _ => Vec::new(),
    }
}

fn matches_simple_query_string_query(
    id: &str,
    source: &Value,
    fields: Option<&[String]>,
    query: &str,
) -> bool {
    let effective_fields = simple_query_string_effective_fields_from_source(id, source, fields);
    let query_tokens = tokenize_query_string_required_terms(query);
    matched_query_token_count_across_fields(id, source, &effective_fields, query)
        == query_tokens.len()
}

fn simple_query_string_effective_fields(hit: &SearchHit, fields: Option<&[String]>) -> Vec<String> {
    fields
        .map(|fields| fields.to_vec())
        .unwrap_or_else(|| {
            let mut effective_fields = hit
                .source
                .as_object()
                .map(|object| object.keys().cloned().collect::<Vec<_>>())
                .unwrap_or_default();
            effective_fields.push("_id".to_string());
            effective_fields
        })
}

fn simple_query_string_effective_fields_from_source(
    _id: &str,
    source: &Value,
    fields: Option<&[String]>,
) -> Vec<String> {
    fields
        .map(|fields| fields.to_vec())
        .unwrap_or_else(|| {
            let mut effective_fields = source
                .as_object()
                .map(|object| object.keys().cloned().collect::<Vec<_>>())
                .unwrap_or_default();
            effective_fields.push("_id".to_string());
            effective_fields
        })
}

fn phrase_prefix_window_matches(window: &[String], query_tokens: &[String]) -> bool {
    if window.len() != query_tokens.len() || query_tokens.is_empty() {
        return false;
    }
    let last_index = query_tokens.len() - 1;
    query_tokens[..last_index]
        .iter()
        .zip(&window[..last_index])
        .all(|(query_token, field_token)| query_token == field_token)
        && window[last_index].starts_with(&query_tokens[last_index])
}

fn tokenize_phrase_text(text: &str) -> Vec<String> {
    text.split(|ch: char| !ch.is_alphanumeric())
        .filter(|token| !token.is_empty())
        .map(|token| token.to_lowercase())
        .collect()
}

fn matches_range_query(value: &Value, bounds: &RangeBounds) -> bool {
    range_query_matching_value_count(value, bounds) > 0
}

fn range_query_matching_value_count(value: &Value, bounds: &RangeBounds) -> usize {
    if let Value::Array(items) = value {
        return items
            .iter()
            .map(|item| range_query_matching_value_count(item, bounds))
            .sum();
    }

    usize::from(
        bound_matches(value, bounds.gt.as_ref(), |ordering| ordering.is_gt())
        && bound_matches(value, bounds.gte.as_ref(), |ordering| ordering.is_ge())
        && bound_matches(value, bounds.lt.as_ref(), |ordering| ordering.is_lt())
        && bound_matches(value, bounds.lte.as_ref(), |ordering| ordering.is_le()),
    )
}

fn text_range_candidate_matches_token_bound(text: &str, bounds: &RangeBounds) -> bool {
    let tokens = tokenize_phrase_text(text);
    if tokens.is_empty() {
        return false;
    }
    [
        bounds.gt.as_ref(),
        bounds.gte.as_ref(),
        bounds.lt.as_ref(),
        bounds.lte.as_ref(),
    ]
    .into_iter()
    .flatten()
    .filter_map(Value::as_str)
    .flat_map(tokenize_phrase_text)
    .any(|bound_token| tokens.iter().any(|token| token == &bound_token))
}

fn value_matches_exists_query(value: &Value) -> bool {
    exists_query_matching_value_count(value) > 0
}

fn exists_query_matching_value_count(value: &Value) -> usize {
    match value {
        Value::Null => 0,
        Value::Array(values) => values.iter().map(exists_query_matching_value_count).sum(),
        _ => 1,
    }
}

fn bound_matches(
    value: &Value,
    bound: Option<&Value>,
    predicate: impl FnOnce(std::cmp::Ordering) -> bool,
) -> bool {
    let Some(bound) = bound else {
        return true;
    };

    compare_values(value, bound).is_some_and(predicate)
}

fn compare_values(left: &Value, right: &Value) -> Option<std::cmp::Ordering> {
    match (left, right) {
        (Value::Number(left), Value::Number(right)) => left
            .as_f64()
            .zip(right.as_f64())
            .and_then(|(left, right)| left.partial_cmp(&right)),
        (Value::Bool(left), Value::Bool(right)) => Some(left.cmp(right)),
        (Value::String(left), Value::String(right)) => {
            let left_dt = parse_tantivy_datetime_value(&Value::String(left.clone()));
            let right_dt = parse_tantivy_datetime_value(&Value::String(right.clone()));
            match (left_dt, right_dt) {
                (Some(left_dt), Some(right_dt)) => Some(left_dt.cmp(&right_dt)),
                _ => Some(left.cmp(right)),
            }
        }
        _ => None,
    }
}

fn parse_offset_datetime_value(value: &Value) -> Option<OffsetDateTime> {
    match value {
        Value::String(text) => OffsetDateTime::parse(text, &Rfc3339).ok(),
        Value::Number(number) => number
            .as_i64()
            .or_else(|| number.as_u64().and_then(|value| i64::try_from(value).ok()))
            .and_then(|epoch_millis| {
                OffsetDateTime::from_unix_timestamp_nanos(i128::from(epoch_millis).saturating_mul(1_000_000)).ok()
            }),
        _ => None,
    }
}

fn normalize_date_histogram_interval(interval: &str) -> Option<&'static str> {
    match interval {
        "minute" | "1m" => Some("minute"),
        "hour" | "1h" => Some("hour"),
        "day" | "1d" => Some("day"),
        "week" | "1w" => Some("week"),
        "month" | "1M" => Some("month"),
        "year" | "1y" => Some("year"),
        _ => None,
    }
}

fn date_histogram_interval_rank(interval: &str) -> Option<usize> {
    match normalize_date_histogram_interval(interval)? {
        "minute" => Some(0),
        "hour" => Some(1),
        "day" => Some(2),
        "week" => Some(3),
        "month" => Some(4),
        "year" => Some(5),
        _ => None,
    }
}

fn coarsest_date_histogram_interval(left: &str, right: &str) -> Option<&'static str> {
    const INTERVALS: [&str; 6] = ["minute", "hour", "day", "week", "month", "year"];
    let left_rank = date_histogram_interval_rank(left)?;
    let right_rank = date_histogram_interval_rank(right)?;
    Some(INTERVALS[left_rank.max(right_rank)])
}

fn choose_auto_date_histogram_interval_from_values<'a, I>(
    values: I,
    target_buckets: usize,
) -> &'static str
where
    I: IntoIterator<Item = &'a Value>,
{
    const CANDIDATES: [&str; 6] = ["minute", "hour", "day", "week", "month", "year"];
    let values = values.into_iter().collect::<Vec<_>>();
    let target_buckets = target_buckets.max(1);
    for interval in CANDIDATES {
        let bucket_count = values
            .iter()
            .flat_map(|value| {
                distinct_date_histogram_buckets(value, interval)
                    .into_iter()
                    .map(|(bucket, _)| bucket)
            })
            .collect::<std::collections::BTreeSet<_>>()
            .len();
        if bucket_count < target_buckets || (target_buckets == 1 && bucket_count <= target_buckets)
        {
            return interval;
        }
    }
    "year"
}

fn rebucket_date_histogram_buckets_to_interval(
    buckets: &[Value],
    target_interval: &str,
    aggregation_map: Option<&AggregationMap>,
) -> Vec<Value> {
    let mut counts = std::collections::BTreeMap::<
        i64,
        (
            String,
            u64,
            serde_json::Map<String, Value>,
            BTreeMap<String, u64>,
            BTreeMap<String, std::collections::BTreeSet<String>>,
            BTreeMap<String, Vec<f64>>,
        ),
    >::new();
    for bucket in buckets {
        let key_as_string = bucket.get("key_as_string");
        let doc_count = bucket.get("doc_count").and_then(|value| value.as_u64()).unwrap_or(0);
        let Some(key_as_string) = key_as_string else {
            continue;
        };
        let Some((bucket_key, bucket_string)) = date_histogram_bucket(key_as_string, target_interval)
        else {
            continue;
        };
        let entry = counts.entry(bucket_key).or_insert((
            bucket_string,
            0,
            serde_json::Map::new(),
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
        ));
        entry.1 = entry.1.saturating_add(doc_count);
        if let Some(aggregation_map) = aggregation_map {
            let (avg_count_hints, cardinality_value_hints, percentile_value_hints) =
                plugin_nested_reduce_hints_from_value(bucket);
            merge_native_aggregation_response(
                &mut entry.2,
                aggregation_map,
                Value::Object(array_bucketed_plugin_nested_fields(bucket)),
                &avg_count_hints,
                &cardinality_value_hints,
                &percentile_value_hints,
            );
            for (name, count) in avg_count_hints {
                *entry.3.entry(name).or_default() += count;
            }
            for (name, values) in cardinality_value_hints {
                entry.4.entry(name).or_default().extend(values);
            }
            for (name, values) in percentile_value_hints {
                entry.5.entry(name).or_default().extend(values);
            }
        }
    }
    counts
        .into_iter()
        .map(|(key, (key_as_string, doc_count, nested_merged, avg_count_hints, cardinality_value_hints, percentile_value_hints))| {
            let object = object_value_with_fields(
                [
                    ("key".to_string(), Value::from(key)),
                    ("key_as_string".to_string(), Value::String(key_as_string)),
                    ("doc_count".to_string(), Value::from(doc_count)),
                ]
                .into_iter()
                .collect(),
            )
            .as_object()
            .cloned()
            .unwrap_or_default();
            if aggregation_map.is_some() {
                plugin_bucket_value_from_existing_fields(
                    object,
                    Some(Value::Object(nested_merged)),
                    Some((
                        avg_count_hints,
                        cardinality_value_hints,
                        percentile_value_hints,
                    )),
                )
            } else {
                Value::Object(object)
            }
        })
        .collect::<Vec<_>>()
}

fn coarsen_auto_date_histogram_buckets_until_target(
    buckets: &[Value],
    interval: &str,
    target_buckets: usize,
    aggregation_map: Option<&AggregationMap>,
) -> (String, Vec<Value>) {
    const INTERVALS: [&str; 6] = ["minute", "hour", "day", "week", "month", "year"];
    let target_buckets = target_buckets.max(1);
    let mut current_interval = normalize_date_histogram_interval(interval)
        .unwrap_or("year")
        .to_string();
    let mut current_buckets = buckets.to_vec();
    let mut rank = date_histogram_interval_rank(&current_interval).unwrap_or(INTERVALS.len() - 1);
    while current_buckets.len() > target_buckets && rank + 1 < INTERVALS.len() {
        rank += 1;
        current_interval = INTERVALS[rank].to_string();
        current_buckets = rebucket_date_histogram_buckets_to_interval(
            &current_buckets,
            &current_interval,
            aggregation_map,
        );
    }
    (current_interval, current_buckets)
}

fn date_histogram_bucket(value: &Value, interval: &str) -> Option<(i64, String)> {
    let timestamp = parse_offset_datetime_value(value)?;
    let millis = timestamp.unix_timestamp_nanos() / 1_000_000;
    date_histogram_bucket_from_epoch_millis(i64::try_from(millis).ok()?, interval)
}

fn date_histogram_bucket_from_epoch_millis(
    epoch_millis: i64,
    interval: &str,
) -> Option<(i64, String)> {
    let interval = normalize_date_histogram_interval(interval)?;
    let timestamp = OffsetDateTime::from_unix_timestamp_nanos(
        i128::from(epoch_millis).saturating_mul(1_000_000),
    )
    .ok()?;
    let year = timestamp.year();
    let month = timestamp.month() as u32;
    let day = u32::from(timestamp.day());
    let hour = timestamp.hour();
    let minute = timestamp.minute();
    match interval {
        "minute" => {
            let days = days_from_civil(year, month, day)?;
            let millis = days
                .checked_mul(86_400_000)?
                .checked_add(i64::from(hour).checked_mul(3_600_000)?)?
                .checked_add(i64::from(minute).checked_mul(60_000)?)?;
            Some((
                millis,
                format!("{year:04}-{month:02}-{day:02}T{hour:02}:{minute:02}:00.000Z"),
            ))
        }
        "hour" => {
            let days = days_from_civil(year, month, day)?;
            let millis = days
                .checked_mul(86_400_000)?
                .checked_add(i64::from(hour).checked_mul(3_600_000)?)?;
            Some((
                millis,
                format!("{year:04}-{month:02}-{day:02}T{hour:02}:00:00.000Z"),
            ))
        }
        "day" => {
            let days = days_from_civil(year, month, day)?;
            let millis = days.checked_mul(86_400_000)?;
            Some((
                millis,
                format!("{year:04}-{month:02}-{day:02}T00:00:00.000Z"),
            ))
        }
        "week" => {
            let days = days_from_civil(year, month, day)?;
            let weekday_offset = i64::from(timestamp.weekday().number_days_from_monday());
            let monday_days = days.checked_sub(weekday_offset)?;
            let millis = monday_days.checked_mul(86_400_000)?;
            let start = timestamp.date().checked_sub(time::Duration::days(weekday_offset))?;
            Some((
                millis,
                format!(
                    "{:04}-{:02}-{:02}T00:00:00.000Z",
                    start.year(),
                    start.month() as u32,
                    u32::from(start.day())
                ),
            ))
        }
        "month" => {
            let days = days_from_civil(year, month, 1)?;
            let millis = days.checked_mul(86_400_000)?;
            Some((millis, format!("{year:04}-{month:02}-01T00:00:00.000Z")))
        }
        "year" => {
            let days = days_from_civil(year, 1, 1)?;
            let millis = days.checked_mul(86_400_000)?;
            Some((millis, format!("{year:04}-01-01T00:00:00.000Z")))
        }
        _ => None,
    }
}

fn days_from_civil(year: i32, month: u32, day: u32) -> Option<i64> {
    if !(1..=12).contains(&month) || !(1..=31).contains(&day) {
        return None;
    }
    let year = year - ((month <= 2) as i32);
    let era = if year >= 0 { year } else { year - 399 } / 400;
    let yoe = year - era * 400;
    let month = month as i32;
    let day = day as i32;
    let doy = (153 * (month + if month > 2 { -3 } else { 9 }) + 2) / 5 + day - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    Some((era * 146097 + doe - 719468) as i64)
}

fn matches_prefix_query(field_value: &Value, prefix: &str, case_insensitive: bool) -> bool {
    prefix_query_matching_value_count(field_value, prefix, case_insensitive) > 0
}

fn prefix_query_matching_value_count(field_value: &Value, prefix: &str, case_insensitive: bool) -> usize {
    if let Value::Array(items) = field_value {
        return items
            .iter()
            .map(|item| prefix_query_matching_value_count(item, prefix, case_insensitive))
            .sum();
    }

    let Some(field_value) = field_value.as_str() else {
        return 0;
    };

    if case_insensitive {
        usize::from(
            field_value
                .to_lowercase()
                .starts_with(&prefix.to_lowercase()),
        )
    } else {
        usize::from(field_value.starts_with(prefix))
    }
}

fn matches_wildcard_query(field_value: &Value, pattern: &str, case_insensitive: bool) -> bool {
    wildcard_query_matching_value_count(field_value, pattern, case_insensitive) > 0
}

fn wildcard_query_matching_value_count(
    field_value: &Value,
    pattern: &str,
    case_insensitive: bool,
) -> usize {
    if let Value::Array(items) = field_value {
        return items
            .iter()
            .map(|item| wildcard_query_matching_value_count(item, pattern, case_insensitive))
            .sum();
    }

    let Some(field_value) = field_value.as_str() else {
        return 0;
    };

    if case_insensitive {
        usize::from(wildcard_matches(
            &pattern.to_lowercase(),
            &field_value.to_lowercase(),
        ))
    } else {
        usize::from(wildcard_matches(pattern, field_value))
    }
}

fn matches_regexp_query(field_value: &Value, pattern: &str, case_insensitive: bool) -> bool {
    regexp_query_matching_value_count(field_value, pattern, case_insensitive) > 0
}

fn regexp_query_matching_value_count(field_value: &Value, pattern: &str, case_insensitive: bool) -> usize {
    if let Value::Array(items) = field_value {
        return items
            .iter()
            .map(|item| regexp_query_matching_value_count(item, pattern, case_insensitive))
            .sum();
    }

    let Some(field_value) = field_value.as_str() else {
        return 0;
    };

    let mut builder = regex::RegexBuilder::new(&format!("^(?:{pattern})$"));
    builder.case_insensitive(case_insensitive);
    usize::from(builder.build().is_ok_and(|regex| regex.is_match(field_value)))
}

fn matches_fuzzy_query(
    field_value: &Value,
    query: &str,
    fuzziness: u8,
    prefix_length: usize,
    transpositions: bool,
) -> bool {
    fuzzy_query_matching_value_count(
        field_value,
        query,
        fuzziness,
        prefix_length,
        transpositions,
    ) > 0
}

fn fuzzy_query_matching_value_count(
    field_value: &Value,
    query: &str,
    fuzziness: u8,
    prefix_length: usize,
    transpositions: bool,
) -> usize {
    if let Value::Array(items) = field_value {
        return items
            .iter()
            .map(|item| {
                fuzzy_query_matching_value_count(
                    item,
                    query,
                    fuzziness,
                    prefix_length,
                    transpositions,
                )
            })
            .sum();
    }

    let Some(field_value) = field_value.as_str() else {
        return 0;
    };

    usize::from(fuzzy_matches_text(
        field_value,
        query,
        fuzziness,
        prefix_length,
        transpositions,
    ))
}

fn fuzzy_matches_text(
    text: &str,
    query: &str,
    fuzziness: u8,
    prefix_length: usize,
    transpositions: bool,
) -> bool {
    fuzzy_matches_candidate(text, query, fuzziness, prefix_length, transpositions)
        || text
            .split(|ch: char| !ch.is_alphanumeric())
            .filter(|token| !token.is_empty())
            .any(|token| {
                fuzzy_matches_candidate(token, query, fuzziness, prefix_length, transpositions)
            })
}

fn fuzzy_matches_candidate(
    candidate: &str,
    query: &str,
    fuzziness: u8,
    prefix_length: usize,
    transpositions: bool,
) -> bool {
    let candidate_chars = candidate.chars().collect::<Vec<_>>();
    let query_chars = query.chars().collect::<Vec<_>>();
    if prefix_length > candidate_chars.len() || prefix_length > query_chars.len() {
        return false;
    }
    if candidate_chars[..prefix_length] != query_chars[..prefix_length] {
        return false;
    }
    let candidate_suffix = &candidate_chars[prefix_length..];
    let query_suffix = &query_chars[prefix_length..];
    let distance = if transpositions {
        optimal_string_alignment_distance(candidate_suffix, query_suffix)
    } else {
        levenshtein_distance(candidate_suffix, query_suffix)
    };
    distance <= usize::from(fuzziness)
}

fn levenshtein_distance(left: &[char], right: &[char]) -> usize {
    let mut dp = vec![vec![0; right.len() + 1]; left.len() + 1];
    for (i, row) in dp.iter_mut().enumerate() {
        row[0] = i;
    }
    for j in 0..=right.len() {
        dp[0][j] = j;
    }
    for i in 1..=left.len() {
        for j in 1..=right.len() {
            let substitution_cost = usize::from(left[i - 1] != right[j - 1]);
            dp[i][j] = (dp[i - 1][j] + 1)
                .min(dp[i][j - 1] + 1)
                .min(dp[i - 1][j - 1] + substitution_cost);
        }
    }
    dp[left.len()][right.len()]
}

fn optimal_string_alignment_distance(left: &[char], right: &[char]) -> usize {
    let mut dp = vec![vec![0; right.len() + 1]; left.len() + 1];
    for (i, row) in dp.iter_mut().enumerate() {
        row[0] = i;
    }
    for j in 0..=right.len() {
        dp[0][j] = j;
    }
    for i in 1..=left.len() {
        for j in 1..=right.len() {
            let substitution_cost = usize::from(left[i - 1] != right[j - 1]);
            let mut distance = (dp[i - 1][j] + 1)
                .min(dp[i][j - 1] + 1)
                .min(dp[i - 1][j - 1] + substitution_cost);
            if i > 1
                && j > 1
                && left[i - 1] == right[j - 2]
                && left[i - 2] == right[j - 1]
            {
                distance = distance.min(dp[i - 2][j - 2] + 1);
            }
            dp[i][j] = distance;
        }
    }
    dp[left.len()][right.len()]
}

fn wildcard_matches(pattern: &str, value: &str) -> bool {
    let pattern = pattern.as_bytes();
    let value = value.as_bytes();
    let (mut pattern_index, mut value_index) = (0, 0);
    let mut star_index = None;
    let mut star_value_index = 0;

    while value_index < value.len() {
        if pattern_index < pattern.len()
            && (pattern[pattern_index] == b'?' || pattern[pattern_index] == value[value_index])
        {
            pattern_index += 1;
            value_index += 1;
        } else if pattern_index < pattern.len() && pattern[pattern_index] == b'*' {
            star_index = Some(pattern_index);
            pattern_index += 1;
            star_value_index = value_index;
        } else if let Some(star) = star_index {
            pattern_index = star + 1;
            star_value_index += 1;
            value_index = star_value_index;
        } else {
            return false;
        }
    }

    while pattern_index < pattern.len() && pattern[pattern_index] == b'*' {
        pattern_index += 1;
    }

    pattern_index == pattern.len()
}

fn regex_escape_literal(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '.' | '+' | '(' | ')' | '[' | ']' | '{' | '}' | '^' | '$' | '|' | '\\' => {
                escaped.push('\\');
                escaped.push(ch);
            }
            _ => escaped.push(ch),
        }
    }
    escaped
}

fn wildcard_pattern_to_regex(pattern: &str) -> String {
    let mut regex = String::with_capacity(pattern.len().saturating_mul(2));
    for ch in pattern.chars() {
        match ch {
            '*' => regex.push_str(".*"),
            '?' => regex.push('.'),
            '.' | '+' | '(' | ')' | '[' | ']' | '{' | '}' | '^' | '$' | '|' | '\\' => {
                regex.push('\\');
                regex.push(ch);
            }
            _ => regex.push(ch),
        }
    }
    regex
}

fn matches_bool_query(clauses: &BoolQuery, id: &str, source: &Value) -> bool {
    if !clauses
        .must
        .iter()
        .all(|query| document_matches_query(query, id, source))
    {
        return false;
    }
    if !clauses
        .filter
        .iter()
        .all(|query| document_matches_query(query, id, source))
    {
        return false;
    }
    if clauses
        .must_not
        .iter()
        .any(|query| document_matches_query(query, id, source))
    {
        return false;
    }

    let mut minimum_should_match = effective_bool_minimum_should_match(clauses) as usize;
    minimum_should_match = minimum_should_match.min(clauses.should.len());
    let matching_should_clauses = clauses
        .should
        .iter()
        .filter(|query| document_matches_query(query, id, source))
        .count();

    matching_should_clauses >= minimum_should_match
}

fn sort_hits(hits: &mut [SearchHit], sort_specs: &[SortSpec]) {
    if sort_specs.is_empty() {
        return;
    }

    hits.sort_by(|left, right| {
        for sort_spec in sort_specs {
            let ordering = compare_hits_by_sort(left, right, sort_spec);
            if !ordering.is_eq() {
                return match sort_spec.order {
                    SortOrder::Asc => ordering,
                    SortOrder::Desc => ordering.reverse(),
                };
            }
        }

        compare_search_hit_identity(left, right)
    });

    materialize_search_hit_sort_values_in_place(hits, sort_specs);
}

fn compare_search_hit_identity(left: &SearchHit, right: &SearchHit) -> std::cmp::Ordering {
    left.index
        .cmp(&right.index)
        .then_with(|| left.metadata.id.cmp(&right.metadata.id))
}

fn search_hit_sort_values_for_specs(hit: &SearchHit, sort_specs: &[SortSpec]) -> Vec<Value> {
    sort_specs
        .iter()
        .map(|sort_spec| {
            if let Some(script) = &sort_spec.script {
                return evaluate_sort_script(&hit.source, script)
                    .map(Value::from)
                    .unwrap_or(Value::Null);
            }
            if sort_spec.geo_origin.is_some() {
                return geo_sort_distance_value_from_source(&hit.source, sort_spec)
                    .map(Value::from)
                    .unwrap_or(Value::Null);
            }
            match sort_spec.field.as_str() {
                "_id" => Value::String(hit.metadata.id.clone()),
                "_score" => Value::from(hit.score),
                field => source_sort_value(
                    &hit.source,
                    field,
                    sort_spec.order.clone(),
                    sort_spec.mode.clone(),
                )
                .unwrap_or(Value::Null),
            }
        })
        .collect()
}

fn materialize_search_hit_sort_values_in_place(hits: &mut [SearchHit], sort_specs: &[SortSpec]) {
    if sort_specs.is_empty() {
        return;
    }
    for hit in hits {
        hit.sort = Some(Value::Array(search_hit_sort_values_for_specs(hit, sort_specs)));
    }
}

fn compare_hits_by_sort(
    left: &SearchHit,
    right: &SearchHit,
    sort_spec: &SortSpec,
) -> std::cmp::Ordering {
    if let Some(script) = &sort_spec.script {
        return compare_optional_numeric_sort_values(
            evaluate_sort_script(&left.source, script),
            evaluate_sort_script(&right.source, script),
        );
    }
    if let Some(origin) = &sort_spec.geo_origin {
        return compare_optional_numeric_sort_values(
            geo_sort_distance_value_from_source(&left.source, sort_spec),
            geo_sort_distance_value_from_source(&right.source, sort_spec),
        );
    }
    match sort_spec.field.as_str() {
        "_id" => left.metadata.id.cmp(&right.metadata.id),
        "_score" => left
            .score
            .partial_cmp(&right.score)
            .unwrap_or(std::cmp::Ordering::Equal),
        field => compare_optional_owned_sort_values(
            source_sort_value(
                &left.source,
                field,
                sort_spec.order.clone(),
                sort_spec.mode.clone(),
            ),
            source_sort_value(
                &right.source,
                field,
                sort_spec.order.clone(),
                sort_spec.mode.clone(),
            ),
        ),
    }
}

fn plugin_top_metrics_fields(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<Vec<String>> {
    match plugin.params.get("metrics") {
        Some(Value::Object(object)) => object
            .get("field")
            .and_then(Value::as_str)
            .filter(|field| !field.is_empty())
            .map(|field| vec![field.to_string()]),
        Some(Value::Array(values)) => {
            if values.is_empty() {
                return None;
            }
            values
                .iter()
                .map(|value| {
                    value
                        .as_object()
                        .and_then(|object| object.get("field"))
                        .and_then(Value::as_str)
                        .filter(|field| !field.is_empty())
                        .map(ToString::to_string)
                })
                .collect::<Option<Vec<_>>>()
        }
        _ => None,
    }
}

fn plugin_top_metrics_explicit_sort_specs(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<Vec<SortSpec>> {
    let sort_value = plugin.params.get("sort")?;
    let expected_len = match sort_value {
        Value::Array(values) => values.len(),
        Value::Object(_) => 1,
        _ => 0,
    };
    if expected_len == 0 {
        return None;
    }
    let sort_specs = parse_plugin_top_hits_sort_specs(sort_value);
    if sort_specs.len() == expected_len {
        Some(sort_specs)
    } else {
        None
    }
}

fn plugin_param_exists(plugin: &os_query_dsl::PluginAggregation, name: &str) -> bool {
    plugin
        .params
        .as_object()
        .map_or(false, |params| params.contains_key(name))
}

fn plugin_top_metrics_size(plugin: &os_query_dsl::PluginAggregation) -> Option<usize> {
    if plugin_param_exists(plugin, "size") {
        plugin_usize_param(plugin, "size")
    } else {
        Some(1)
    }
}

fn plugin_rare_terms_max_doc_count(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<u64> {
    if plugin_param_exists(plugin, "max_doc_count") {
        plugin.params.get("max_doc_count").and_then(|value| value.as_u64())
    } else {
        Some(1)
    }
}

fn plugin_terms_family_order_param(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<(&'static str, SortOrder)> {
    if !plugin_param_exists(plugin, "order") {
        return Some(match plugin.kind.as_str() {
            "significant_terms" | "significant_text" => ("_score", SortOrder::Desc),
            "rare_terms" => ("_count", SortOrder::Asc),
            _ => ("_count", SortOrder::Desc),
        });
    }
    let order = plugin.params.get("order").and_then(Value::as_object)?;
    if order.len() != 1 {
        return None;
    }
    let (field, direction) = order.iter().next()?;
    let valid_field = match plugin.kind.as_str() {
        "significant_terms" | "significant_text" => {
            matches!(field.as_str(), "_score" | "_key" | "_count")
        }
        "terms" | "multi_terms" | "rare_terms" => {
            matches!(field.as_str(), "_key" | "_count")
        }
        _ => true,
    };
    if !valid_field {
        return None;
    }
    let direction = if direction.as_str()?.eq_ignore_ascii_case("asc") {
        SortOrder::Asc
    } else {
        SortOrder::Desc
    };
    Some(match field.as_str() {
        "_score" => ("_score", direction),
        "_key" => ("_key", direction),
        "_count" => ("_count", direction),
        _ => return None,
    })
}

