fn plugin_bucket_sort_explicit_sort_values(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<Vec<Value>> {
    let sort_value = plugin.params.get("sort")?;
    let sort_values = sort_value.as_array()?;
    if sort_values.is_empty() {
        return None;
    }
    if sort_values.iter().all(|entry| {
        let Some(object) = entry.as_object() else {
            return false;
        };
        if object.len() != 1 {
            return false;
        }
        object
            .values()
            .next()
            .and_then(Value::as_str)
            .is_some_and(|order| matches!(order, "asc" | "ASC" | "desc" | "DESC"))
    }) {
        Some(sort_values.clone())
    } else {
        None
    }
}

fn plugin_bucket_sort_window(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<(usize, usize)> {
    let from = if plugin_param_exists(plugin, "from") {
        plugin_usize_param(plugin, "from")?
    } else {
        0
    };
    let size = if plugin_param_exists(plugin, "size") {
        plugin_usize_param(plugin, "size")?
    } else {
        10
    };
    Some((from, size))
}

