fn plugin_top_metrics_collection_setup(
    plugin: &os_query_dsl::PluginAggregation,
    allow_score_sort: bool,
) -> Option<(Vec<String>, Vec<SortSpec>)> {
    let metric_fields = plugin_top_metrics_fields(plugin)?;
    let sort_specs = plugin_top_metrics_explicit_sort_specs(plugin)?;
    plugin_top_metrics_size(plugin)?;
    if !allow_score_sort && sort_specs.iter().any(|spec| spec.field == "_score") {
        return None;
    }
    Some((metric_fields, sort_specs))
}

fn compare_document_sources_by_sort_specs(
    left_id: &str,
    left_source: &Value,
    right_id: &str,
    right_source: &Value,
    sort_specs: &[SortSpec],
) -> std::cmp::Ordering {
    for sort_spec in sort_specs {
        let ordering = if let Some(script) = &sort_spec.script {
            compare_optional_numeric_sort_values(
                evaluate_sort_script(left_source, script),
                evaluate_sort_script(right_source, script),
            )
        } else if sort_spec.geo_origin.is_some() {
            compare_optional_numeric_sort_values(
                geo_sort_distance_value_from_source(left_source, sort_spec),
                geo_sort_distance_value_from_source(right_source, sort_spec),
            )
        } else {
            match sort_spec.field.as_str() {
                "_id" => left_id.cmp(right_id),
                field => compare_optional_owned_sort_values(
                    source_sort_value(
                        left_source,
                        field,
                        sort_spec.order.clone(),
                        sort_spec.mode.clone(),
                    ),
                    source_sort_value(
                        right_source,
                        field,
                        sort_spec.order.clone(),
                        sort_spec.mode.clone(),
                    ),
                ),
            }
        };
        if !ordering.is_eq() {
            return match sort_spec.order {
                SortOrder::Asc => ordering,
                SortOrder::Desc => ordering.reverse(),
            };
        }
    }
    left_id.cmp(right_id)
}

fn geo_sort_distance_value_from_source(source: &Value, sort_spec: &SortSpec) -> Option<f64> {
    let origin = sort_spec.geo_origin.as_ref()?;
    let distances = geo_point_source_values(source, &sort_spec.field)
        .into_iter()
        .map(|(lat, lon)| haversine_distance_meters(origin.lat, origin.lon, lat, lon))
        .collect::<Vec<_>>();
    if distances.is_empty() {
        return None;
    }
    if let Some(mode) = &sort_spec.mode {
        return match mode {
            os_engine::SortMode::Avg => {
                Some(distances.iter().sum::<f64>() / (distances.len() as f64))
            }
            os_engine::SortMode::Sum => Some(distances.iter().sum::<f64>()),
            os_engine::SortMode::Min => distances.into_iter().reduce(f64::min),
            os_engine::SortMode::Max => distances.into_iter().reduce(f64::max),
        };
    }
    match sort_spec.order {
        SortOrder::Asc => distances.into_iter().reduce(f64::min),
        SortOrder::Desc => distances.into_iter().reduce(f64::max),
    }
}

fn top_metrics_sort_value_from_source(source: &Value, sort_spec: &SortSpec) -> Value {
    if let Some(script) = &sort_spec.script {
        return evaluate_sort_script(source, script)
            .map(Value::from)
            .unwrap_or(Value::Null);
    }
    if sort_spec.geo_origin.is_some() {
        return geo_sort_distance_value_from_source(source, sort_spec)
            .map(Value::from)
            .unwrap_or(Value::Null);
    }
    source_sort_value(
        source,
        &sort_spec.field,
        sort_spec.order.clone(),
        sort_spec.mode.clone(),
    )
    .unwrap_or(Value::Null)
}

fn top_metrics_sort_values_for_document(
    id: &str,
    source: &Value,
    sort_specs: &[SortSpec],
) -> Vec<Value> {
    sort_specs
        .iter()
        .map(|sort_spec| match sort_spec.field.as_str() {
            "_id" => Value::String(id.to_string()),
            _ => top_metrics_sort_value_from_source(source, sort_spec),
        })
        .collect()
}

fn top_metrics_sort_values_for_hit(hit: &SearchHit, sort_specs: &[SortSpec]) -> Vec<Value> {
    sort_specs
        .iter()
        .map(|sort_spec| match sort_spec.field.as_str() {
            "_id" => Value::String(hit.metadata.id.to_string()),
            "_score" => Value::from(hit.score),
            _ => top_metrics_sort_value_from_source(&hit.source, sort_spec),
        })
        .collect()
}

fn top_metrics_metrics_object(source: &Value, fields: &[String]) -> Value {
    Value::Object(
        fields
            .iter()
            .map(|field| {
                (
                    field.clone(),
                    source_value_for_highlight_field(source, field)
                        .cloned()
                        .unwrap_or(Value::Null),
                )
            })
            .collect(),
    )
}

fn top_metrics_entry_for_document(
    index_name: &str,
    document: &StoredDocument,
    metric_fields: &[String],
    sort_specs: &[SortSpec],
) -> Value {
    serde_json::json!({
        "sort": top_metrics_sort_values_for_document(
            &document.metadata.id,
            &document.source,
            sort_specs,
        ),
        "metrics": top_metrics_metrics_object(&document.source, metric_fields),
        "_index": index_name,
        "_id": document.metadata.id
    })
}

fn top_metrics_entry_for_hit(
    hit: &SearchHit,
    metric_fields: &[String],
    sort_specs: &[SortSpec],
) -> Value {
    serde_json::json!({
        "sort": top_metrics_sort_values_for_hit(hit, sort_specs),
        "metrics": top_metrics_metrics_object(&hit.source, metric_fields),
        "_index": hit.index,
        "_id": hit.metadata.id
    })
}

fn truncate_top_metrics_entries(
    entries: &mut Vec<Value>,
    plugin: &os_query_dsl::PluginAggregation,
) {
    entries.sort_by(|left, right| compare_top_metrics_entries(left, right, plugin));
    let Some(size) = plugin_top_metrics_size(plugin) else {
        entries.clear();
        return;
    };
    entries.truncate(size);
}

fn compare_top_metrics_entries(
    left: &Value,
    right: &Value,
    plugin: &os_query_dsl::PluginAggregation,
) -> std::cmp::Ordering {
    let left_sort = left
        .get("sort")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let right_sort = right
        .get("sort")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    for (index, sort_spec) in plugin_top_metrics_explicit_sort_specs(plugin)
        .unwrap_or_default()
        .iter()
        .enumerate()
    {
        let ordering = compare_optional_owned_sort_values(
            left_sort.get(index).cloned(),
            right_sort.get(index).cloned(),
        );
        if !ordering.is_eq() {
            return match sort_spec.order {
                SortOrder::Asc => ordering,
                SortOrder::Desc => ordering.reverse(),
            };
        }
    }
    let left_metrics = left.get("metrics").cloned().unwrap_or(Value::Null);
    let right_metrics = right.get("metrics").cloned().unwrap_or(Value::Null);
    let metrics_ordering = serde_json::to_string(&left_metrics)
        .unwrap_or_else(|_| left_metrics.to_string())
        .cmp(
            &serde_json::to_string(&right_metrics)
                .unwrap_or_else(|_| right_metrics.to_string()),
        );
    if !metrics_ordering.is_eq() {
        return metrics_ordering;
    }
    let left_index = left
        .get("_index")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let right_index = right
        .get("_index")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let left_id = left.get("_id").and_then(Value::as_str).unwrap_or_default();
    let right_id = right.get("_id").and_then(Value::as_str).unwrap_or_default();
    left_index.cmp(right_index).then_with(|| left_id.cmp(right_id))
}

fn compare_top_metrics_document_candidates(
    index_name: &str,
    left: &StoredDocument,
    right: &StoredDocument,
    plugin: &os_query_dsl::PluginAggregation,
) -> std::cmp::Ordering {
    let Some(metric_fields) = plugin_top_metrics_fields(plugin) else {
        return std::cmp::Ordering::Equal;
    };
    let sort_specs = plugin_top_metrics_explicit_sort_specs(plugin).unwrap_or_default();
    let left_entry = top_metrics_entry_for_document(index_name, left, &metric_fields, &sort_specs);
    let right_entry =
        top_metrics_entry_for_document(index_name, right, &metric_fields, &sort_specs);
    compare_top_metrics_entries(&left_entry, &right_entry, plugin)
}

fn compare_top_metrics_hit_candidates(
    left: &SearchHit,
    right: &SearchHit,
    plugin: &os_query_dsl::PluginAggregation,
) -> std::cmp::Ordering {
    let Some(metric_fields) = plugin_top_metrics_fields(plugin) else {
        return std::cmp::Ordering::Equal;
    };
    let sort_specs = plugin_top_metrics_explicit_sort_specs(plugin).unwrap_or_default();
    let left_entry = top_metrics_entry_for_hit(left, &metric_fields, &sort_specs);
    let right_entry = top_metrics_entry_for_hit(right, &metric_fields, &sort_specs);
    compare_top_metrics_entries(&left_entry, &right_entry, plugin)
}

fn collect_plugin_top_metrics_aggregation_from_documents(
    index_name: &str,
    documents: &[&StoredDocument],
    plugin: &os_query_dsl::PluginAggregation,
) -> Value {
    let Some((metric_fields, sort_specs)) = plugin_top_metrics_collection_setup(plugin, false) else {
        return collect_plugin_aggregation_placeholder(plugin);
    };
    let mut top_entries = documents
        .iter()
        .copied()
        .map(|document| top_metrics_entry_for_document(index_name, document, &metric_fields, &sort_specs))
        .collect::<Vec<_>>();
    if top_entries.is_empty() {
        return plugin_top_metrics_aggregation_value(plugin, Vec::new());
    }
    truncate_top_metrics_entries(&mut top_entries, plugin);
    plugin_top_metrics_aggregation_value(plugin, top_entries)
}

fn collect_plugin_top_metrics_aggregation_from_hits(
    hits: &[SearchHit],
    plugin: &os_query_dsl::PluginAggregation,
) -> Value {
    let Some((metric_fields, sort_specs)) = plugin_top_metrics_collection_setup(plugin, true) else {
        return collect_plugin_aggregation_placeholder(plugin);
    };
    let mut top_entries = hits
        .iter()
        .map(|hit| top_metrics_entry_for_hit(hit, &metric_fields, &sort_specs))
        .collect::<Vec<_>>();
    if top_entries.is_empty() {
        return plugin_top_metrics_aggregation_value(plugin, Vec::new());
    }
    truncate_top_metrics_entries(&mut top_entries, plugin);
    plugin_top_metrics_aggregation_value(plugin, top_entries)
}

fn compare_optional_owned_sort_values(left: Option<Value>, right: Option<Value>) -> std::cmp::Ordering {
    match (left.as_ref(), right.as_ref()) {
        (Some(left), Some(right)) => {
            compare_values(left, right).unwrap_or(std::cmp::Ordering::Equal)
        }
        (Some(_), None) => std::cmp::Ordering::Less,
        (None, Some(_)) => std::cmp::Ordering::Greater,
        (None, None) => std::cmp::Ordering::Equal,
    }
}

fn compare_relevance_hits(left: &SearchHit, right: &SearchHit) -> std::cmp::Ordering {
    right
        .score
        .partial_cmp(&left.score)
        .unwrap_or(std::cmp::Ordering::Equal)
        .then_with(|| compare_search_hit_identity(left, right))
}

fn compare_hits_for_page(
    left: &SearchHit,
    right: &SearchHit,
    sort_specs: &[SortSpec],
) -> std::cmp::Ordering {
    if sort_specs.is_empty() {
        return compare_relevance_hits(left, right);
    }
    for sort_spec in sort_specs {
        let ordering = compare_hits_by_sort(left, right, sort_spec);
        if !ordering.is_eq() {
            return match sort_spec.order {
                SortOrder::Asc => ordering,
                SortOrder::Desc => ordering.reverse(),
            };
        }
    }
    compare_search_hit_identity(left, right)
}

fn retain_top_hits_for_requested_page(
    merged_hits: &mut Vec<SearchHit>,
    index_hits: Vec<SearchHit>,
    sort_specs: &[SortSpec],
    page_limit: usize,
) {
    if page_limit == 0 {
        return;
    }
    for hit in index_hits {
        StoredIndex::insert_bounded_page_hit(merged_hits, hit, sort_specs, page_limit);
    }
}

fn finalize_hits_for_requested_page(
    mut merged_hits: Vec<SearchHit>,
    sort_specs: &[SortSpec],
    from: usize,
    size: usize,
) -> Vec<SearchHit> {
    if sort_uses_default_relevance_order(sort_specs) {
        merged_hits.sort_by(compare_relevance_hits);
    } else if !sort_specs.is_empty() {
        if merged_hits.len() > 1 {
            sort_hits(&mut merged_hits, sort_specs);
        } else {
            materialize_search_hit_sort_values_in_place(&mut merged_hits, sort_specs);
        }
    }
    if size == 0 {
        Vec::new()
    } else {
        merged_hits
            .into_iter()
            .skip(from)
            .take(size)
            .collect::<Vec<_>>()
    }
}

fn standard_search_response(
    total_hits: u64,
    hits: impl IntoIterator<Item = SearchHit>,
    aggregations: Value,
    query_phase_detail: &'static str,
    fetch_phase: SearchPhaseResult,
    fetch_subphases: Vec<FetchSubphaseResult>,
) -> SearchResponse {
    SearchResponse::from_hits_iter(total_hits, hits, aggregations)
        .with_phase_results(vec![
            SearchPhaseResult::completed(
                SearchPhase::CanMatch,
                "validated target indices",
            ),
            SearchPhaseResult::completed(SearchPhase::Query, query_phase_detail),
            fetch_phase,
            SearchPhaseResult::skipped(
                SearchPhase::Dfs,
                "single-node execution does not require distributed DFS",
            ),
        ])
        .with_fetch_subphases(fetch_subphases)
}


fn source_sort_value(
    source: &Value,
    field: &str,
    order: SortOrder,
    mode: Option<os_engine::SortMode>,
) -> Option<Value> {
    source
        .get(field)
        .cloned()
        .or_else(|| nested_source_sort_value(source, field, order, mode))
}

fn nested_source_sort_value(
    source: &Value,
    field: &str,
    order: SortOrder,
    mode: Option<os_engine::SortMode>,
) -> Option<Value> {
    if field.split('.').count() < 2 {
        return None;
    }
    let path = field.split('.').collect::<Vec<_>>();
    let mut values = Vec::new();
    collect_nested_sort_values(source, &path, &mut values);
    let numeric_values = values
        .iter()
        .filter_map(Value::as_f64)
        .collect::<Vec<_>>();

    if let Some(mode) = mode {
        match mode {
            os_engine::SortMode::Avg => {
                if numeric_values.is_empty() {
                    return None;
                }
                return Some(Value::from(
                    numeric_values.iter().sum::<f64>() / (numeric_values.len() as f64),
                ));
            }
            os_engine::SortMode::Sum => {
                if numeric_values.is_empty() {
                    return None;
                }
                return Some(Value::from(numeric_values.iter().sum::<f64>()));
            }
            os_engine::SortMode::Min => {
                let mut best: Option<Value> = None;
                for candidate in &values {
                    if candidate.is_null() {
                        continue;
                    }
                    match &best {
                        None => best = Some(candidate.clone()),
                        Some(current) => {
                            let Some(ordering) = compare_values(candidate, current) else {
                                continue;
                            };
                            if ordering.is_lt() {
                                best = Some(candidate.clone());
                            }
                        }
                    }
                }
                return best;
            }
            os_engine::SortMode::Max => {
                let mut best: Option<Value> = None;
                for candidate in &values {
                    if candidate.is_null() {
                        continue;
                    }
                    match &best {
                        None => best = Some(candidate.clone()),
                        Some(current) => {
                            let Some(ordering) = compare_values(candidate, current) else {
                                continue;
                            };
                            if ordering.is_gt() {
                                best = Some(candidate.clone());
                            }
                        }
                    }
                }
                return best;
            }
        }
    }

    let mut best: Option<Value> = None;
    for candidate in values {
        if candidate.is_null() {
            continue;
        }
        match &best {
            None => best = Some(candidate),
            Some(current) => {
                let Some(ordering) = compare_values(&candidate, current) else {
                    continue;
                };
                let take_candidate = match order {
                    SortOrder::Asc => ordering.is_lt(),
                    SortOrder::Desc => ordering.is_gt(),
                };
                if take_candidate {
                    best = Some(candidate);
                }
            }
        }
    }
    best
}

fn collect_nested_sort_values(value: &Value, path: &[&str], out: &mut Vec<Value>) {
    if path.is_empty() {
        match value {
            Value::Array(items) => {
                for item in items {
                    collect_nested_sort_values(item, path, out);
                }
            }
            _ => out.push(value.clone()),
        }
        return;
    }
    match value {
        Value::Object(object) => {
            if let Some(next) = object.get(path[0]) {
                collect_nested_sort_values(next, &path[1..], out);
            }
        }
        Value::Array(items) => {
            for item in items {
                collect_nested_sort_values(item, path, out);
            }
        }
        _ => {}
    }
}

fn compare_optional_numeric_sort_values(left: Option<f64>, right: Option<f64>) -> std::cmp::Ordering {
    match (left, right) {
        (Some(left), Some(right)) => left
            .partial_cmp(&right)
            .unwrap_or(std::cmp::Ordering::Equal),
        (Some(_), None) => std::cmp::Ordering::Less,
        (None, Some(_)) => std::cmp::Ordering::Greater,
        (None, None) => std::cmp::Ordering::Equal,
    }
}

enum SortScriptBinaryOp {
    Add,
    Sub,
    Mul,
    Div,
    Mod,
}

fn evaluate_sort_script(source: &Value, script: &os_engine::SortScript) -> Option<f64> {
    let (value, rest) = parse_sort_script_add_sub(source, script, script.source.trim())?;
    skip_sort_script_whitespace(rest).is_empty().then_some(value)
}

fn parse_sort_script_add_sub<'a>(
    source: &Value,
    script: &os_engine::SortScript,
    expression: &'a str,
) -> Option<(f64, &'a str)> {
    let (mut value, mut rest) = parse_sort_script_mul_div(source, script, expression)?;
    loop {
        let trimmed = skip_sort_script_whitespace(rest);
        if !matches!(trimmed.chars().next(), Some('+' | '-')) {
            return Some((value, trimmed));
        }
        let Some(operator) = trimmed.chars().next() else {
            return Some((value, trimmed));
        };
        let op = match operator {
            '+' => SortScriptBinaryOp::Add,
            '-' => SortScriptBinaryOp::Sub,
            _ => return Some((value, trimmed)),
        };
        let (rhs, next_rest) =
            parse_sort_script_mul_div(source, script, &trimmed[operator.len_utf8()..])?;
        value = match op {
            SortScriptBinaryOp::Add => value + rhs,
            SortScriptBinaryOp::Sub => value - rhs,
            SortScriptBinaryOp::Mul | SortScriptBinaryOp::Div | SortScriptBinaryOp::Mod => {
                unreachable!()
            }
        };
        rest = next_rest;
    }
}

fn parse_sort_script_mul_div<'a>(
    source: &Value,
    script: &os_engine::SortScript,
    expression: &'a str,
) -> Option<(f64, &'a str)> {
    let (mut value, mut rest) = parse_sort_script_unary(source, script, expression)?;
    loop {
        let trimmed = skip_sort_script_whitespace(rest);
        if !matches!(trimmed.chars().next(), Some('*' | '/' | '%')) {
            return Some((value, trimmed));
        }
        let Some(operator) = trimmed.chars().next() else {
            return Some((value, trimmed));
        };
        let op = match operator {
            '*' => SortScriptBinaryOp::Mul,
            '/' => SortScriptBinaryOp::Div,
            '%' => SortScriptBinaryOp::Mod,
            _ => return Some((value, trimmed)),
        };
        let (rhs, next_rest) =
            parse_sort_script_unary(source, script, &trimmed[operator.len_utf8()..])?;
        value = match op {
            SortScriptBinaryOp::Mul => value * rhs,
            SortScriptBinaryOp::Div => {
                if rhs == 0.0 {
                    return None;
                }
                value / rhs
            }
            SortScriptBinaryOp::Mod => {
                if rhs == 0.0 {
                    return None;
                }
                value % rhs
            }
            SortScriptBinaryOp::Add | SortScriptBinaryOp::Sub => unreachable!(),
        };
        rest = next_rest;
    }
}

fn parse_sort_script_unary<'a>(
    source: &Value,
    script: &os_engine::SortScript,
    expression: &'a str,
) -> Option<(f64, &'a str)> {
    let expression = skip_sort_script_whitespace(expression);
    if let Some(rest) = expression.strip_prefix('-') {
        let (value, rest) = parse_sort_script_unary(source, script, rest)?;
        return Some((-value, rest));
    }
    if let Some(rest) = expression
        .strip_prefix("abs(")
        .or_else(|| expression.strip_prefix("Math.abs("))
    {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.abs(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.ceil(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.ceil(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.floor(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.floor(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.round(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.round(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.sqrt(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.sqrt(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.cbrt(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.cbrt(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.sin(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.sin(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.cos(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.cos(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.tan(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.tan(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.asin(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.asin(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.acos(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.acos(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.atan(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.atan(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.sinh(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.sinh(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.cosh(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.cosh(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.toRadians(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.to_radians(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.toDegrees(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.to_degrees(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.log(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.ln(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.log1p(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.ln_1p(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.log10(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.log10(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.log2(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.log2(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.exp(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.exp(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.exp2(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.exp2(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.fround(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((((value as f32) as f64), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.expm1(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.exp_m1(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.sign(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.signum(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.trunc(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.trunc(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.hypot(") {
        let (first, mut rest) = parse_sort_script_add_sub(source, script, rest)?;
        let mut squared_sum = first * first;
        loop {
            let trimmed = skip_sort_script_whitespace(rest);
            if let Some(next_rest) = trimmed.strip_prefix(')') {
                return Some((squared_sum.sqrt(), next_rest));
            }
            let next_rest = trimmed.strip_prefix(',')?;
            let (next_value, next_rest) = parse_sort_script_add_sub(source, script, next_rest)?;
            squared_sum += next_value * next_value;
            rest = next_rest;
        }
    }
    if let Some(rest) = expression.strip_prefix("Math.tanh(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.tanh(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.asinh(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.asinh(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.acosh(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.acosh(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.atanh(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.atanh(), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.atan2(") {
        let (left, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(',')?;
        let (right, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((left.atan2(right), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.fma(") {
        let (first, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(',')?;
        let (second, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(',')?;
        let (third, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((first.mul_add(second, third), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.imul(") {
        let (left, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(',')?;
        let (right, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((((left as i32).wrapping_mul(right as i32)) as f64, rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.clz32(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((((value as i32) as u32).leading_zeros() as f64, rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.pow(") {
        let (left, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(',')?;
        let (right, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((left.powf(right), rest));
    }
    if let Some(rest) = expression.strip_prefix("Math.clamp(") {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(',')?;
        let (min, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(',')?;
        let (max, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value.clamp(min, max), rest));
    }
    for prefix in ["Math.min(", "Math.max("] {
        if let Some(rest) = expression.strip_prefix(prefix) {
            let (mut value, mut rest) = parse_sort_script_add_sub(source, script, rest)?;
            loop {
                let trimmed = skip_sort_script_whitespace(rest);
                if let Some(next_rest) = trimmed.strip_prefix(')') {
                    return Some((value, next_rest));
                }
                let next_rest = trimmed.strip_prefix(',')?;
                let (next_value, next_rest) = parse_sort_script_add_sub(source, script, next_rest)?;
                value = if prefix == "Math.min(" {
                    value.min(next_value)
                } else {
                    value.max(next_value)
                };
                rest = next_rest;
            }
        }
    }
    if let Some(rest) = expression.strip_prefix('(') {
        let (value, rest) = parse_sort_script_add_sub(source, script, rest)?;
        let rest = skip_sort_script_whitespace(rest).strip_prefix(')')?;
        return Some((value, rest));
    }
    parse_sort_script_atom(source, script, expression)
}

fn parse_sort_script_atom<'a>(
    source: &Value,
    script: &os_engine::SortScript,
    expression: &'a str,
) -> Option<(f64, &'a str)> {
    let expression = skip_sort_script_whitespace(expression);
    if let Some(rest) = expression.strip_prefix("doc['") {
        let end = rest.find("'].value")?;
        let field = &rest[..end];
        if field.is_empty() || field.contains("'].value") || field[1..].contains('-') {
            return None;
        }
        let value = numeric_source_value(source, field)?;
        return Some((value, &rest[end + "'].value".len()..]));
    }
    if let Some(rest) = expression.strip_prefix("params.") {
        let end = rest
            .find(|character: char| {
                character.is_whitespace()
                    || matches!(character, '+' | '-' | '*' | '/' | '%' | ')' | '(' | ',')
            })
            .unwrap_or(rest.len());
        let param_name = &rest[..end];
        if param_name.is_empty() {
            return None;
        }
        let value = script.params.get(param_name).and_then(Value::as_f64)?;
        return Some((value, &rest[end..]));
    }
    let end = expression
        .find(|character: char| {
            character.is_whitespace()
                || matches!(character, '+' | '-' | '*' | '/' | '%' | ')' | '(' | ',')
        })
        .unwrap_or(expression.len());
    let token = &expression[..end];
    if !(!token.is_empty()
        && (script_sort_current_representative_math_constant_value(token).is_some()
            || token.parse::<f64>().is_ok()))
    {
        return None;
    }
    let value = script_sort_current_representative_math_constant_value(token)
        .or_else(|| token.parse::<f64>().ok())?;
    Some((value, &expression[end..]))
}

fn script_sort_current_representative_math_constant_value(token: &str) -> Option<f64> {
    Some(match token {
        "Math.PI" => std::f64::consts::PI,
        "Math.E" => std::f64::consts::E,
        "Math.LN2" => std::f64::consts::LN_2,
        "Math.LN10" => std::f64::consts::LN_10,
        "Math.LOG2E" => std::f64::consts::LOG2_E,
        "Math.LOG10E" => std::f64::consts::LOG10_E,
        "Math.SQRT1_2" => std::f64::consts::FRAC_1_SQRT_2,
        "Math.SQRT2" => std::f64::consts::SQRT_2,
        _ => return None,
    })
}

fn skip_sort_script_whitespace(expression: &str) -> &str {
    expression.trim_start()
}

fn compare_optional_geo_distance(
    left: Option<(f64, f64)>,
    right: Option<(f64, f64)>,
    origin_lat: f64,
    origin_lon: f64,
) -> std::cmp::Ordering {
    match (left, right) {
        (Some((left_lat, left_lon)), Some((right_lat, right_lon))) => haversine_distance_meters(
            origin_lat,
            origin_lon,
            left_lat,
            left_lon,
        )
        .partial_cmp(&haversine_distance_meters(
            origin_lat,
            origin_lon,
            right_lat,
            right_lon,
        ))
        .unwrap_or(std::cmp::Ordering::Equal),
        (Some(_), None) => std::cmp::Ordering::Less,
        (None, Some(_)) => std::cmp::Ordering::Greater,
        (None, None) => std::cmp::Ordering::Equal,
    }
}

fn haversine_distance_meters(
    origin_lat: f64,
    origin_lon: f64,
    target_lat: f64,
    target_lon: f64,
) -> f64 {
    let earth_radius_meters = 6_371_000.0_f64;
    let origin_lat = origin_lat.to_radians();
    let origin_lon = origin_lon.to_radians();
    let target_lat = target_lat.to_radians();
    let target_lon = target_lon.to_radians();
    let delta_lat = target_lat - origin_lat;
    let delta_lon = target_lon - origin_lon;
    let haversine = (delta_lat / 2.0).sin().powi(2)
        + origin_lat.cos() * target_lat.cos() * (delta_lon / 2.0).sin().powi(2);
    let angular_distance = 2.0 * haversine.sqrt().asin();
    earth_radius_meters * angular_distance
}

fn collect_single_aggregation_native(
    index: &StoredIndex,
    search_state: &TantivySearchState,
    searcher: &tantivy::Searcher,
    base_query: &Query,
    tantivy_query: &dyn TantivyQueryTrait,
    aggregation: &Aggregation,
    reusable: Option<&ReusableQueryContext<'_>>,
) -> EngineResult<Option<Value>> {
    let _ = (search_state, searcher, tantivy_query);
    let documents = reusable
        .and_then(|context| context.documents.clone())
        .or_else(|| {
            index
                .search_documents_for_query_native_readonly(index.name(), base_query)
                .ok()
                .flatten()
        });
    let Some(documents) = documents else {
        return Ok(None);
    };
    let mut aggregation_map = AggregationMap::new();
    aggregation_map.insert("_single".to_string(), aggregation.clone());
    let all_documents = if aggregation_map_requires_all_hits(&aggregation_map) {
        let all_documents = reusable
            .and_then(|context| context.all_documents.clone())
            .or_else(|| {
                index
                    .search_documents_for_query_native_readonly(index.name(), &Query::MatchAll)
                    .ok()
                    .flatten()
            });
        let Some(all_documents) = all_documents else {
            return Ok(None);
        };
        all_documents
    } else {
        Vec::new()
    };
    let mut value = collect_aggregations_from_documents(
        index.name(),
        &documents,
        &all_documents,
        &aggregation_map,
    );
    if let Some(object) = value.as_object_mut() {
        finalize_merged_pipeline_aggregations(object, &aggregation_map);
    }
    strip_internal_merge_surfaces(&mut value);
    Ok(value
        .as_object()
        .and_then(|object| object.get("_single"))
        .cloned())
}

fn plugin_pipeline_aggregation(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<os_query_dsl::PipelineAggregation> {
    let kind = plugin_pipeline_aggregation_kind(plugin)?;
    let buckets_path = plugin
        .params
        .get("buckets_path")
        .and_then(Value::as_str)
        .map(str::to_string)?;
    let window = plugin_pipeline_window_override(plugin, kind.clone());
    let percents = plugin_pipeline_percent_config(plugin);
    let values = plugin_pipeline_values_config(plugin);
    Some(os_query_dsl::PipelineAggregation {
        kind,
        buckets_path,
        window,
        percents,
        values,
    })
}

fn plugin_pipeline_aggregation_kind(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<os_query_dsl::PipelineAggregationKind> {
    if !plugin_kind_is_current_supported_finalize_pipeline_kind(plugin) {
        return None;
    }
    match plugin.kind.as_str() {
        "sum_bucket" => Some(os_query_dsl::PipelineAggregationKind::SumBucket),
        "avg_bucket" => Some(os_query_dsl::PipelineAggregationKind::AvgBucket),
        "min_bucket" => Some(os_query_dsl::PipelineAggregationKind::MinBucket),
        "max_bucket" => Some(os_query_dsl::PipelineAggregationKind::MaxBucket),
        "moving_count" => Some(os_query_dsl::PipelineAggregationKind::MovingCount),
        "cumulative_sum" => Some(os_query_dsl::PipelineAggregationKind::CumulativeSum),
        "serial_diff" => Some(os_query_dsl::PipelineAggregationKind::SerialDiff),
        "derivative" => Some(os_query_dsl::PipelineAggregationKind::Derivative),
        "stats_bucket" => Some(os_query_dsl::PipelineAggregationKind::StatsBucket),
        "extended_stats_bucket" => Some(os_query_dsl::PipelineAggregationKind::ExtendedStatsBucket),
        "percentiles_bucket" => Some(os_query_dsl::PipelineAggregationKind::PercentilesBucket),
        "percentile_ranks_bucket" => {
            Some(os_query_dsl::PipelineAggregationKind::PercentileRanksBucket)
        }
        _ => None,
    }
}

fn plugin_kind_is_current_supported_finalize_pipeline_kind(
    plugin: &os_query_dsl::PluginAggregation,
) -> bool {
    matches!(
        plugin.kind.as_str(),
        "sum_bucket"
            | "avg_bucket"
            | "min_bucket"
            | "max_bucket"
            | "moving_count"
            | "cumulative_sum"
            | "serial_diff"
            | "derivative"
            | "stats_bucket"
            | "extended_stats_bucket"
            | "percentiles_bucket"
            | "percentile_ranks_bucket"
    )
}

fn plugin_pipeline_window_override(
    plugin: &os_query_dsl::PluginAggregation,
    kind: os_query_dsl::PipelineAggregationKind,
) -> Option<usize> {
    if plugin_pipeline_supports_window_override(plugin, kind) {
        plugin_lag_param(plugin)
    } else {
        None
    }
}

fn plugin_pipeline_supports_window_override(
    _plugin: &os_query_dsl::PluginAggregation,
    kind: os_query_dsl::PipelineAggregationKind,
) -> bool {
    matches!(kind, os_query_dsl::PipelineAggregationKind::SerialDiff)
}

fn plugin_pipeline_percent_config(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<Vec<f64>> {
    if plugin.kind != "percentiles_bucket" {
        return None;
    }
    plugin_numeric_array_param(plugin, "percents")
}

fn plugin_pipeline_values_config(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<Vec<f64>> {
    if plugin.kind != "percentile_ranks_bucket" {
        return None;
    }
    plugin_numeric_array_param(plugin, "values")
}

fn plugin_finalize_aggregation(plugin: &os_query_dsl::PluginAggregation) -> bool {
    if plugin_kind_still_requires_explicit_finalize_family_admission(plugin) {
        return false;
    }
    plugin_pipeline_aggregation(plugin).is_some() || plugin_has_explicit_finalize_wrapper_family(plugin)
}

fn plugin_kind_still_requires_explicit_finalize_family_admission(
    plugin: &os_query_dsl::PluginAggregation,
) -> bool {
    !plugin_kind_is_current_supported_finalize_pipeline_kind(plugin)
        && !plugin_kind_is_current_supported_explicit_finalize_wrapper_kind(plugin)
}

fn plugin_has_explicit_finalize_wrapper_family(
    plugin: &os_query_dsl::PluginAggregation,
) -> bool {
    plugin_kind_is_current_supported_explicit_finalize_wrapper_kind(plugin)
        && (plugin.kind == "bucket_count"
            || matches!(
                plugin.kind.as_str(),
                "normalize" | "bucket_selector" | "bucket_script"
            )
            || plugin.kind == "bucket_sort"
            || plugin.kind == "moving_count"
            || matches!(
                plugin.kind.as_str(),
                "moving_avg"
                    | "moving_sum"
                    | "moving_min"
                    | "moving_max"
                    | "moving_median"
                    | "moving_mad"
                    | "moving_stddev"
                    | "moving_variance"
                    | "moving_skewness"
                    | "moving_kurtosis"
                    | "moving_range"
            )
            || matches!(
                plugin.kind.as_str(),
                "moving_percentiles" | "moving_percentile_ranks"
            ))
}

fn plugin_kind_is_current_supported_explicit_finalize_wrapper_kind(
    plugin: &os_query_dsl::PluginAggregation,
) -> bool {
    matches!(
        plugin.kind.as_str(),
        "bucket_sort"
            | "bucket_count"
            | "normalize"
            | "bucket_selector"
            | "bucket_script"
            | "moving_count"
            | "moving_avg"
            | "moving_sum"
            | "moving_min"
            | "moving_max"
            | "moving_median"
            | "moving_mad"
            | "moving_stddev"
            | "moving_variance"
            | "moving_skewness"
            | "moving_kurtosis"
            | "moving_range"
            | "moving_percentiles"
            | "moving_percentile_ranks"
            | "serial_diff"
            | "derivative"
            | "cumulative_sum"
            | "stats_bucket"
            | "extended_stats_bucket"
            | "percentiles_bucket"
            | "percentile_ranks_bucket"
            | "min_bucket"
            | "max_bucket"
            | "avg_bucket"
            | "sum_bucket"
    )
}

fn plugin_pipeline_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    plugin: &os_query_dsl::PluginAggregation,
) -> Value {
    if plugin_kind_requires_named_aggregation_target(plugin)
        && plugin_aggregation_target_param(plugin).is_none()
    {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin.kind == "bucket_script" && plugin_bucket_script_source_param(plugin).is_none() {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin.kind == "bucket_script"
        && plugin_param_exists(plugin, "params")
        && plugin_bucket_script_params_object(plugin).is_none()
    {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin.kind == "serial_diff"
        && plugin_param_exists(plugin, "lag")
        && plugin_lag_param(plugin).is_none()
    {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin.kind == "bucket_selector" && plugin_bucket_selector_threshold_param(plugin).is_none() {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin.kind == "bucket_selector"
        && plugin_param_exists(plugin, "op")
        && plugin_bucket_selector_operator_param(plugin).is_none()
    {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin_kind_treats_path_as_request_surface(plugin)
        && plugin_param_exists(plugin, "path")
        && plugin_path_param(plugin).is_none()
    {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin_kind_treats_window_as_request_surface(plugin)
        && plugin_param_exists(plugin, "window")
        && plugin_window_param(plugin).is_none()
    {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin.kind == "percentiles_bucket"
        && plugin_param_exists(plugin, "percents")
        && plugin_numeric_array_param(plugin, "percents").is_none()
    {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin.kind == "percentile_ranks_bucket"
        && plugin_param_exists(plugin, "values")
        && plugin_numeric_array_param(plugin, "values").is_none()
    {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin.kind == "moving_percentiles"
        && plugin_param_exists(plugin, "percents")
        && plugin_numeric_array_param(plugin, "percents").is_none()
    {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin.kind == "moving_percentile_ranks"
        && plugin_param_exists(plugin, "values")
        && plugin_numeric_array_param(plugin, "values").is_none()
    {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin.kind == "bucket_sort" {
        if (plugin_param_exists(plugin, "sort")
            && plugin_bucket_sort_explicit_sort_values(plugin).is_none())
            || (plugin_param_exists(plugin, "from") && plugin_usize_param(plugin, "from").is_none())
            || (plugin_param_exists(plugin, "size") && plugin_usize_param(plugin, "size").is_none())
        {
            return collect_plugin_aggregation_placeholder(plugin);
        }
        return plugin_bucket_sort_aggregation_value(aggregations, plugin);
    }
    if plugin.kind == "bucket_count" {
        return plugin_bucket_count_aggregation_value(aggregations, plugin);
    }
    if matches!(
        plugin.kind.as_str(),
        "normalize" | "bucket_selector" | "bucket_script"
    ) {
        return plugin_bucket_path_pipeline_aggregation_value(aggregations, plugin);
    }
    if plugin.kind == "moving_count" {
        return plugin_moving_count_aggregation_value(aggregations, plugin);
    }
    if matches!(
        plugin.kind.as_str(),
        "moving_avg"
            | "moving_sum"
            | "moving_min"
            | "moving_max"
            | "moving_median"
            | "moving_mad"
            | "moving_range"
            | "moving_stddev"
            | "moving_variance"
            | "moving_skewness"
            | "moving_kurtosis"
    ) {
        return plugin_moving_window_pipeline_aggregation_value(aggregations, plugin);
    }
    if matches!(
        plugin.kind.as_str(),
        "moving_percentiles" | "moving_percentile_ranks"
    ) {
        return plugin_moving_percentile_window_pipeline_aggregation_value(aggregations, plugin);
    }
    if matches!(plugin.kind.as_str(), "serial_diff" | "derivative") {
        return plugin_generic_pipeline_aggregation_value(aggregations, plugin);
    }
    if plugin.kind == "cumulative_sum" {
        return plugin_generic_pipeline_aggregation_value(aggregations, plugin);
    }
    if matches!(
        plugin.kind.as_str(),
        "stats_bucket"
            | "extended_stats_bucket"
            | "percentiles_bucket"
            | "percentile_ranks_bucket"
    ) {
        return plugin_generic_pipeline_aggregation_value(aggregations, plugin);
    }
    if matches!(plugin.kind.as_str(), "min_bucket" | "max_bucket") {
        return plugin_generic_pipeline_aggregation_value(aggregations, plugin);
    }
    if plugin.kind == "avg_bucket" {
        return plugin_generic_pipeline_aggregation_value(aggregations, plugin);
    }
    if plugin.kind == "sum_bucket" {
        return plugin_generic_pipeline_aggregation_value(aggregations, plugin);
    }
    collect_plugin_aggregation_placeholder(plugin)
}

fn plugin_bucket_path_pipeline_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    plugin: &os_query_dsl::PluginAggregation,
) -> Value {
    if plugin.kind == "normalize" {
        return plugin_normalize_aggregation_value(aggregations, plugin);
    }
    if plugin.kind == "bucket_selector" {
        return plugin_bucket_selector_aggregation_value(aggregations, plugin);
    }
    if plugin.kind == "bucket_script" {
        return plugin_bucket_script_aggregation_value(aggregations, plugin);
    }
    collect_plugin_aggregation_placeholder(plugin)
}

fn plugin_generic_pipeline_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    plugin: &os_query_dsl::PluginAggregation,
) -> Value {
    let Some(pipeline) = plugin_pipeline_aggregation(plugin) else {
        return collect_plugin_aggregation_placeholder(plugin);
    };
    plugin_object_aggregation_value(plugin, collect_pipeline_aggregation(aggregations, &pipeline))
}

fn clear_top_hits_score_surface(value: &mut Value) {
    let Some(hits_object) = value.get_mut("hits").and_then(Value::as_object_mut) else {
        return;
    };
    let total = hits_object
        .get("total")
        .cloned()
        .unwrap_or_else(|| serde_json::json!({ "value": 0, "relation": "eq" }));
    let mut carrier_hits = object_top_hits_carrier(hits_object);
    for hit in &mut carrier_hits {
        if let Some(hit_object) = hit.as_object_mut() {
            hit_object.insert("_score".to_string(), Value::Null);
        }
    }
    let visible_hits = if let Some(existing_visible_hits) =
        hits_object.get("hits").and_then(Value::as_array)
    {
        existing_visible_hits
            .iter()
            .map(|hit| {
                let mut hit = hit.clone();
                if let Some(hit_object) = hit.as_object_mut() {
                    hit_object.insert("_score".to_string(), Value::Null);
                }
                hit
            })
            .collect::<Vec<_>>()
    } else {
        carrier_hits.clone()
    };
    *hits_object = object_merge_and_visible_array_value_with_fields(
        "_merge_hits",
        "hits",
        carrier_hits,
        visible_hits,
        [
            ("total".to_string(), total),
            ("max_score".to_string(), Value::Null),
        ]
        .into_iter()
        .collect(),
    )
    .as_object()
    .cloned()
    .unwrap_or_default();
}

fn plugin_top_hits_uses_non_score_explicit_sort(
    plugin: &os_query_dsl::PluginAggregation,
) -> bool {
    let Some((_, _, sort_specs)) = plugin_top_hits_window_and_sort(plugin) else {
        return false;
    };
    !sort_specs.is_empty() && sort_specs.iter().all(|spec| spec.field != "_score")
}

fn next_f64_toward_positive(value: f64) -> f64 {
    if !value.is_finite() {
        return value;
    }
    if value == -0.0 {
        return 0.0;
    }
    if value >= 0.0 {
        f64::from_bits(value.to_bits().saturating_add(1))
    } else {
        f64::from_bits(value.to_bits().saturating_sub(1))
    }
}

fn finalize_merged_top_metrics_aggregation_value(
    merged: &mut serde_json::Map<String, Value>,
    name: &str,
) {
    let Some(entry_object) = merged.get_mut(name).and_then(Value::as_object_mut) else {
        return;
    };
    let metadata_fields = ["_plugin", "_type", "params"]
        .into_iter()
        .filter_map(|field| {
            entry_object
                .get(field)
                .cloned()
                .map(|value| (field.to_string(), value))
        })
        .collect::<Vec<_>>();
    let merge_top = object_top_metrics_carrier(entry_object);
    let mut visible_top = merge_top.clone();
    for entry in &mut visible_top {
        if let Some(object) = entry.as_object_mut() {
            object.remove("_index");
            object.remove("_id");
        }
    }
    *entry_object = object_merge_and_visible_array_value(
        "_merge_top",
        "top",
        merge_top,
        visible_top,
    )
    .as_object()
    .cloned()
    .unwrap_or_default();
    for (field, value) in metadata_fields {
        entry_object.insert(field, value);
    }
}

fn strip_internal_merge_surfaces(value: &mut Value) {
    match value {
        Value::Object(object) => {
            object.remove("_merge_hits");
            object.remove("_merge_top");
            object.remove("_merge_buckets");
            for nested in object.values_mut() {
                strip_internal_merge_surfaces(nested);
            }
        }
        Value::Array(values) => {
            for nested in values {
                strip_internal_merge_surfaces(nested);
            }
        }
        _ => {}
    }
}

