fn plugin_normalize_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    plugin: &os_query_dsl::PluginAggregation,
) -> Value {
    let Some(target) = plugin_aggregation_target_param(plugin) else {
        return collect_plugin_aggregation_placeholder(plugin);
    };
    if plugin_param_exists(plugin, "path") && plugin_path_param(plugin).is_none() {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    let path = plugin_path_param(plugin).unwrap_or("_count");

    plugin_visible_bucket_surface_aggregation_value(
        plugin,
        collect_normalize_aggregation_value(aggregations, &target, path),
    )
}

fn bucket_normalize_source_value(bucket: &Value, path: &str) -> Option<f64> {
    if path == "_count" {
        return bucket.get("doc_count").and_then(Value::as_f64);
    }
    if let Some(value) = bucket
        .get(path)
        .and_then(|value| value.get("value"))
        .and_then(Value::as_f64)
    {
        return Some(value);
    }
    bucket.get(path).and_then(Value::as_f64)
}

fn plugin_bucket_selector_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    plugin: &os_query_dsl::PluginAggregation,
) -> Value {
    let Some(target) = plugin_aggregation_target_param(plugin) else {
        return collect_plugin_aggregation_placeholder(plugin);
    };
    let Some(threshold) = plugin_bucket_selector_threshold_param(plugin) else {
        return collect_plugin_aggregation_placeholder(plugin);
    };
    if plugin_param_exists(plugin, "path") && plugin_path_param(plugin).is_none() {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin_param_exists(plugin, "op") && plugin_bucket_selector_operator_param(plugin).is_none() {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    let path = plugin_path_param(plugin).unwrap_or("_count");
    let operator =
        plugin_bucket_selector_operator_param(plugin).unwrap_or("gte");

    plugin_visible_bucket_surface_aggregation_value(
        plugin,
        collect_bucket_selector_aggregation_value(
            aggregations,
            &target,
            &path,
            &operator,
            threshold
        ),
    )
}

fn collect_bucket_count_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    target: &str,
) -> Value {
    let value = aggregations
        .get(target)
        .map(pipeline_bucket_values)
        .map(|buckets| buckets.len())
        .unwrap_or(0);
    serde_json::json!({ "value": value })
}

fn pipeline_bucket_values(value: &Value) -> Vec<Value> {
    match pipeline_bucket_surface(value) {
        Value::Array(items) => items,
        Value::Object(object) => object
            .iter()
            .map(|(key, bucket)| {
                let mut bucket = bucket.clone();
                if bucket.get("key").is_none() {
                    if let Some(map) = bucket.as_object_mut() {
                        map.insert("key".to_string(), Value::String(key.clone()));
                    }
                }
                bucket
            })
            .collect::<Vec<_>>(),
        _ => Vec::new(),
    }
}

fn pipeline_bucket_surface(value: &Value) -> Value {
    if let Some(object) = value.as_object() {
        if let Some(merge_buckets) = object.get("_merge_buckets") {
            return merge_buckets.clone();
        }
        if let Some(buckets) = object.get("buckets") {
            return buckets.clone();
        }
        return Value::Object(object.clone());
    }
    match value {
        Value::Array(items) => Value::Array(items.clone()),
        _ => Value::Array(Vec::new()),
    }
}

fn bucket_surface_wrapper_value(buckets: Value) -> Value {
    match buckets {
        Value::Array(items) => {
            let visible_buckets = items.clone();
            object_merge_and_visible_array_value(
                "_merge_buckets",
                "buckets",
                items,
                visible_buckets,
            )
        }
        Value::Object(items) => {
            let visible_buckets = items.clone();
            object_value_with_fields(
                [
                    ("_merge_buckets".to_string(), Value::Object(items)),
                    ("buckets".to_string(), Value::Object(visible_buckets)),
                ]
                .into_iter()
                .collect(),
            )
        }
        _ => object_merge_and_visible_array_value(
            "_merge_buckets",
            "buckets",
            Vec::new(),
            Vec::new(),
        ),
    }
}

