fn object_value_with_field(field: &str, field_value: Value) -> Value {
    object_value_with_fields([(field.to_string(), field_value)].into_iter().collect())
}

fn object_value_with_field_and_fields(
    field: &str,
    field_value: Value,
    fields: serde_json::Map<String, Value>,
) -> Value {
    value_with_attached_fields(object_value_with_field(field, field_value), fields)
}

fn object_value_with_fields_and_fields(
    fields: serde_json::Map<String, Value>,
    extra_fields: serde_json::Map<String, Value>,
) -> Value {
    value_with_attached_fields(object_value_with_fields(fields), extra_fields)
}

fn object_fields_map<I>(fields: I) -> serde_json::Map<String, Value>
where
    I: IntoIterator<Item = (String, Value)>,
{
    fields.into_iter().collect()
}

fn wrapper_with_named_value(name: &str, value: Value) -> serde_json::Map<String, Value> {
    object_fields_map([(name.to_string(), value)])
}

