fn stats_summary_object(
    count: u64,
    sum: f64,
    min: Option<f64>,
    max: Option<f64>,
    avg: Value,
) -> serde_json::Map<String, Value> {
    serde_json::Map::from_iter([
        ("count".to_string(), Value::from(count)),
        ("sum".to_string(), Value::from(sum)),
        ("min".to_string(), min.map(Value::from).unwrap_or(Value::Null)),
        ("max".to_string(), max.map(Value::from).unwrap_or(Value::Null)),
        ("avg".to_string(), avg),
    ])
}

fn object_value_with_fields(fields: serde_json::Map<String, Value>) -> Value {
    Value::Object(fields)
}

fn value_with_attached_fields(
    mut value: Value,
    fields: serde_json::Map<String, Value>,
) -> Value {
    if let Some(object) = value.as_object_mut() {
        for (field, field_value) in fields {
            object.insert(field, field_value);
        }
    }
    value
}

fn range_bucket_seed_object(
    key: Value,
    from: Option<Value>,
    to: Option<Value>,
    doc_count: u64,
) -> serde_json::Map<String, Value> {
    let mut fields = serde_json::Map::new();
    fields.insert("key".to_string(), key);
    if let Some(from) = from {
        fields.insert("from".to_string(), from);
    }
    if let Some(to) = to {
        fields.insert("to".to_string(), to);
    }
    fields.insert("doc_count".to_string(), Value::from(doc_count));
    object_value_with_fields(fields)
        .as_object()
        .cloned()
        .unwrap_or_default()
}

