fn collect_normalize_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    target: &str,
    path: &str,
) -> Value {
    let buckets = aggregations
        .get(target)
        .map(pipeline_bucket_surface)
        .unwrap_or_else(|| Value::Array(Vec::new()));

    match buckets {
        Value::Array(items) => {
            let extracted = items
                .iter()
                .map(|bucket| bucket_normalize_source_value(bucket, path).unwrap_or(0.0))
                .collect::<Vec<_>>();
            let total = extracted.iter().sum::<f64>();
            Value::Array(
                items
                    .into_iter()
                    .zip(extracted)
                    .map(|(bucket, value)| {
                        let normalized = if total == 0.0 { 0.0 } else { value / total };
                        serde_json::json!({
                            "key": bucket.get("key").cloned().unwrap_or(Value::Null),
                            "value": normalized
                        })
                    })
                    .collect::<Vec<_>>(),
            )
        }
        Value::Object(object) => {
            let extracted = object
                .iter()
                .map(|(_, bucket)| bucket_normalize_source_value(bucket, path).unwrap_or(0.0))
                .collect::<Vec<_>>();
            let total = extracted.iter().sum::<f64>();
            Value::Object(
                object
                    .into_iter()
                    .zip(extracted)
                    .map(|((key, _bucket), value)| {
                        let normalized = if total == 0.0 { 0.0 } else { value / total };
                        (
                            key,
                            serde_json::json!({
                                "value": normalized
                            }),
                        )
                    })
                    .collect(),
            )
        }
        _ => Value::Array(Vec::new()),
    }
}

fn collect_bucket_selector_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    target: &str,
    path: &str,
    operator: &str,
    threshold: f64,
) -> Value {
    let buckets = aggregations
        .get(target)
        .map(pipeline_bucket_surface)
        .unwrap_or_else(|| Value::Array(Vec::new()));

    match buckets {
        Value::Array(items) => Value::Array(
            items.into_iter()
                .filter(|bucket| {
                    bucket_normalize_source_value(bucket, path)
                        .map(|value| matches_bucket_selector(value, operator, threshold))
                        .unwrap_or(false)
                })
                .collect(),
        ),
        Value::Object(object) => Value::Object(
            object
                .into_iter()
                .filter(|(_, bucket)| {
                    bucket_normalize_source_value(bucket, path)
                        .map(|value| matches_bucket_selector(value, operator, threshold))
                        .unwrap_or(false)
                })
                .collect(),
        ),
        _ => Value::Array(Vec::new()),
    }
}

fn collect_bucket_script_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    target: &str,
    path: &str,
    script_source: &str,
    params: &std::collections::BTreeMap<String, Value>,
) -> Value {
    let script = os_engine::SortScript {
        source: script_source.replace("_value", "doc['_value'].value"),
        params: params.clone(),
    };

    let buckets = aggregations
        .get(target)
        .map(pipeline_bucket_surface)
        .unwrap_or_else(|| Value::Array(Vec::new()));

    match buckets {
        Value::Array(items) => Value::Array(
            items
                .into_iter()
                .filter_map(|bucket| {
                    let key = bucket.get("key").cloned().unwrap_or(Value::Null);
                    let value = bucket_normalize_source_value(&bucket, path)?;
                    let source = serde_json::json!({ "_value": value });
                    let scripted_value = evaluate_sort_script(&source, &script)?;
                    Some(serde_json::json!({
                        "key": key,
                        "value": scripted_value
                    }))
                })
                .collect::<Vec<_>>(),
        ),
        Value::Object(object) => Value::Object(
            object
                .into_iter()
                .filter_map(|(key, bucket)| {
                    let value = bucket_normalize_source_value(&bucket, path)?;
                    let source = serde_json::json!({ "_value": value });
                    let scripted_value = evaluate_sort_script(&source, &script)?;
                    Some((
                        key,
                        serde_json::json!({
                            "value": scripted_value
                        }),
                    ))
                })
                .collect(),
        ),
        _ => Value::Array(Vec::new()),
    }
}

fn moving_window_bucket_aggregation_value<F>(
    aggregations: &serde_json::Map<String, Value>,
    target: &str,
    path: &str,
    window: usize,
    value_source: fn(&Value, &str) -> Option<f64>,
    bucket_value: F,
) -> Value
where
    F: Fn(&[f64]) -> serde_json::Map<String, Value>,
{
    let buckets = aggregations
        .get(target)
        .map(pipeline_bucket_surface)
        .unwrap_or_else(|| Value::Array(Vec::new()));

    match buckets {
        Value::Array(items) => {
            let source_values = items
                .iter()
                .map(|bucket| value_source(bucket, path).unwrap_or(0.0))
                .collect::<Vec<_>>();
            Value::Array(
                items.into_iter()
                    .enumerate()
                    .map(|(index, bucket)| {
                        let start = index.saturating_sub(window.saturating_sub(1));
                        let mut bucket_object = bucket_value(&source_values[start..=index]);
                        bucket_object.insert(
                            "key".to_string(),
                            bucket.get("key").cloned().unwrap_or(Value::Null),
                        );
                        Value::Object(bucket_object)
                    })
                    .collect::<Vec<_>>(),
            )
        }
        Value::Object(object) => {
            let entries = object.into_iter().collect::<Vec<_>>();
            let source_values = entries
                .iter()
                .map(|(_, bucket)| value_source(bucket, path).unwrap_or(0.0))
                .collect::<Vec<_>>();
            Value::Object(
                entries
                    .into_iter()
                    .enumerate()
                    .map(|(index, (key, _bucket))| {
                        let start = index.saturating_sub(window.saturating_sub(1));
                        (key, Value::Object(bucket_value(&source_values[start..=index])))
                    })
                    .collect(),
            )
        }
        _ => Value::Array(Vec::new()),
    }
}

fn pipeline_moving_window_bucket_aggregation_value<F>(
    aggregations: &serde_json::Map<String, Value>,
    buckets_path: &str,
    window: usize,
    bucket_value: F,
) -> Value
where
    F: Fn(&[f64]) -> serde_json::Map<String, Value>,
{
    let (bucket_aggregation, metric_name, use_doc_count) =
        if let Some(bucket_aggregation) = buckets_path
            .strip_suffix(">_count")
            .or_else(|| buckets_path.strip_suffix("._count"))
        {
            (bucket_aggregation, None, true)
        } else {
            let Some((bucket_aggregation, metric_name)) = buckets_path
                .split_once('>')
                .or_else(|| buckets_path.split_once('.'))
            else {
                return Value::Array(Vec::new());
            };
            (bucket_aggregation, Some(metric_name), false)
        };

    let buckets = aggregations
        .get(bucket_aggregation)
        .map(pipeline_bucket_surface)
        .unwrap_or_else(|| Value::Array(Vec::new()));

    let bucket_metric = |bucket: &Value| {
        if use_doc_count {
            bucket.get("doc_count").and_then(Value::as_f64)
        } else {
            metric_name
                .and_then(|metric_name| bucket.get(metric_name))
                .and_then(|metric| metric.get("value"))
                .and_then(Value::as_f64)
        }
    };

    match buckets {
        Value::Array(items) => {
            let filtered = items
                .into_iter()
                .filter_map(|bucket| Some((bucket_metric(&bucket)?, bucket)))
                .collect::<Vec<_>>();
            Value::Array(
                filtered
                    .iter()
                    .enumerate()
                    .map(|(index, (_metric, bucket))| {
                        let start = index.saturating_sub(window.saturating_sub(1));
                        let slice = filtered[start..=index]
                            .iter()
                            .map(|(value, _bucket)| *value)
                            .collect::<Vec<_>>();
                        let mut bucket_object = bucket_value(&slice);
                        bucket_object.insert(
                            "key".to_string(),
                            Value::from(index),
                        );
                        Value::Object(bucket_object)
                    })
                    .collect::<Vec<_>>(),
            )
        }
        Value::Object(object) => {
            let filtered = object
                .into_iter()
                .filter_map(|(key, bucket)| Some((key, bucket_metric(&bucket)?, bucket)))
                .collect::<Vec<_>>();
            Value::Object(
                filtered
                    .iter()
                    .enumerate()
                    .map(|(index, (key, _metric, _bucket))| {
                        let start = index.saturating_sub(window.saturating_sub(1));
                        let slice = filtered[start..=index]
                            .iter()
                            .map(|(_key, value, _bucket)| *value)
                            .collect::<Vec<_>>();
                        (key.clone(), Value::Object(bucket_value(&slice)))
                    })
                    .collect(),
            )
        }
        _ => Value::Array(Vec::new()),
    }
}

fn plugin_bucket_script_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    plugin: &os_query_dsl::PluginAggregation,
) -> Value {
    let Some(target) = plugin_aggregation_target_param(plugin) else {
        return collect_plugin_aggregation_placeholder(plugin);
    };
    let Some(script_source) = plugin_bucket_script_source_param(plugin) else {
        return collect_plugin_aggregation_placeholder(plugin);
    };
    if plugin_param_exists(plugin, "path") && plugin_path_param(plugin).is_none() {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    if plugin_param_exists(plugin, "params") && plugin_bucket_script_params_object(plugin).is_none() {
        return collect_plugin_aggregation_placeholder(plugin);
    }
    let path = plugin_path_param(plugin).unwrap_or("_count");
    plugin_visible_bucket_surface_aggregation_value(
        plugin,
        collect_bucket_script_aggregation_value(
            aggregations,
            &target,
            &path,
            &script_source,
            &plugin_bucket_script_params_object(plugin)
                .unwrap_or_default()
                .into_iter()
                .collect(),
        ),
    )
}

fn plugin_moving_avg_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    plugin: &os_query_dsl::PluginAggregation,
) -> Value {
    let target = plugin
        .params
        .get("aggregation")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let path = plugin
        .params
        .get("path")
        .and_then(Value::as_str)
        .unwrap_or("_count");
    let window = plugin
        .params
        .get("window")
        .and_then(|value| value.as_u64())
        .map(|value| value as usize)
        .filter(|value| *value > 0)
        .unwrap_or(2);

    plugin_visible_bucket_surface_aggregation_value(
        plugin,
        moving_window_bucket_aggregation_value(
            aggregations,
            target,
            path,
            window,
            bucket_normalize_source_value,
            |slice| {
                let average = if slice.is_empty() {
                    0.0
                } else {
                    slice.iter().sum::<f64>() / (slice.len() as f64)
                };
                serde_json::Map::from_iter([("value".to_string(), Value::from(average))])
            }
        ),
    )
}

fn plugin_moving_count_aggregation_value(
    aggregations: &serde_json::Map<String, Value>,
    plugin: &os_query_dsl::PluginAggregation,
) -> Value {
    let target = plugin
        .params
        .get("aggregation")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let path = plugin
        .params
        .get("path")
        .and_then(Value::as_str)
        .unwrap_or("_count");
    let window = plugin
        .params
        .get("window")
        .and_then(|value| value.as_u64())
        .map(|value| value as usize)
        .unwrap_or(2)
        .max(1);
    let buckets = match aggregations
        .get(target)
        .map(pipeline_bucket_surface)
        .unwrap_or_else(|| Value::Array(Vec::new()))
    {
        Value::Array(items) => {
            let filtered = items
                .into_iter()
                .filter(|bucket| bucket_normalize_source_value(bucket, path).is_some())
                .collect::<Vec<_>>();
            let buckets = filtered
                .into_iter()
                .enumerate()
                .map(|(index, bucket)| {
                    let start = index.saturating_sub(window.saturating_sub(1));
                    let count = index.saturating_sub(start).saturating_add(1);
                    let _ = bucket;
                    serde_json::json!({
                        "key": index,
                        "value": count as f64
                    })
                })
                .collect::<Vec<_>>();
            Value::Array(buckets)
        }
        Value::Object(object) => {
            let filtered = object
                .into_iter()
                .filter(|(_, bucket)| bucket_normalize_source_value(bucket, path).is_some())
                .collect::<Vec<_>>();
            let buckets = filtered
                .into_iter()
                .enumerate()
                .map(|(index, (key, _bucket))| {
                    let start = index.saturating_sub(window.saturating_sub(1));
                    let count = index.saturating_sub(start).saturating_add(1);
                    (key, serde_json::json!({ "value": count as f64 }))
                })
                .collect::<serde_json::Map<_, _>>();
            Value::Object(buckets)
        }
        _ => Value::Array(Vec::new()),
    };
    plugin_visible_bucket_surface_aggregation_value(plugin, buckets)
}

