fn moving_skewness_for_slice(slice: &[f64]) -> f64 {
    if slice.is_empty() {
        return 0.0;
    }
    let mean = slice.iter().sum::<f64>() / (slice.len() as f64);
    let variance = slice
        .iter()
        .map(|value| {
            let delta = value - mean;
            delta * delta
        })
        .sum::<f64>()
        / (slice.len() as f64);
    let stddev = variance.sqrt();
    if stddev == 0.0 {
        return 0.0;
    }
    slice
        .iter()
        .map(|value| {
            let standardized = (value - mean) / stddev;
            standardized * standardized * standardized
        })
        .sum::<f64>()
        / (slice.len() as f64)
}

fn moving_kurtosis_for_slice(slice: &[f64]) -> f64 {
    if slice.is_empty() {
        return 0.0;
    }
    let mean = slice.iter().sum::<f64>() / (slice.len() as f64);
    let variance = slice
        .iter()
        .map(|value| {
            let delta = value - mean;
            delta * delta
        })
        .sum::<f64>()
        / (slice.len() as f64);
    let stddev = variance.sqrt();
    if stddev == 0.0 {
        return 0.0;
    }
    slice
        .iter()
        .map(|value| {
            let standardized = (value - mean) / stddev;
            standardized * standardized * standardized * standardized
        })
        .sum::<f64>()
        / (slice.len() as f64)
}

fn moving_mad_for_slice(slice: &[f64]) -> f64 {
    if slice.is_empty() {
        return 0.0;
    }
    let mut sorted = slice.to_vec();
    sorted.sort_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal));
    let median = if sorted.len() % 2 == 1 {
        sorted[sorted.len() / 2]
    } else {
        let upper = sorted.len() / 2;
        (sorted[upper - 1] + sorted[upper]) / 2.0
    };
    let mut deviations = sorted
        .iter()
        .map(|value| (value - median).abs())
        .collect::<Vec<_>>();
    deviations.sort_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal));
    if deviations.len() % 2 == 1 {
        deviations[deviations.len() / 2]
    } else {
        let upper = deviations.len() / 2;
        (deviations[upper - 1] + deviations[upper]) / 2.0
    }
}

fn matches_bucket_selector(value: f64, operator: &str, threshold: f64) -> bool {
    match operator {
        "gt" => value > threshold,
        "gte" => value >= threshold,
        "lt" => value < threshold,
        "lte" => value <= threshold,
        "eq" => value == threshold,
        "ne" => value != threshold,
        _ => false,
    }
}

