fn aggregation_top_hits_request_surface_carries_only_from_and_size(
    top_hits: &os_query_dsl::TopHitsAggregation,
) -> bool {
    aggregation_top_hits_request_surface_carries_from_and_size_window(top_hits)
        && aggregation_top_hits_request_surface_still_has_no_sort_carrier()
}

fn aggregation_top_hits_request_surface_still_has_no_sort_carrier() -> bool {
    aggregation_top_hits_request_surface_exposes_only_window_fields()
        && aggregation_top_hits_request_surface_has_no_sort_field_on_dsl_type()
}

fn aggregation_top_hits_request_surface_carries_from_and_size_window(
    top_hits: &os_query_dsl::TopHitsAggregation,
) -> bool {
    let (from, size) = aggregation_top_hits_request_surface_extracts_window_fields(top_hits);
    from.saturating_add(size) > 0
}

fn aggregation_top_hits_request_surface_exposes_only_window_fields() -> bool {
    true
}

fn aggregation_top_hits_request_surface_has_no_sort_field_on_dsl_type() -> bool {
    true
}

fn aggregation_top_hits_request_surface_extracts_window_fields(
    top_hits: &os_query_dsl::TopHitsAggregation,
) -> (usize, usize) {
    (top_hits.from, top_hits.size)
}

fn plugin_top_hits_request_surface_carries_from_and_size_window(
    plugin: &os_query_dsl::PluginAggregation,
) -> bool {
    let Some((from, size, _)) = plugin_top_hits_window_and_sort(plugin) else {
        return false;
    };
    from.saturating_add(size) > 0
}

fn plugin_top_hits_request_surface_carries_non_empty_sort_specs(
    plugin: &os_query_dsl::PluginAggregation,
) -> bool {
    plugin_top_hits_explicit_sort_specs(plugin).is_some_and(|sort_specs| !sort_specs.is_empty())
}

fn plugin_top_hits_request_surface_uses_score_sort(
    plugin: &os_query_dsl::PluginAggregation,
) -> bool {
    plugin_top_hits_explicit_sort_specs(plugin)
        .unwrap_or_default()
        .iter()
        .any(|spec| spec.field == "_score")
}

fn plugin_top_metrics_request_surface_uses_score_sort(
    plugin: &os_query_dsl::PluginAggregation,
) -> bool {
    plugin_top_metrics_explicit_sort_specs(plugin)
        .unwrap_or_default()
        .iter()
        .any(|spec| spec.field == "_score")
}

