fn aggregation_uses_key_asc_order_for_significant_terms_family(
    aggregation: &Aggregation,
) -> bool {
    match aggregation {
        Aggregation::Plugin(plugin) if plugin_kind_uses_significant_terms_carrier(&plugin.kind) => {
            plugin_terms_family_order_param(plugin).is_some()
                && plugin_terms_family_order_param(plugin).unwrap_or(("_score", SortOrder::Desc))
                    == ("_key", SortOrder::Asc)
        }
        Aggregation::Plugin(plugin) => plugin_subaggregation_map(plugin)
            .is_some_and(|map| aggregation_map_uses_key_asc_order_for_significant_terms_family(&map)),
        _ => false,
    }
}

fn aggregation_uses_key_desc_order_for_significant_terms_family(
    aggregation: &Aggregation,
) -> bool {
    match aggregation {
        Aggregation::Plugin(plugin) if plugin_kind_uses_significant_terms_carrier(&plugin.kind) => {
            plugin_terms_family_order_param(plugin).is_some()
                && plugin_terms_family_order_param(plugin).unwrap_or(("_score", SortOrder::Desc))
                    == ("_key", SortOrder::Desc)
        }
        Aggregation::Plugin(plugin) => plugin_subaggregation_map(plugin)
            .is_some_and(|map| aggregation_map_uses_key_desc_order_for_significant_terms_family(&map)),
        _ => false,
    }
}

fn aggregation_uses_only_key_asc_order_for_significant_terms_family(
    aggregation: &Aggregation,
) -> bool {
    match aggregation {
        Aggregation::SignificantTerms(_) => false,
        Aggregation::Plugin(plugin) if plugin_kind_uses_significant_terms_carrier(&plugin.kind) => {
            plugin_terms_family_order_param(plugin).is_some()
                && plugin_terms_family_order_param(plugin).unwrap_or(("_score", SortOrder::Desc))
                    == ("_key", SortOrder::Asc)
        }
        Aggregation::Plugin(plugin) => plugin_subaggregation_map(plugin).map_or(true, |map| aggregation_map_uses_only_key_asc_order_for_significant_terms_family(&map)),
        _ => true,
    }
}

fn aggregation_uses_count_asc_order_for_significant_terms_family(
    aggregation: &Aggregation,
) -> bool {
    match aggregation {
        Aggregation::Plugin(plugin) if plugin_kind_uses_significant_terms_carrier(&plugin.kind) => {
            plugin_terms_family_order_param(plugin).is_some()
                && plugin_terms_family_order_param(plugin).unwrap_or(("_score", SortOrder::Desc))
                    == ("_count", SortOrder::Asc)
        }
        Aggregation::Plugin(plugin) => plugin_subaggregation_map(plugin)
            .is_some_and(|map| aggregation_map_uses_count_asc_order_for_significant_terms_family(&map)),
        _ => false,
    }
}

fn aggregation_requires_no_extra_ranking_interpretation_for_significant_terms_family(
    aggregation: &Aggregation,
) -> bool {
    match aggregation {
        Aggregation::Plugin(plugin) if plugin_kind_uses_significant_terms_carrier(&plugin.kind) => {
            plugin_terms_family_order_param(plugin).is_some()
                && matches!(
                    plugin_terms_family_order_param(plugin).unwrap_or(("_score", SortOrder::Desc)),
                    ("_score", SortOrder::Asc | SortOrder::Desc)
                        | ("_key", SortOrder::Asc | SortOrder::Desc)
                        | ("_count", SortOrder::Asc | SortOrder::Desc)
                )
        }
        Aggregation::Plugin(plugin) => plugin_subaggregation_map(plugin).map_or(true, |map| aggregation_map_requires_no_extra_ranking_interpretation_for_significant_terms_family(&map)),
        _ => true,
    }
}

fn aggregation_supports_deterministic_bucket_key_tie_break_for_significant_terms_family(
    aggregation: &Aggregation,
) -> bool {
    match aggregation {
        Aggregation::Plugin(plugin) if plugin_kind_uses_significant_terms_carrier(&plugin.kind) => {
            plugin_terms_family_order_param(plugin).is_some()
                && matches!(
                    plugin_terms_family_order_param(plugin).unwrap_or(("_score", SortOrder::Desc)),
                    ("_score", SortOrder::Asc | SortOrder::Desc)
                        | ("_key", SortOrder::Asc | SortOrder::Desc)
                        | ("_count", SortOrder::Asc | SortOrder::Desc)
                )
        }
        Aggregation::SignificantTerms(_) => true,
        Aggregation::Plugin(plugin) => plugin_subaggregation_map(plugin).map_or(true, |map| aggregation_map_supports_deterministic_bucket_key_tie_break_for_significant_terms_family(&map)),
        _ => true,
    }
}

fn aggregation_map_top_hits_window(aggregation_map: &AggregationMap) -> Option<usize> {
    aggregation_map
        .values()
        .filter_map(|aggregation| match aggregation {
            Aggregation::TopHits(top_hits) => Some(top_hits.from.saturating_add(top_hits.size)),
            Aggregation::Plugin(plugin) if plugin.kind == "top_hits" => {
                let Some((from, size, sort_specs)) = plugin_top_hits_window_and_sort(plugin) else {
                    return None;
                };
                if sort_specs.is_empty() {
                    Some(from.saturating_add(size))
                } else {
                    None
                }
            }
            _ => None,
        })
        .max()
}

fn aggregation_map_for_shard_local_native_reduce(aggregation_map: &AggregationMap) -> AggregationMap {
    aggregation_map
        .iter()
        .filter(|(_, aggregation)| {
            !matches!(aggregation, Aggregation::TopHits(_))
                && !matches!(
                    aggregation,
                    Aggregation::BucketSort(_)
                        | Aggregation::BucketCount(_)
                        | Aggregation::Normalize(_)
                        | Aggregation::BucketSelector(_)
                        | Aggregation::BucketScript(_)
                        | Aggregation::Pipeline(_)
                )
                && !matches!(
                    aggregation,
                    Aggregation::Plugin(plugin)
                        if plugin.kind == "top_hits" || plugin_finalize_aggregation(plugin)
                )
        })
        .map(|(name, aggregation)| (name.clone(), aggregation.clone()))
        .collect()
}

fn merge_native_aggregation_response(
    merged: &mut serde_json::Map<String, Value>,
    aggregation_map: &AggregationMap,
    response: Value,
    avg_count_hints: &BTreeMap<String, u64>,
    cardinality_value_hints: &BTreeMap<String, std::collections::BTreeSet<String>>,
    percentile_value_hints: &BTreeMap<String, Vec<f64>>,
) {
    let Some(response_object) = response.as_object() else {
        return;
    };
    for (name, aggregation) in aggregation_map {
        if matches!(aggregation, Aggregation::Pipeline(_))
            || matches!(aggregation, Aggregation::Plugin(plugin) if plugin_finalize_aggregation(plugin))
        {
            continue;
        }
        let Some(value) = response_object.get(name) else {
            continue;
        };
        match aggregation {
            Aggregation::Terms(_) => {
                merge_terms_aggregation_value(merged, name, value);
            }
            Aggregation::DateHistogram(_) => {
                merge_date_histogram_aggregation_value(merged, name, value);
            }
            Aggregation::Histogram(_) => {
                merge_histogram_aggregation_value(merged, name, value);
            }
            Aggregation::Range(_) => {
                merge_range_aggregation_value(merged, name, value);
            }
            Aggregation::Composite(composite) => {
                merge_composite_aggregation_value(merged, name, value, composite);
            }
            Aggregation::Metric(metric) => {
                merge_metric_aggregation_value(
                    merged,
                    name,
                    value,
                    metric,
                    avg_count_hints.get(name).copied(),
                    cardinality_value_hints.get(name),
                    percentile_value_hints.get(name),
                );
            }
            Aggregation::Missing(_) => {
                merge_missing_aggregation_value(merged, name, value);
            }
            Aggregation::Filter(_) => {
                merge_filter_aggregation_value(merged, name, value);
            }
            Aggregation::Filters(_) => {
                merge_filters_aggregation_value(merged, name, value);
            }
            Aggregation::TopHits(top_hits) => {
                merge_top_hits_aggregation_value(merged, name, value, top_hits.from, top_hits.size);
            }
            Aggregation::GeoBounds(_) => {
                merge_geo_bounds_aggregation_value(merged, name, value);
            }
            Aggregation::GeoCentroid(_) => {
                merge_geo_centroid_aggregation_value(merged, name, value);
            }
            Aggregation::SignificantTerms(significant_terms) => {
                merge_significant_terms_aggregation_value(merged, name, value, significant_terms.size);
            }
            Aggregation::ScriptedMetric(_) => {
                merge_scripted_metric_aggregation_value(merged, name, value);
            }
            Aggregation::Plugin(plugin) => {
                merge_plugin_aggregation_value(
                    merged,
                    name,
                    value,
                    plugin,
                    cardinality_value_hints.get(name),
                    percentile_value_hints.get(name),
                );
            }
            _ => {}
        }
    }
}

fn rewrite_top_hits_reduce_windows(
    aggregations: &mut Value,
    aggregation_map: &AggregationMap,
    hits: &[SearchHit],
) {
    let mut ordered_hits = hits.to_vec();
    if ordered_hits.len() > 1 {
        ordered_hits.sort_by(compare_relevance_hits);
    }
    let Some(aggregations_object) = aggregations.as_object_mut() else {
        return;
    };
    for (name, aggregation) in aggregation_map {
        match aggregation {
            Aggregation::TopHits(top_hits) => {
                let reduce_top_hits = os_query_dsl::TopHitsAggregation {
                    from: 0,
                    size: top_hits.from.saturating_add(top_hits.size),
                };
                aggregations_object
                    .insert(
                        name.clone(),
                        collect_top_hits_aggregation(&ordered_hits, &reduce_top_hits),
                    );
            }
            Aggregation::Plugin(plugin) if plugin.kind == "top_hits" => {
                let Some((from, size, sort_specs)) = plugin_top_hits_window_and_sort(plugin) else {
                    continue;
                };
                if !sort_specs.is_empty() {
                    continue;
                }
                let reduce_plugin = os_query_dsl::PluginAggregation {
                    name: plugin.name.clone(),
                    kind: plugin.kind.clone(),
                    params: serde_json::json!({
                        "from": 0,
                        "size": from.saturating_add(size),
                    }),
                };
                aggregations_object.insert(
                    name.clone(),
                    collect_plugin_top_hits_aggregation_with_input_order(
                        &ordered_hits,
                        &reduce_plugin,
                        PluginTopHitsInputOrder::CallerFinal,
                    ),
                );
            }
            _ => {}
        }
    }
}

fn finalize_merged_pipeline_aggregations(
    merged: &mut serde_json::Map<String, Value>,
    aggregation_map: &AggregationMap,
) {
    for (name, aggregation) in aggregation_map {
        match aggregation {
            Aggregation::TopHits(top_hits) => {
                finalize_merged_top_hits_aggregation_value(
                    merged,
                    name,
                    top_hits.from,
                    top_hits.size,
                );
            }
            Aggregation::BucketSort(bucket_sort) => {
                merged.insert(
                    name.clone(),
                    serde_json::json!({
                        "buckets": collect_bucket_sort_aggregation_value(
                            merged,
                            &bucket_sort.aggregation,
                            &bucket_sort.sort,
                            bucket_sort.from,
                            bucket_sort.size
                        )
                    }),
                );
            }
            Aggregation::BucketCount(bucket_count) => {
                merged.insert(
                    name.clone(),
                    collect_bucket_count_aggregation_value(merged, &bucket_count.aggregation),
                );
            }
            Aggregation::Normalize(normalize) => {
                merged.insert(
                    name.clone(),
                    serde_json::json!({
                        "buckets": collect_normalize_aggregation_value(
                            merged,
                            &normalize.aggregation,
                            &normalize.path
                        )
                    }),
                );
            }
            Aggregation::BucketSelector(bucket_selector) => {
                merged.insert(
                    name.clone(),
                    serde_json::json!({
                        "buckets": collect_bucket_selector_aggregation_value(
                            merged,
                            &bucket_selector.aggregation,
                            &bucket_selector.path,
                            &bucket_selector.op,
                            bucket_selector.value
                        )
                    }),
                );
            }
            Aggregation::BucketScript(bucket_script) => {
                merged.insert(
                    name.clone(),
                    serde_json::json!({
                        "buckets": collect_bucket_script_aggregation_value(
                            merged,
                            &bucket_script.aggregation,
                            &bucket_script.path,
                            &bucket_script.script,
                            &bucket_script.params
                        )
                    }),
                );
            }
            Aggregation::Pipeline(pipeline) => {
                merged.insert(name.clone(), collect_pipeline_aggregation(merged, pipeline));
            }
            Aggregation::Plugin(plugin) => {
                if !plugin_has_valid_request_surface_for_merge_or_finalize(plugin) {
                    merged.insert(name.clone(), collect_plugin_aggregation_placeholder(plugin));
                    continue;
                }
                if plugin.kind == "top_hits" {
                    let Some((from, size, _)) = plugin_top_hits_window_and_sort(plugin) else {
                        merged.insert(name.clone(), collect_plugin_aggregation_placeholder(plugin));
                        continue;
                    };
                    finalize_merged_top_hits_aggregation_value(merged, name, from, size);
                    if plugin_top_hits_uses_non_score_explicit_sort(plugin) {
                        if let Some(value) = merged.get_mut(name) {
                            clear_top_hits_score_surface(value);
                        }
                    }
                } else if plugin.kind == "top_metrics" {
                    if !plugin_top_metrics_has_valid_setup(plugin) {
                        merged.insert(name.clone(), collect_plugin_aggregation_placeholder(plugin));
                    } else {
                        finalize_merged_top_metrics_aggregation_value(merged, name);
                    }
                } else if plugin_finalize_aggregation(plugin) {
                    merged.insert(name.clone(), plugin_pipeline_aggregation_value(merged, plugin));
                }
            }
            _ => {}
        }
    }
    finalize_bucket_pipeline_aggregation_response(merged, aggregation_map);
    for (name, aggregation) in aggregation_map {
        if let Aggregation::Metric(metric) = aggregation {
            if matches!(metric.kind, os_query_dsl::MetricAggregationKind::Avg) {
                if let Some(metric_value) = merged.get_mut(name).and_then(Value::as_object_mut) {
                    metric_value.remove("_count");
                }
            }
            if matches!(metric.kind, os_query_dsl::MetricAggregationKind::WeightedAvg) {
                if let Some(metric_value) = merged.get_mut(name).and_then(Value::as_object_mut) {
                    metric_value.remove("_count");
                }
            }
            if matches!(metric.kind, os_query_dsl::MetricAggregationKind::Cardinality) {
                if let Some(metric_value) = merged.get_mut(name).and_then(Value::as_object_mut) {
                    metric_value.remove("_distinct_values");
                }
            }
            if matches!(
                metric.kind,
                os_query_dsl::MetricAggregationKind::Percentiles
                    | os_query_dsl::MetricAggregationKind::PercentileRanks
                    | os_query_dsl::MetricAggregationKind::MedianAbsoluteDeviation
                    | os_query_dsl::MetricAggregationKind::Boxplot
            ) {
                if let Some(metric_value) = merged.get_mut(name).and_then(Value::as_object_mut) {
                    metric_value.remove("_values");
                }
            }
        }
        if let Aggregation::Terms(terms) = aggregation {
            if let Some(value) = merged.get_mut(name) {
                finalize_terms_aggregation_value(value, terms.size);
            }
        }
        if let Aggregation::Composite(composite) = aggregation {
            if let Some(value) = merged.get_mut(name) {
                finalize_composite_aggregation_value(value, composite.size);
            }
        }
        if let Aggregation::SignificantTerms(significant_terms) = aggregation {
            if let Some(value) = merged.get_mut(name) {
                finalize_significant_terms_aggregation_value(value, significant_terms.size);
            }
        }
        if let Aggregation::Plugin(plugin) = aggregation {
            if !plugin_has_valid_request_surface_for_merge_or_finalize(plugin) {
                merged.insert(name.clone(), collect_plugin_aggregation_placeholder(plugin));
                continue;
            }
            if matches!(plugin.kind.as_str(), "terms" | "multi_terms") {
                if let Some(value) = merged.get_mut(name) {
                    finalize_plugin_terms_aggregation_value(value, plugin);
                }
            }
            if plugin.kind == "rare_terms" {
                if let Some(value) = merged.get_mut(name) {
                    finalize_plugin_rare_terms_aggregation_value(value, plugin);
                }
            }
            if plugin_kind_uses_significant_terms_carrier(&plugin.kind) {
                if let Some(value) = merged.get_mut(name) {
                    finalize_plugin_significant_terms_aggregation_value(value, plugin);
                }
            }
            if plugin.kind == "composite" {
                let Some((size, _, _)) = plugin_composite_setup(plugin) else {
                    merged.insert(name.clone(), collect_plugin_aggregation_placeholder(plugin));
                    continue;
                };
                if let Some(value) = merged.get_mut(name) {
                    finalize_composite_aggregation_value(value, size);
                }
            }
            if let Some(subaggregation_map) = plugin_subaggregation_map(plugin) {
                finalize_wrapper_nested_aggregation_value(merged, name, plugin, &subaggregation_map);
                if matches!(plugin.kind.as_str(), "filters" | "adjacency_matrix") {
                    finalize_plugin_bucketed_nested_aggregation_value(
                        merged,
                        name,
                        &subaggregation_map,
                    );
                }
                if matches!(
                    plugin.kind.as_str(),
                    "terms"
                        | "rare_terms"
                        | "multi_terms"
                        | "range"
                        | "ip_range"
                        | "date_range"
                        | "geo_distance"
                        | "histogram"
                        | "date_histogram"
                        | "significant_terms"
                        | "significant_text"
                        | "composite"
                        | "auto_date_histogram"
                        | "variable_width_histogram"
                ) {
                    finalize_plugin_array_bucketed_nested_aggregation_value(
                        merged,
                        name,
                        &subaggregation_map,
                    );
                }
            }
            if matches!(
                plugin.kind.as_str(),
                "global" | "sampler" | "random_sampler" | "diversified_sampler"
            ) {
                if let Some(metric_value) = merged.get_mut(name).and_then(Value::as_object_mut) {
                    metric_value.remove("_avg_count_hints");
                    metric_value.remove("_cardinality_value_hints");
                    metric_value.remove("_percentile_value_hints");
                }
            }
            if plugin.kind == "cardinality" {
                if let Some(metric_value) = merged.get_mut(name).and_then(Value::as_object_mut) {
                    metric_value.remove("_distinct_values");
                }
            }
            if matches!(
                plugin.kind.as_str(),
                "percentiles"
                    | "percentile_ranks"
                    | "median_absolute_deviation"
                    | "boxplot"
            ) {
                if let Some(metric_value) = merged.get_mut(name).and_then(Value::as_object_mut) {
                    metric_value.remove("_values");
                }
            }
        }
    }
}

fn finalize_wrapper_nested_aggregation_value(
    merged: &mut serde_json::Map<String, Value>,
    name: &str,
    plugin: &os_query_dsl::PluginAggregation,
    subaggregation_map: &AggregationMap,
) {
    let Some(wrapper_value) = merged.get_mut(name).and_then(Value::as_object_mut) else {
        return;
    };
    let mut nested = wrapper_value
        .iter()
        .filter(|(field, _)| {
            field.as_str() != "doc_count"
                && field.as_str() != "_plugin"
                && field.as_str() != "_type"
                && field.as_str() != "params"
                && field.as_str() != "_avg_count_hints"
                && field.as_str() != "_cardinality_value_hints"
                && field.as_str() != "_percentile_value_hints"
        })
        .map(|(field, value)| (field.clone(), value.clone()))
        .collect::<serde_json::Map<_, _>>();
    finalize_merged_pipeline_aggregations(&mut nested, subaggregation_map);
    if matches!(
        plugin.kind.as_str(),
        "global" | "sampler" | "random_sampler" | "diversified_sampler"
    ) {
        wrapper_value.remove("_avg_count_hints");
        wrapper_value.remove("_cardinality_value_hints");
        wrapper_value.remove("_percentile_value_hints");
    }
    let stale_nested_fields = wrapper_value
        .keys()
        .filter(|field| {
            field.as_str() != "doc_count"
                && field.as_str() != "_plugin"
                && field.as_str() != "_type"
                && field.as_str() != "params"
        })
        .cloned()
        .collect::<Vec<_>>();
    for field in stale_nested_fields {
        wrapper_value.remove(&field);
    }
    for (field, value) in nested {
        wrapper_value.insert(field, value);
    }
}

fn finalize_plugin_bucketed_nested_aggregation_value(
    merged: &mut serde_json::Map<String, Value>,
    name: &str,
    subaggregation_map: &AggregationMap,
) {
    let Some(wrapper_value) = merged.get_mut(name).and_then(Value::as_object_mut) else {
        return;
    };
    let finalize_bucket_object = |buckets: &mut serde_json::Map<String, Value>| {
        for bucket_value in buckets.values_mut() {
            let Some(bucket_object) = bucket_value.as_object_mut() else {
                continue;
            };
            let mut nested = bucket_object
                .iter()
                .filter(|(field, _)| {
                    field.as_str() != "doc_count"
                        && field.as_str() != "_avg_count_hints"
                        && field.as_str() != "_cardinality_value_hints"
                        && field.as_str() != "_percentile_value_hints"
                })
                .map(|(field, value)| (field.clone(), value.clone()))
                .collect::<serde_json::Map<_, _>>();
            finalize_merged_pipeline_aggregations(&mut nested, subaggregation_map);
            bucket_object.remove("_avg_count_hints");
            bucket_object.remove("_cardinality_value_hints");
            bucket_object.remove("_percentile_value_hints");
            let stale_nested_fields = bucket_object
                .keys()
                .filter(|field| field.as_str() != "doc_count")
                .cloned()
                .collect::<Vec<_>>();
            for field in stale_nested_fields {
                bucket_object.remove(&field);
            }
            for (field, value) in nested {
                bucket_object.insert(field, value);
            }
        }
    };
    let mut buckets = take_object_bucket_object_carrier(wrapper_value);
    finalize_bucket_object(&mut buckets);
    let extra_fields = wrapper_value
        .iter()
        .filter(|(field, _)| field.as_str() != "_merge_buckets" && field.as_str() != "buckets")
        .map(|(field, value)| (field.clone(), value.clone()))
        .collect::<serde_json::Map<String, Value>>();
    *wrapper_value = value_with_attached_fields(
        bucket_object_visible_and_carrier_value(buckets),
        extra_fields,
    )
    .as_object()
    .cloned()
    .unwrap_or_default();
}

fn finalize_plugin_array_bucketed_nested_aggregation_value(
    merged: &mut serde_json::Map<String, Value>,
    name: &str,
    subaggregation_map: &AggregationMap,
) {
    let Some(wrapper_value) = merged.get_mut(name).and_then(Value::as_object_mut) else {
        return;
    };
    let finalize_bucket_array = |buckets: &mut Vec<Value>| {
        for bucket_value in buckets.iter_mut() {
            let Some(bucket_object) = bucket_value.as_object_mut() else {
                continue;
            };
            let structural_fields = bucket_object
                .iter()
                .filter(|(field, _)| {
                    matches!(
                        field.as_str(),
                        "key" | "key_as_string" | "doc_count" | "bg_count" | "score" | "from" | "to"
                    )
                })
                .map(|(field, value)| (field.clone(), value.clone()))
                .collect::<serde_json::Map<String, Value>>();
            let mut nested =
                array_bucketed_plugin_nested_fields(&Value::Object(bucket_object.clone()));
            finalize_merged_pipeline_aggregations(&mut nested, subaggregation_map);
            bucket_object.remove("_avg_count_hints");
            bucket_object.remove("_cardinality_value_hints");
            bucket_object.remove("_percentile_value_hints");
            let stale_nested_fields = bucket_object
                .keys()
                .filter(|field| {
                    !matches!(
                        field.as_str(),
                        "key" | "key_as_string" | "doc_count" | "bg_count" | "score" | "from" | "to"
                    )
                })
                .cloned()
                .collect::<Vec<_>>();
            for field in stale_nested_fields {
                bucket_object.remove(&field);
            }
            for (field, value) in structural_fields {
                bucket_object.insert(field, value);
            }
            for (field, value) in nested {
                bucket_object.insert(field, value);
            }
        }
    };
    let existing_visible_buckets = wrapper_value.get("buckets").and_then(Value::as_array).cloned();
    let mut buckets = take_object_bucket_array_carrier(wrapper_value);
    finalize_bucket_array(&mut buckets);
    let visible_buckets = if let Some(existing_visible_buckets) = existing_visible_buckets {
        let merge_bucket_map = buckets
            .iter()
            .filter_map(|bucket| {
                let key = bucket.get("key")?.clone();
                Some((
                    serde_json::to_string(&key).unwrap_or_else(|_| key.to_string()),
                    bucket.clone(),
                ))
            })
            .collect::<BTreeMap<_, _>>();
        existing_visible_buckets
            .iter()
            .map(|bucket| {
                let key = bucket.get("key").cloned().unwrap_or(Value::Null);
                let bucket_key =
                    serde_json::to_string(&key).unwrap_or_else(|_| key.to_string());
                merge_bucket_map
                    .get(&bucket_key)
                    .cloned()
                    .unwrap_or_else(|| bucket.clone())
            })
            .collect::<Vec<_>>()
    } else {
        buckets.clone()
    };
    let extra_fields = wrapper_value
        .iter()
        .filter(|(field, _)| field.as_str() != "_merge_buckets" && field.as_str() != "buckets")
        .map(|(field, value)| (field.clone(), value.clone()))
        .collect::<serde_json::Map<String, Value>>();
    *wrapper_value = object_merge_and_visible_array_value_with_fields(
        "_merge_buckets",
        "buckets",
        buckets,
        visible_buckets,
        extra_fields,
    )
    .as_object()
    .cloned()
    .unwrap_or_default();
}

fn finalize_bucket_pipeline_aggregation_response(
    response: &mut serde_json::Map<String, Value>,
    aggregation_map: &AggregationMap,
) {
    for (name, aggregation) in aggregation_map {
        match aggregation {
            Aggregation::BucketSort(bucket_sort) => {
                response.insert(
                    name.clone(),
                    bucket_surface_wrapper_value(collect_bucket_sort_aggregation_value(
                        response,
                        &bucket_sort.aggregation,
                        &bucket_sort.sort,
                        bucket_sort.from,
                        bucket_sort.size,
                    )),
                );
            }
            Aggregation::BucketCount(bucket_count) => {
                response.insert(
                    name.clone(),
                    collect_bucket_count_aggregation_value(response, &bucket_count.aggregation),
                );
            }
            Aggregation::Normalize(normalize) => {
                response.insert(
                    name.clone(),
                    bucket_surface_wrapper_value(collect_normalize_aggregation_value(
                        response,
                        &normalize.aggregation,
                        &normalize.path,
                    )),
                );
            }
            Aggregation::BucketSelector(bucket_selector) => {
                response.insert(
                    name.clone(),
                    bucket_surface_wrapper_value(collect_bucket_selector_aggregation_value(
                        response,
                        &bucket_selector.aggregation,
                        &bucket_selector.path,
                        &bucket_selector.op,
                        bucket_selector.value,
                    )),
                );
            }
            Aggregation::BucketScript(bucket_script) => {
                response.insert(
                    name.clone(),
                    bucket_surface_wrapper_value(collect_bucket_script_aggregation_value(
                        response,
                        &bucket_script.aggregation,
                        &bucket_script.path,
                        &bucket_script.script,
                        &bucket_script.params,
                    )),
                );
            }
            Aggregation::Pipeline(pipeline) => {
                response.insert(name.clone(), collect_pipeline_aggregation(response, pipeline));
            }
            Aggregation::Plugin(plugin) => {
                if plugin_finalize_aggregation(plugin) {
                    if !plugin_has_valid_request_surface_for_merge_or_finalize(plugin) {
                        response.insert(
                            name.clone(),
                            collect_plugin_aggregation_placeholder(plugin),
                        );
                    } else {
                        response.insert(
                            name.clone(),
                            plugin_pipeline_aggregation_value(response, plugin),
                        );
                    }
                }
            }
            _ => {}
        }
    }
}

fn merge_scripted_metric_aggregation_value(
    merged: &mut serde_json::Map<String, Value>,
    name: &str,
    value: &Value,
) {
    merged.entry(name.to_string()).or_insert_with(|| value.clone());
}

fn merge_missing_aggregation_value(
    merged: &mut serde_json::Map<String, Value>,
    name: &str,
    value: &Value,
) {
    let next = value.get("doc_count").and_then(|value| value.as_u64()).unwrap_or(0);
    let entry = merged
        .entry(name.to_string())
        .or_insert_with(|| object_value_with_field("doc_count", Value::from(0)));
    let current = entry.get("doc_count").and_then(|value| value.as_u64()).unwrap_or(0);
    *entry = object_value_with_field("doc_count", Value::from(current.saturating_add(next)));
}

fn merge_terms_aggregation_value(
    merged: &mut serde_json::Map<String, Value>,
    name: &str,
    value: &Value,
) {
    let buckets = value_object_bucket_array_carrier(value);
    if buckets.is_empty() {
        return;
    }
    let entry = merged
        .entry(name.to_string())
        .or_insert_with(|| bucket_array_visible_and_carrier_value(Vec::new()));
    let Some(entry_object) = entry.as_object_mut() else {
        return;
    };
    let mut merged_buckets = take_object_bucket_array_carrier(entry_object);
    let mut bucket_map = merged_buckets
        .iter()
        .enumerate()
        .filter_map(|(index, bucket)| {
            bucket.get("key").map(|key| {
                (
                    serde_json::to_string(key).unwrap_or_else(|_| key.to_string()),
                    index,
                )
            })
        })
        .collect::<BTreeMap<_, _>>();
    for bucket in buckets {
        let key = bucket.get("key").cloned().unwrap_or(Value::Null);
        let bucket_key = serde_json::to_string(&key).unwrap_or_else(|_| key.to_string());
        let doc_count = bucket.get("doc_count").and_then(|value| value.as_u64()).unwrap_or(0);
        if let Some(index) = bucket_map.get(&bucket_key).copied() {
            if let Some(current) = merged_buckets[index].get_mut("doc_count") {
                *current = Value::from(current.as_u64().unwrap_or(0).saturating_add(doc_count));
            }
        } else {
            merged_buckets.push(serde_json::json!({
                "key": key,
                "doc_count": doc_count
            }));
            bucket_map.insert(bucket_key, merged_buckets.len() - 1);
        }
    }
    merged_buckets.sort_by(|left, right| {
        let left_count = left.get("doc_count").and_then(|value| value.as_u64()).unwrap_or(0);
        let right_count = right.get("doc_count").and_then(|value| value.as_u64()).unwrap_or(0);
        right_count
            .cmp(&left_count)
            .then_with(|| {
                let left_key = left.get("key").cloned().unwrap_or(Value::Null);
                let right_key = right.get("key").cloned().unwrap_or(Value::Null);
                bucket_sort_key(&left_key).cmp(&bucket_sort_key(&right_key))
            })
    });
    *entry = bucket_array_visible_and_carrier_value(merged_buckets);
}

