fn plugin_terms_bucket_value(
    key: Value,
    doc_count: u64,
    nested_aggregations: Option<Value>,
    nested_reduce_hints: Option<(
        BTreeMap<String, u64>,
        BTreeMap<String, std::collections::BTreeSet<String>>,
        BTreeMap<String, Vec<f64>>,
    )>,
) -> Value {
    let object = object_value_with_fields(
        [
            ("key".to_string(), key),
            ("doc_count".to_string(), Value::from(doc_count)),
        ]
        .into_iter()
        .collect(),
    )
    .as_object()
    .cloned()
    .unwrap_or_default();
    plugin_bucket_value_from_existing_fields(object, nested_aggregations, nested_reduce_hints)
}

fn plugin_bucket_value_from_existing_fields(
    mut object: serde_json::Map<String, Value>,
    nested_aggregations: Option<Value>,
    nested_reduce_hints: Option<(
        BTreeMap<String, u64>,
        BTreeMap<String, std::collections::BTreeSet<String>>,
        BTreeMap<String, Vec<f64>>,
    )>,
) -> Value {
    if let Some(nested_aggregations) = nested_aggregations {
        if let Some(nested_object) = nested_aggregations.as_object() {
            for (name, value) in nested_object {
                object.insert(name.clone(), value.clone());
            }
        }
    }
    if let Some((avg_count_hints, cardinality_value_hints, percentile_value_hints)) =
        nested_reduce_hints
    {
        insert_plugin_nested_reduce_hints(
            &mut object,
            &avg_count_hints,
            &cardinality_value_hints,
            &percentile_value_hints,
        );
    }
    Value::Object(object)
}

