fn plugin_composite_sources(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<Vec<os_query_dsl::CompositeTermsSource>> {
    let values = plugin.params.get("sources")?.as_array()?;
    if values.is_empty() {
        return None;
    }
    values
        .iter()
        .map(|source| {
            let object = source.as_object()?;
            if object.len() != 1 {
                return None;
            }
            let (name, body) = object.iter().next()?;
            let field = body
                .get("terms")
                .and_then(|terms| terms.get("field"))
                .and_then(Value::as_str)
                .filter(|field| !field.is_empty())?;
            Some(os_query_dsl::CompositeTermsSource {
                name: name.clone(),
                field: field.to_string(),
            })
        })
        .collect::<Option<Vec<_>>>()
}

