fn collect_significant_terms_aggregation(
    hits: &[SearchHit],
    all_hits: &[SearchHit],
    significant_terms: &os_query_dsl::SignificantTermsAggregation,
) -> Value {
    let mut buckets = BTreeMap::<String, (Value, u64)>::new();
    let mut background_counts = BTreeMap::<String, u64>::new();

    for hit in all_hits {
        let Some(value) = source_value_for_highlight_field(&hit.source, &significant_terms.field) else {
            continue;
        };
        for value in distinct_scalar_bucket_values(value) {
            *background_counts.entry(bucket_sort_key(&value)).or_insert(0) += 1;
        }
    }

    for hit in hits {
        let Some(value) = source_value_for_highlight_field(&hit.source, &significant_terms.field) else {
            continue;
        };
        for value in distinct_scalar_bucket_values(value) {
            let bucket_key = bucket_sort_key(&value);
            let (_, doc_count) = buckets
                .entry(bucket_key)
                .or_insert_with(|| (value.clone(), 0));
            *doc_count += 1;
        }
    }

    let total_doc_count = hits.len() as u64;
    let total_bg_count = all_hits.len() as u64;
    let mut buckets = buckets
        .into_values()
        .map(|(key, doc_count)| {
            let bg_count = background_counts
                .get(&bucket_sort_key(&key))
                .copied()
                .unwrap_or(doc_count);
            serde_json::json!({
                "key": key,
                "doc_count": doc_count,
                "bg_count": bg_count,
                "score": significant_terms_score(doc_count, bg_count, total_doc_count, total_bg_count)
            })
        })
        .collect::<Vec<_>>();
    sort_significant_terms_buckets_by_score_desc(&mut buckets);

    bucket_array_visible_and_carrier_value_with_fields(
        buckets,
        [
            ("doc_count".to_string(), Value::from(total_doc_count)),
            ("bg_count".to_string(), Value::from(total_bg_count)),
        ]
        .into_iter()
        .collect(),
    )
}

fn collect_significant_terms_aggregation_from_documents(
    documents: &[&StoredDocument],
    all_documents: &[&StoredDocument],
    significant_terms: &os_query_dsl::SignificantTermsAggregation,
) -> Value {
    let mut buckets = BTreeMap::<String, (Value, u64)>::new();
    let mut background_counts = BTreeMap::<String, u64>::new();

    for document in all_documents {
        let Some(value) =
            source_value_for_highlight_field(&document.source, &significant_terms.field)
        else {
            continue;
        };
        for value in distinct_scalar_bucket_values(value) {
            *background_counts.entry(bucket_sort_key(&value)).or_insert(0) += 1;
        }
    }

    for document in documents {
        let Some(value) =
            source_value_for_highlight_field(&document.source, &significant_terms.field)
        else {
            continue;
        };
        for value in distinct_scalar_bucket_values(value) {
            let bucket_key = bucket_sort_key(&value);
            let (_, doc_count) = buckets
                .entry(bucket_key)
                .or_insert_with(|| (value.clone(), 0));
            *doc_count += 1;
        }
    }

    let total_doc_count = documents.len() as u64;
    let total_bg_count = all_documents.len() as u64;
    let mut buckets = buckets
        .into_values()
        .map(|(key, doc_count)| {
            let bg_count = background_counts
                .get(&bucket_sort_key(&key))
                .copied()
                .unwrap_or(doc_count);
            serde_json::json!({
                "key": key,
                "doc_count": doc_count,
                "bg_count": bg_count,
                "score": significant_terms_score(doc_count, bg_count, total_doc_count, total_bg_count)
            })
        })
        .collect::<Vec<_>>();
    sort_significant_terms_buckets_by_score_desc(&mut buckets);

    bucket_array_visible_and_carrier_value_with_fields(
        buckets,
        [
            ("doc_count".to_string(), Value::from(total_doc_count)),
            ("bg_count".to_string(), Value::from(total_bg_count)),
        ]
        .into_iter()
        .collect(),
    )
}

fn collect_composite_aggregation(
    hits: &[SearchHit],
    composite: &os_query_dsl::CompositeAggregation,
) -> Value {
    let mut buckets = BTreeMap::<String, (Value, u64)>::new();

    for hit in hits {
        for key in composite_keys_from_source(&hit.source, &composite.sources) {
            let bucket_key = serde_json::to_string(&key).unwrap_or_else(|_| key.to_string());
            let (_, doc_count) = buckets.entry(bucket_key).or_insert_with(|| (key, 0));
            *doc_count += 1;
        }
    }

    collect_composite_aggregation_value(buckets, composite.size, None, &composite.sources)
}

fn collect_composite_aggregation_from_documents(
    documents: &[&StoredDocument],
    composite: &os_query_dsl::CompositeAggregation,
) -> Value {
    let mut buckets = BTreeMap::<String, (Value, u64)>::new();

    for document in documents {
        for key in composite_keys_from_source(&document.source, &composite.sources) {
            let bucket_key = serde_json::to_string(&key).unwrap_or_else(|_| key.to_string());
            let (_, doc_count) = buckets.entry(bucket_key).or_insert_with(|| (key, 0));
            *doc_count += 1;
        }
    }

    collect_composite_aggregation_value(buckets, composite.size, None, &composite.sources)
}

fn compare_composite_keys(
    left: &Value,
    right: &Value,
    sources: &[os_query_dsl::CompositeTermsSource],
) -> std::cmp::Ordering {
    let Some(left_object) = left.as_object() else {
        return std::cmp::Ordering::Equal;
    };
    let Some(right_object) = right.as_object() else {
        return std::cmp::Ordering::Equal;
    };
    for source in sources {
        let ordering = compare_optional_owned_sort_values(
            left_object.get(&source.name).cloned(),
            right_object.get(&source.name).cloned(),
        );
        if !ordering.is_eq() {
            return ordering;
        }
    }
    std::cmp::Ordering::Equal
}

fn collect_composite_aggregation_value(
    buckets: BTreeMap<String, (Value, u64)>,
    size: usize,
    after: Option<&Value>,
    sources: &[os_query_dsl::CompositeTermsSource],
) -> Value {
    let mut bucket_values = buckets
        .into_values()
        .filter(|(key, _)| {
            after.map_or(true, |after_key| {
                compare_composite_keys(key, after_key, sources).is_gt()
            })
        })
        .map(|(key, doc_count)| {
            serde_json::json!({
                "key": key,
                "doc_count": doc_count
            })
        })
        .collect::<Vec<_>>();
    bucket_values.sort_by(|left, right| {
        compare_composite_keys(
            left.get("key").unwrap_or(&Value::Null),
            right.get("key").unwrap_or(&Value::Null),
            sources,
        )
    });
    bucket_values.truncate(size);
    let extra_fields = bucket_values
        .last()
        .and_then(|bucket| bucket.get("key"))
        .cloned()
        .map(|after_key| {
            [("after_key".to_string(), after_key)]
                .into_iter()
                .collect::<serde_json::Map<String, Value>>()
        })
        .unwrap_or_default();

    bucket_array_visible_and_carrier_value_with_fields(bucket_values, extra_fields)
}

fn composite_key(source: &Value, sources: &[os_query_dsl::CompositeTermsSource]) -> Option<Value> {
    let mut key = serde_json::Map::new();

    for terms_source in sources {
        let value = source_value_for_highlight_field(source, &terms_source.field)
            .filter(|value| is_scalar_value(value))?;
        key.insert(terms_source.name.clone(), value.clone());
    }

    Some(Value::Object(key))
}

fn composite_keys_from_source(
    source: &Value,
    sources: &[os_query_dsl::CompositeTermsSource],
) -> Vec<Value> {
    let mut source_values = Vec::with_capacity(sources.len());
    for terms_source in sources {
        let Some(value) = source_value_for_highlight_field(source, &terms_source.field) else {
            return Vec::new();
        };
        let values = distinct_scalar_bucket_values(value);
        if values.is_empty() {
            return Vec::new();
        }
        source_values.push((terms_source.name.clone(), values));
    }

    fn visit(
        index: usize,
        source_values: &[(String, Vec<Value>)],
        current: &mut serde_json::Map<String, Value>,
        keys: &mut BTreeMap<String, Value>,
    ) {
        if index == source_values.len() {
            let key = Value::Object(current.clone());
            let serialized = serde_json::to_string(&key).unwrap_or_else(|_| key.to_string());
            keys.entry(serialized).or_insert(key);
            return;
        }

        let (name, values) = &source_values[index];
        for value in values {
            current.insert(name.clone(), value.clone());
            visit(index + 1, source_values, current, keys);
        }
        current.remove(name);
    }

    let mut keys = BTreeMap::new();
    visit(
        0,
        &source_values,
        &mut serde_json::Map::new(),
        &mut keys,
    );
    keys.into_values().collect()
}

fn collect_date_histogram_aggregation(
    hits: &[SearchHit],
    date_histogram: &os_query_dsl::DateHistogramAggregation,
) -> EngineResult<Value> {
    if normalize_date_histogram_interval(&date_histogram.interval).is_none() {
        return Err(invalid_request(format!(
            "unsupported date_histogram interval [{}]",
            date_histogram.interval
        )));
    }
    let mut counts = std::collections::BTreeMap::<i64, (String, u64)>::new();
    for hit in hits {
        let Some(raw) = source_value_for_highlight_field(&hit.source, &date_histogram.field) else {
            continue;
        };
        for (bucket_key, bucket_string) in
            distinct_date_histogram_buckets(raw, &date_histogram.interval)
        {
            let entry = counts.entry(bucket_key).or_insert((bucket_string, 0));
            entry.1 += 1;
        }
    }
    let bucket_values = counts
        .into_iter()
        .map(|(key, (key_as_string, doc_count))| serde_json::json!({
            "key": key,
            "key_as_string": key_as_string,
            "doc_count": doc_count,
        }))
        .collect::<Vec<_>>();
    Ok(bucket_array_visible_and_carrier_value(bucket_values))
}

fn collect_date_histogram_aggregation_from_documents(
    documents: &[&StoredDocument],
    date_histogram: &os_query_dsl::DateHistogramAggregation,
) -> EngineResult<Value> {
    if normalize_date_histogram_interval(&date_histogram.interval).is_none() {
        return Err(invalid_request(format!(
            "unsupported date_histogram interval [{}]",
            date_histogram.interval
        )));
    }
    let mut counts = std::collections::BTreeMap::<i64, (String, u64)>::new();
    let top_level_field = !date_histogram.field.contains('.');
    for document in documents {
        if top_level_field {
            if let Some(epoch_millis) = document
                .top_level_date_millis_fields
                .get(&date_histogram.field)
                .copied()
            {
                if let Some((bucket_key, bucket_string)) =
                    date_histogram_bucket_from_epoch_millis(epoch_millis, &date_histogram.interval)
                {
                    let entry = counts.entry(bucket_key).or_insert((bucket_string, 0));
                    entry.1 += 1;
                }
                continue;
            }
        }
        let Some(raw) = document_source_value_for_prechecked_aggregation_field(
            document,
            &date_histogram.field,
            top_level_field,
        )
        else {
            continue;
        };
        match raw {
            Value::Array(_) => {
                for (bucket_key, bucket_string) in
                    distinct_date_histogram_buckets(raw, &date_histogram.interval)
                {
                    let entry = counts.entry(bucket_key).or_insert((bucket_string, 0));
                    entry.1 += 1;
                }
            }
            _ => {
                if let Some((bucket_key, bucket_string)) =
                    date_histogram_bucket(raw, &date_histogram.interval)
                {
                    let entry = counts.entry(bucket_key).or_insert((bucket_string, 0));
                    entry.1 += 1;
                }
            }
        }
    }
    let bucket_values = counts
        .into_iter()
        .map(|(key, (key_as_string, doc_count))| {
            let mut bucket = serde_json::Map::with_capacity(3);
            bucket.insert("key".to_string(), Value::from(key));
            bucket.insert("key_as_string".to_string(), Value::String(key_as_string));
            bucket.insert("doc_count".to_string(), Value::from(doc_count));
            Value::Object(bucket)
        })
        .collect::<Vec<_>>();
    Ok(bucket_array_visible_and_carrier_value(bucket_values))
}

fn histogram_bucket_key(value: f64, interval: f64) -> Option<f64> {
    if !interval.is_finite() || interval <= 0.0 || !value.is_finite() {
        return None;
    }
    Some((value / interval).floor() * interval)
}

fn choose_variable_width_histogram_interval_from_values<'a, I>(
    values: I,
    target_buckets: usize,
) -> f64
where
    I: IntoIterator<Item = &'a Value>,
{
    let numeric_values = values
        .into_iter()
        .flat_map(numeric_values_from_value)
        .collect::<Vec<_>>();
    if numeric_values.len() <= 1 {
        return 1.0;
    }
    let target_buckets = target_buckets.max(1);
    let min = numeric_values.iter().copied().reduce(f64::min).unwrap_or(0.0);
    let max = numeric_values.iter().copied().reduce(f64::max).unwrap_or(min);
    let span = (max - min).abs();
    if !span.is_finite() || span == 0.0 {
        return 1.0;
    }
    let interval = span / (target_buckets as f64);
    if !interval.is_finite() || interval <= 0.0 {
        1.0
    } else {
        interval
    }
}

fn rebucket_histogram_buckets_to_interval(
    buckets: &[Value],
    target_interval: f64,
    aggregation_map: Option<&AggregationMap>,
) -> Vec<Value> {
    let mut counts = std::collections::BTreeMap::<
        u64,
        (
            f64,
            u64,
            serde_json::Map<String, Value>,
            BTreeMap<String, u64>,
            BTreeMap<String, std::collections::BTreeSet<String>>,
            BTreeMap<String, Vec<f64>>,
        ),
    >::new();
    for bucket in buckets {
        let Some(value) = bucket.get("key").and_then(Value::as_f64) else {
            continue;
        };
        let doc_count = bucket.get("doc_count").and_then(|value| value.as_u64()).unwrap_or(0);
        let Some(target_key) = histogram_bucket_key(value, target_interval) else {
            continue;
        };
        let entry = counts.entry(target_key.to_bits()).or_insert((
            target_key,
            0,
            serde_json::Map::new(),
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
        ));
        entry.1 = entry.1.saturating_add(doc_count);
        if let Some(aggregation_map) = aggregation_map {
            let (avg_count_hints, cardinality_value_hints, percentile_value_hints) =
                plugin_nested_reduce_hints_from_value(bucket);
            merge_native_aggregation_response(
                &mut entry.2,
                aggregation_map,
                Value::Object(array_bucketed_plugin_nested_fields(bucket)),
                &avg_count_hints,
                &cardinality_value_hints,
                &percentile_value_hints,
            );
            for (name, count) in avg_count_hints {
                *entry.3.entry(name).or_default() += count;
            }
            for (name, values) in cardinality_value_hints {
                entry.4.entry(name).or_default().extend(values);
            }
            for (name, values) in percentile_value_hints {
                entry.5.entry(name).or_default().extend(values);
            }
        }
    }
    counts
        .into_values()
        .map(|(key, doc_count, nested_merged, avg_count_hints, cardinality_value_hints, percentile_value_hints)| {
            let object = object_value_with_fields(
                [
                    ("key".to_string(), Value::from(key)),
                    ("doc_count".to_string(), Value::from(doc_count)),
                ]
                .into_iter()
                .collect(),
            )
            .as_object()
            .cloned()
            .unwrap_or_default();
            if aggregation_map.is_some() {
                plugin_bucket_value_from_existing_fields(
                    object,
                    Some(Value::Object(nested_merged)),
                    Some((
                        avg_count_hints,
                        cardinality_value_hints,
                        percentile_value_hints,
                    )),
                )
            } else {
                Value::Object(object)
            }
        })
        .collect::<Vec<_>>()
}

fn coarsen_variable_width_histogram_buckets_until_target(
    buckets: &[Value],
    interval: f64,
    target_buckets: usize,
    aggregation_map: Option<&AggregationMap>,
) -> (f64, Vec<Value>) {
    let target_buckets = target_buckets.max(1);
    let mut current_interval = if interval.is_finite() && interval > 0.0 {
        interval
    } else {
        1.0
    };
    let mut current_buckets = buckets.to_vec();
    while current_buckets.len() > target_buckets {
        current_interval *= 2.0;
        current_buckets = rebucket_histogram_buckets_to_interval(
            &current_buckets,
            current_interval,
            aggregation_map,
        );
    }
    (current_interval, current_buckets)
}

fn collect_histogram_aggregation_from_values<'a, I>(
    values: I,
    histogram: &os_query_dsl::HistogramAggregation,
) -> Value
where
    I: IntoIterator<Item = &'a Value>,
{
    let mut counts = std::collections::BTreeMap::<u64, (f64, u64)>::new();
    for raw in values {
        let mut matched_bucket_keys = BTreeMap::<u64, f64>::new();
        for value in distinct_scalar_bucket_values(raw) {
            let Some(value) = value.as_f64() else {
                continue;
            };
            let Some(bucket_key) = histogram_bucket_key(value, histogram.interval) else {
                continue;
            };
            matched_bucket_keys
                .entry(bucket_key.to_bits())
                .or_insert(bucket_key);
        }
        for (bucket_key_bits, bucket_key) in matched_bucket_keys {
            let entry = counts.entry(bucket_key_bits).or_insert((bucket_key, 0));
            entry.1 = entry.1.saturating_add(1);
        }
    }
    let bucket_values = counts
        .into_values()
        .map(|(key, doc_count)| serde_json::json!({
            "key": key,
            "doc_count": doc_count
        }))
        .collect::<Vec<_>>();
    bucket_array_visible_and_carrier_value(bucket_values)
}

fn collect_histogram_aggregation_from_documents(
    documents: &[&StoredDocument],
    histogram: &os_query_dsl::HistogramAggregation,
) -> Value {
    collect_histogram_aggregation_from_values(
        documents.iter().filter_map(|document| {
            source_value_for_highlight_field(&document.source, &histogram.field)
        }),
        histogram,
    )
}

fn collect_histogram_aggregation(
    hits: &[SearchHit],
    histogram: &os_query_dsl::HistogramAggregation,
) -> Value {
    collect_histogram_aggregation_from_values(
        hits.iter()
            .filter_map(|hit| source_value_for_highlight_field(&hit.source, &histogram.field)),
        histogram,
    )
}

fn collect_top_hits_aggregation(
    hits: &[SearchHit],
    top_hits: &os_query_dsl::TopHitsAggregation,
) -> Value {
    collect_top_hits_aggregation_with_input_order(
        hits,
        top_hits,
        PluginTopHitsInputOrder::NeedsExplicitSort,
    )
}

fn collect_top_hits_aggregation_with_input_order(
    hits: &[SearchHit],
    top_hits: &os_query_dsl::TopHitsAggregation,
    input_order: PluginTopHitsInputOrder,
) -> Value {
    let mut ordered_hits = hits.to_vec();
    if !matches!(input_order, PluginTopHitsInputOrder::CallerFinal) && ordered_hits.len() > 1 {
        ordered_hits.sort_by(compare_relevance_hits);
    }
    let selected_hits = ordered_hits
        .iter()
        .skip(top_hits.from)
        .take(top_hits.size)
        .cloned()
        .collect::<Vec<_>>();
    let carrier_hits = ordered_hits
        .iter()
        .take(top_hits.from.saturating_add(top_hits.size))
        .cloned()
        .collect::<Vec<_>>();
    let max_score = selected_hits
        .iter()
        .map(|hit| hit.score)
        .reduce(f32::max)
        .map(Value::from)
        .unwrap_or(Value::Null);
    top_hits_aggregation_value_with_inner_hits(top_hits_inner_value_with_entries(
        ordered_hits.len() as u64,
        max_score,
        carrier_hits
            .iter()
            .map(SearchHit::to_opensearch_body)
            .collect::<Vec<_>>(),
        selected_hits
            .iter()
            .map(SearchHit::to_opensearch_body)
            .collect::<Vec<_>>(),
    ))
}

fn parse_plugin_top_hits_sort_spec(value: &Value) -> Option<SortSpec> {
    let Value::Object(object) = value else {
        return serde_json::from_value::<SortSpec>(value.clone()).ok();
    };
    if object.len() != 1 {
        return serde_json::from_value::<SortSpec>(value.clone()).ok();
    }
    let (field, config) = object.iter().next()?;
    if field == "_script" {
        let Value::Object(script_object) = config else {
            return None;
        };
        return Some(SortSpec {
            field: "_script".to_string(),
            order: script_object
                .get("order")
                .cloned()
                .and_then(|value| serde_json::from_value::<SortOrder>(value).ok())
                .unwrap_or(SortOrder::Asc),
            unmapped_type: None,
            geo_origin: None,
            mode: script_object
                .get("mode")
                .cloned()
                .and_then(|value| serde_json::from_value(value).ok()),
            script: script_object
                .get("script")
                .cloned()
                .and_then(|value| serde_json::from_value(value).ok()),
        });
    }
    match config {
        Value::String(order) => Some(SortSpec {
            field: field.clone(),
            order: serde_json::from_value::<SortOrder>(Value::String(order.clone())).ok()?,
            unmapped_type: None,
            geo_origin: None,
            mode: None,
            script: None,
        }),
        Value::Object(config_object) => Some(SortSpec {
            field: field.clone(),
            order: config_object
                .get("order")
                .cloned()
                .and_then(|value| serde_json::from_value::<SortOrder>(value).ok())
                .unwrap_or(SortOrder::Asc),
            unmapped_type: config_object
                .get("unmapped_type")
                .and_then(Value::as_str)
                .map(ToString::to_string),
            geo_origin: config_object
                .get("geo_origin")
                .and_then(geo_point_value)
                .map(|(lat, lon)| GeoSortOrigin { lat, lon }),
            mode: config_object
                .get("mode")
                .cloned()
                .and_then(|value| serde_json::from_value(value).ok()),
            script: None,
        }),
        _ => None,
    }
}

fn parse_plugin_top_hits_sort_specs(value: &Value) -> Vec<SortSpec> {
    match value {
        Value::Array(values) => values
            .iter()
            .filter_map(parse_plugin_top_hits_sort_spec)
            .collect(),
        _ => parse_plugin_top_hits_sort_spec(value).into_iter().collect(),
    }
}

fn plugin_top_hits_explicit_sort_specs(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<Vec<SortSpec>> {
    let sort_value = plugin.params.get("sort")?;
    let expected_len = match sort_value {
        Value::Array(values) => values.len(),
        Value::Object(_) => 1,
        _ => 0,
    };
    if expected_len == 0 {
        return None;
    }
    let sort_specs = parse_plugin_top_hits_sort_specs(sort_value);
    if sort_specs.len() == expected_len {
        Some(sort_specs)
    } else {
        None
    }
}

fn plugin_top_hits_window_and_sort(
    plugin: &os_query_dsl::PluginAggregation,
) -> Option<(usize, usize, Vec<SortSpec>)> {
    let from = if plugin_param_exists(plugin, "from") {
        plugin_usize_param(plugin, "from")?
    } else {
        0
    };
    let size = if plugin_param_exists(plugin, "size") {
        plugin_usize_param(plugin, "size")?
    } else {
        3
    };
    let sort = if plugin_param_exists(plugin, "sort") {
        plugin_top_hits_explicit_sort_specs(plugin)?
    } else {
        Vec::new()
    };
    Some((from, size, sort))
}

fn collect_plugin_top_hits_aggregation_with_input_order(
    hits: &[SearchHit],
    plugin: &os_query_dsl::PluginAggregation,
    input_order: PluginTopHitsInputOrder,
) -> Value {
    let Some((from, size, sort_specs)) = plugin_top_hits_window_and_sort(plugin) else {
        return collect_plugin_aggregation_placeholder(plugin);
    };
    let mut sorted_hits = hits.to_vec();
    if !sort_specs.is_empty() {
        sort_hits(&mut sorted_hits, &sort_specs);
    } else if matches!(input_order, PluginTopHitsInputOrder::CallerFinal) {
        if sorted_hits.len() > 1 {
            sorted_hits.sort_by(compare_relevance_hits);
        }
    } else if sorted_hits.len() > 1 {
        sorted_hits.sort_by(compare_relevance_hits);
    }
    let selected_hits = sorted_hits
        .iter()
        .skip(from)
        .take(size)
        .cloned()
        .collect::<Vec<_>>();
    let carrier_hits = sorted_hits
        .iter()
        .take(from.saturating_add(size))
        .cloned()
        .collect::<Vec<_>>();
    let max_score = selected_hits
        .iter()
        .map(|hit| hit.score)
        .reduce(f32::max)
        .map(Value::from)
        .unwrap_or(Value::Null);
    plugin_top_hits_aggregation_value(
        plugin,
        top_hits_inner_value_with_entries(
            sorted_hits.len() as u64,
            max_score,
            carrier_hits
                .iter()
                .map(SearchHit::to_opensearch_body)
                .collect::<Vec<_>>(),
            selected_hits
                .iter()
                .map(SearchHit::to_opensearch_body)
                .collect::<Vec<_>>(),
        ),
    )
}

