    #[test]
    fn hybrid_query_candidate_reduction_keeps_zero_minimum_should_match_when_one_optional_clause_cannot_reduce(
    ) {
        let mut engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "vectors".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "embedding": {
                            "type": "knn_vector",
                            "dimension": 3,
                            "space_type": "l2"
                        },
                        "body": { "type": "text" }
                    }
                }),
            })
            .unwrap();

        for (id, body, embedding) in [
            ("a", "alpha", Some(serde_json::json!([1.0, 0.0, 0.0]))),
            ("b", "beta", Some(serde_json::json!([0.9, 0.1, 0.0]))),
            ("c", "gamma", None),
        ] {
            let mut source = serde_json::json!({ "body": body });
            if let Some(embedding) = embedding {
                source["embedding"] = embedding;
            }
            engine
                .index_document(IndexDocumentRequest {
                    index: "vectors".to_string(),
                    id: id.to_string(),
                    source,
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["vectors".to_string()],
            })
            .unwrap();

        let query = Query::Bool {
            clauses: BoolQuery {
                should: vec![
                    Query::Bool {
                        clauses: BoolQuery {
                            minimum_should_match: Some(1),
                            ..BoolQuery::default()
                        },
                    },
                    Query::Knn(KnnQuery {
                        field: "embedding".to_string(),
                        vector: vec![1.0, 0.0, 0.0],
                        k: 2,
                        filter: None,
                        ignore_unmapped: false,
                        max_distance: None,
                        min_score: None,
                        method_parameters: BTreeMap::new(),
                        rescore: None,
                        expand_nested_docs: false,
                    }),
                ],
                minimum_should_match: Some(0),
                ..BoolQuery::default()
            },
        };

        let reduced = engine
            .store.write().unwrap().indices
            .get_mut("vectors")
            .unwrap()
            .search_candidate_ids_for_query_reduced("vectors", &query)
            .unwrap();

        assert_eq!(
            reduced,
            Some(
                ["a".to_string(), "b".to_string(), "c".to_string()]
                    .into_iter()
                    .collect()
            )
        );
    }

