    #[test]
    fn lexical_must_not_only_bool_no_longer_requires_native_candidate_post_filter() {
        let mut engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "docs".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "service": { "type": "keyword" }
                    }
                }),
            })
            .unwrap();
        engine
            .index_document(IndexDocumentRequest {
                index: "docs".to_string(),
                id: "seed".to_string(),
                source: serde_json::json!({ "service": "seed" }),
            })
            .unwrap();
        engine
            .refresh(RefreshRequest {
                indices: vec!["docs".to_string()],
            })
            .unwrap();

        let query = Query::Bool {
            clauses: BoolQuery {
                must_not: vec![Query::Term {
                    field: "service".to_string(),
                    value: Value::String("alpha".to_string()),
                }],
                ..BoolQuery::default()
            },
        };

        let store = engine.store.write().unwrap();
        let search_state = store.indices
            .get("docs")
            .unwrap()
            .search_state
            .as_ref()
            .unwrap();

        assert!(!query_requires_native_candidate_post_filter(&query));
        assert!(build_tantivy_query(search_state, &query).unwrap().is_some());
    }

