    #[test]
    fn hybrid_query_supports_sibling_multiplication_over_alternating_threshold_exclusion_stack() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "vectors".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "embedding_a": {
                            "type": "knn_vector",
                            "dimension": 3,
                            "space_type": "l2"
                        },
                        "embedding_b": {
                            "type": "knn_vector",
                            "dimension": 3,
                            "space_type": "l2"
                        },
                        "body": { "type": "text" }
                    }
                }),
            })
            .unwrap();

        for (id, body, embedding_a, embedding_b) in [
            (
                "a",
                "apple alpha",
                Some(serde_json::json!([1.0, 0.0, 0.0])),
                Some(serde_json::json!([9.0, 9.0, 9.0])),
            ),
            (
                "b",
                "banana beta",
                Some(serde_json::json!([9.0, 9.0, 9.0])),
                Some(serde_json::json!([0.0, 1.0, 0.0])),
            ),
            (
                "c",
                "apple banana",
                Some(serde_json::json!([1.0, 0.0, 0.0])),
                Some(serde_json::json!([0.0, 1.0, 0.0])),
            ),
            (
                "d",
                "orange gamma",
                Some(serde_json::json!([0.0, 1.0, 0.0])),
                Some(serde_json::json!([1.0, 0.0, 0.0])),
            ),
            (
                "e",
                "banana apple",
                Some(serde_json::json!([1.0, 0.0, 0.0])),
                Some(serde_json::json!([0.0, 1.0, 0.0])),
            ),
        ] {
            let mut source = serde_json::json!({ "body": body });
            if let Some(embedding_a) = embedding_a {
                source["embedding_a"] = embedding_a;
            }
            if let Some(embedding_b) = embedding_b {
                source["embedding_b"] = embedding_b;
            }
            engine
                .index_document(IndexDocumentRequest {
                    index: "vectors".to_string(),
                    id: id.to_string(),
                    source,
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["vectors".to_string()],
            })
            .unwrap();

        let apple_a = serde_json::json!({
            "bool": {
                "should": [
                    { "match": { "body": "apple" } },
                    {
                        "knn": {
                            "embedding_a": {
                                "vector": [1.0, 0.0, 0.0],
                                "k": 2
                            }
                        }
                    }
                ],
                "minimum_should_match": 1
            }
        });
        let banana_b = serde_json::json!({
            "bool": {
                "should": [
                    { "match": { "body": "banana" } },
                    {
                        "knn": {
                            "embedding_b": {
                                "vector": [0.0, 1.0, 0.0],
                                "k": 2
                            }
                        }
                    }
                ],
                "minimum_should_match": 1
            }
        });
        let grouped_multi_vector = serde_json::json!({
            "bool": {
                "must": [apple_a.clone(), banana_b.clone()]
            }
        });
        let sibling_group = serde_json::json!({
            "bool": {
                "should": [
                    {
                        "bool": {
                            "must": [grouped_multi_vector.clone()]
                        }
                    },
                    {
                        "bool": {
                            "must": [
                                {
                                    "bool": {
                                        "must": [banana_b.clone(), apple_a.clone()]
                                    }
                                }
                            ]
                        }
                    }
                ],
                "minimum_should_match": 1
            }
        });
        let alternating_stack = serde_json::json!({
            "bool": {
                "should": [
                    {
                        "bool": {
                            "must": [sibling_group.clone()],
                            "must_not": [
                                {
                                    "ids": {
                                        "values": ["e"]
                                    }
                                }
                            ]
                        }
                    }
                ],
                "minimum_should_match": 1
            }
        });

        let hybrid = engine
            .search(SearchRequest {
                indices: vec!["vectors".to_string()],
                query: serde_json::json!({
                    "bool": {
                        "should": [
                            alternating_stack,
                            grouped_multi_vector
                        ],
                        "minimum_should_match": 1
                    }
                }),
                aggregations: serde_json::json!({}),
                sort: Vec::new(),
                from: 0,
                size: 10,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(search_hit_ids(&hybrid.hits), vec!["c", "e"]);
        assert!(hybrid.phase_results.iter().any(|phase| phase.phase == SearchPhase::Query));
    }

