    #[test]
    fn exact_document_native_query_bridge_accepts_hit_only_vector_candidate_window_context() {
        let mut index = StoredIndex::new("vectors");
        index
            .ensure_dynamic_mappings(&serde_json::json!({
                "embedding": [1.0, 0.0, 0.0],
                "body": "alpha"
            }))
            .unwrap();

        for (id, body, embedding) in [
            ("a", "alpha", serde_json::json!([9.0, 9.0, 9.0])),
            ("b", "beta", serde_json::json!([0.0, 1.0, 0.0])),
            ("c", "target", serde_json::json!([1.0, 0.0, 0.0])),
        ] {
            index.apply_primary_document(
                id.to_string(),
                serde_json::json!({
                    "body": body,
                    "embedding": embedding
                }),
            );
        }
        index.refreshed_seq_no = index.next_seq_no.saturating_sub(1);
        index.rebuild_tantivy_search_state().unwrap();

        let query = parse_query_value(&serde_json::json!({
            "knn": {
                "embedding": {
                    "vector": [1.0, 0.0, 0.0],
                    "k": 2
                }
            }
        }))
        .unwrap();

        let hit_only_context = VectorCandidateWindowContext::new(
            VectorCandidateWindowContextKind::Knn,
            NativeQueryContext::with_existing_total_hits(1),
            Some(vec![test_search_hit("vectors".to_string(), "a".to_string(), 1.0, serde_json::json!({
                    "body": "alpha",
                    "embedding": [9.0, 9.0, 9.0]
                }))]),
        );

        let native_query_context = if let Some(documents) = hit_only_context.documents() {
            Some(NativeQueryContext::with_existing_total_hits_and_documents(
                hit_only_context.total_hits(),
                documents,
            ))
        } else if let Some(hits) = hit_only_context.hits() {
            Some(NativeQueryContext::with_existing_total_hits_and_documents(
                hit_only_context.total_hits(),
                index.documents_for_search_hits(&hits),
            ))
        } else if let Some(candidate_ids) = hit_only_context.candidate_ids() {
            Some(NativeQueryContext::with_existing_total_hits_and_documents(
                hit_only_context.total_hits(),
                index.documents_for_candidate_ids(candidate_ids),
            ))
        } else {
            hit_only_context.context.documents.clone().map(|documents| {
                NativeQueryContext::with_existing_total_hits_and_documents(
                    hit_only_context.total_hits(),
                    documents,
                )
            })
        }
        .expect("native query context from hit-only carrier");

        assert_eq!(native_query_context.total_hits, Some(1));
        assert_eq!(
            native_query_context
                .documents
                .unwrap()
                .iter()
                .map(|document| document.metadata.id.as_str())
                .collect::<Vec<_>>(),
            vec!["a"]
        );
    }

