    #[test]
    fn single_index_materialized_final_order_components_produce_optional_reusable_context() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "docs".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "body": { "type": "text" }
                    }
                }),
            })
            .unwrap();

        for (id, body) in [
            ("a", "alpha unrelated"),
            ("b", "target phrase"),
            ("c", "target phrase extra"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "docs".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "body": body
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["docs".to_string()],
            })
            .unwrap();

        let query = parse_query_value(&serde_json::json!({
            "match_phrase": {
                "body": "target phrase"
            }
        }))
        .unwrap();
        let aggregations = parse_search_aggregation_map(&serde_json::json!({})).unwrap();

        let mut store = engine.store.write().unwrap();
        let (_, fetched_hits) = store
            .indices
            .get_mut("docs")
            .unwrap()
            .search_hits_page_for_query_index_aware("docs", &query, &[], 0, 10)
            .unwrap()
            .unwrap();
        let total_hits = fetched_hits.len() as u64;
        let hits = store
            .indices
            .get_mut("docs")
            .unwrap()
            .collect_materialized_single_index_plain_response_hits_with_query_vector_candidate_window_context_and_optional_total_hits_deterministic_stored_field_projection(
                &query,
                &[],
                &fetched_hits,
                Some(total_hits),
                0,
                10,
                None,
            )
            .unwrap();
        let returned_aggregations = serde_json::json!({});
        let reusable = store
            .indices
            .get_mut("docs")
            .unwrap()
            .reusable_query_context_for_query_index_aware_with_optional_all_documents(
                "docs",
                &query,
                Some(&aggregations),
            )
            .unwrap();

        assert_eq!(total_hits, 2);
        assert_eq!(search_hit_ids(&hits), vec!["b", "c"]);
        assert_eq!(returned_aggregations, serde_json::json!({}));
        let reusable: ReusableQueryContext<'_> = reusable.unwrap();
        assert_eq!(reusable.total_hits, Some(2));
        assert_eq!(
            reusable
                .documents
                .unwrap()
                .iter()
                .map(|document| document.metadata.id.as_str())
                .collect::<Vec<_>>(),
            vec!["b", "c"]
        );
    }

    #[test]
    fn multi_index_vector_native_page_aggregation_reduce_produces_optional_reusable_context() {
        let engine = TantivyEngine::default();
        for index_name in ["vectors_a", "vectors_b"] {
            engine
                .create_index(CreateIndexRequest {
                    index: index_name.to_string(),
                    settings: serde_json::json!({}),
                    mappings: serde_json::json!({
                        "properties": {
                            "body": { "type": "text" },
                            "embedding": {
                                "type": "knn_vector",
                                "dimension": 3,
                                "space_type": "l2"
                            }
                        }
                    }),
                })
                .unwrap();
        }

        for (index, id, body, embedding) in [
            ("vectors_a", "a", "alpha", serde_json::json!([9.0, 9.0, 9.0])),
            ("vectors_a", "b", "target", serde_json::json!([1.0, 0.0, 0.0])),
            ("vectors_b", "c", "target", serde_json::json!([1.0, 0.0, 0.0])),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: index.to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "body": body,
                        "embedding": embedding
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["vectors_a".to_string(), "vectors_b".to_string()],
            })
            .unwrap();

        let query = parse_query_value(&serde_json::json!({
            "knn": {
                "embedding": {
                    "vector": [1.0, 0.0, 0.0],
                    "k": 10
                }
            }
        }))
        .unwrap();
        let aggregations = parse_search_aggregation_map(&serde_json::json!({
            "by_body": {
                "terms": { "field": "body", "size": 10 }
            }
        }))
        .unwrap();

        let mut store = engine.store.write().unwrap();
        let (response, reusable) = store
            .search_response_index_aware_with_optional_reusable(
                &["vectors_a".to_string(), "vectors_b".to_string()],
                None,
                &query,
                &[],
                &aggregations,
                0,
                10,
                Vec::new(),
                None,
            )
            .unwrap();

        assert_eq!(search_hit_ids(&response.hits), vec!["b", "c", "a"]);
        assert_eq!(
            response.aggregations.get("by_body"),
            Some(&serde_json::json!({
                "buckets": [
                    { "key": "target", "doc_count": 2 },
                    { "key": "alpha", "doc_count": 1 }
                ]
            }))
        );
        let reusable = reusable.unwrap();
        assert_eq!(reusable.total_hits, Some(3));
        assert_eq!(
            reusable
                .documents
                .unwrap()
                .iter()
                .map(|document| document.metadata.id.as_str())
                .collect::<Vec<_>>(),
            vec!["b", "c", "a"]
        );
    }

