    fn multi_index_vector_native_size_zero_aggregation_fetch_produces_optional_reusable_context() {
        let engine = TantivyEngine::default();
        for index_name in ["vectors_a", "vectors_b"] {
            engine
                .create_index(CreateIndexRequest {
                    index: index_name.to_string(),
                    settings: serde_json::json!({}),
                    mappings: serde_json::json!({
                        "properties": {
                            "body": { "type": "text" },
                            "embedding": {
                                "type": "knn_vector",
                                "dimension": 3,
                                "space_type": "l2"
                            }
                        }
                    }),
                })
                .unwrap();
        }

        for (index, id, body, embedding) in [
            ("vectors_a", "a", "alpha", serde_json::json!([9.0, 9.0, 9.0])),
            ("vectors_a", "b", "target", serde_json::json!([1.0, 0.0, 0.0])),
            ("vectors_b", "c", "target", serde_json::json!([1.0, 0.0, 0.0])),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: index.to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "body": body,
                        "embedding": embedding
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["vectors_a".to_string(), "vectors_b".to_string()],
            })
            .unwrap();

        let query = parse_query_value(&serde_json::json!({
            "knn": {
                "embedding": {
                    "vector": [1.0, 0.0, 0.0],
                    "k": 10
                }
            }
        }))
        .unwrap();
        let aggregations = parse_search_aggregation_map(&serde_json::json!({
            "by_body": {
                "terms": { "field": "body", "size": 10 }
            }
        }))
        .unwrap();

        let mut store = engine.store.write().unwrap();
        let (response, reusable) = store
            .search_response_index_aware_with_optional_reusable(
                &["vectors_a".to_string(), "vectors_b".to_string()],
                None,
                &query,
                &[],
                &aggregations,
                0,
                0,
                Vec::new(),
                None,
            )
            .unwrap();

        assert_eq!(response.total_hits, 3);
        assert_eq!(
            response.aggregations.get("by_body"),
            Some(&serde_json::json!({
                "buckets": [
                    { "key": "target", "doc_count": 2 },
                    { "key": "alpha", "doc_count": 1 }
                ]
            }))
        );
        let reusable = reusable.unwrap();
        assert_eq!(reusable.total_hits, Some(3));
        assert_eq!(
            reusable
                .documents
                .unwrap()
                .iter()
                .map(|document| document.metadata.id.as_str())
                .collect::<Vec<_>>(),
            vec!["b", "c", "a"]
        );
    }

    #[test]
    fn grouped_hybrid_bool_index_aware_aggregation_wrapper_falls_through_to_native_document_backed_collection(
    ) {
        let mut index = StoredIndex::new("vectors");
        index
            .ensure_dynamic_mappings(&serde_json::json!({
                "embedding": [1.0, 0.0, 0.0],
                "body": "apple banana",
                "service": "api"
            }))
            .unwrap();

        for (id, body, service, embedding) in [
            ("a", "apple alpha vector", "api", Some(serde_json::json!([1.0, 0.0, 0.0]))),
            ("b", "apple beta vector", "api", Some(serde_json::json!([0.9, 0.1, 0.0]))),
            ("c", "apricot lexical only", "worker", None),
            ("d", "banana unrelated", "worker", None),
        ] {
            let mut source = serde_json::json!({ "body": body, "service": service });
            if let Some(embedding) = embedding {
                source["embedding"] = embedding;
            }
            index.apply_primary_document(id.to_string(), source);
        }
        index.refreshed_seq_no = index.next_seq_no.saturating_sub(1);
        index.rebuild_tantivy_search_state().unwrap();

        let query = parse_query_value(&serde_json::json!({
            "bool": {
                "should": [
                    { "wildcard": { "body": "apri*" } },
                    {
                        "knn": {
                            "embedding": {
                                "vector": [1.0, 0.0, 0.0],
                                "k": 4
                            }
                        }
                    }
                ],
                "minimum_should_match": 1
            }
        }))
        .unwrap();
        let aggregation_map = parse_search_aggregation_map(&serde_json::json!({
            "by_service": { "terms": { "field": "service", "size": 10 } }
        }))
        .unwrap();

        let (aggregations, reusable) = index
            .collect_aggregations_for_query_index_aware_with_context(
                "vectors",
                &query,
                &aggregation_map,
                ReusableQueryContext::default(),
            )
            .unwrap()
            .unwrap();

        assert_eq!(
            aggregations,
            serde_json::json!({
                "by_service": {
                    "buckets": [
                        { "key": "api", "doc_count": 2 },
                        { "key": "worker", "doc_count": 1 }
                    ]
                }
            })
        );
        assert_eq!(reusable.total_hits, None);
    }

