    #[test]
    fn grouped_hybrid_bool_text_range_leaf_reduces_candidate_ids_directly() {
        let mut index = StoredIndex::new("vectors");
        index
            .ensure_dynamic_mappings(&serde_json::json!({
                "embedding_a": [1.0, 0.0, 0.0],
                "embedding_b": [0.0, 1.0, 0.0],
                "body": "apple banana"
            }))
            .unwrap();

        for (id, body, embedding_a, embedding_b) in [
            (
                "a",
                "apple alpha",
                Some(serde_json::json!([1.0, 0.0, 0.0])),
                Some(serde_json::json!([9.0, 9.0, 9.0])),
            ),
            (
                "b",
                "banana beta",
                Some(serde_json::json!([9.0, 9.0, 9.0])),
                Some(serde_json::json!([0.0, 1.0, 0.0])),
            ),
            (
                "c",
                "apple banana",
                Some(serde_json::json!([1.0, 0.0, 0.0])),
                Some(serde_json::json!([0.0, 1.0, 0.0])),
            ),
            (
                "d",
                "orange gamma",
                Some(serde_json::json!([0.0, 1.0, 0.0])),
                Some(serde_json::json!([1.0, 0.0, 0.0])),
            ),
            (
                "e",
                "banana apple",
                Some(serde_json::json!([1.0, 0.0, 0.0])),
                Some(serde_json::json!([0.0, 1.0, 0.0])),
            ),
        ] {
            let mut source = serde_json::json!({ "body": body });
            if let Some(embedding_a) = embedding_a {
                source["embedding_a"] = embedding_a;
            }
            if let Some(embedding_b) = embedding_b {
                source["embedding_b"] = embedding_b;
            }
            index.apply_primary_document(id.to_string(), source);
        }
        index.refreshed_seq_no = index.next_seq_no.saturating_sub(1);
        index.rebuild_tantivy_search_state().unwrap();

        let query = parse_query_value(&serde_json::json!({
            "bool": {
                "must": [
                    {
                        "bool": {
                            "should": [
                                {
                                    "range": {
                                        "body": {
                                            "gte": "apple"
                                        }
                                    }
                                },
                                {
                                    "knn": {
                                        "embedding_a": {
                                            "vector": [1.0, 0.0, 0.0],
                                            "k": 2
                                        }
                                    }
                                }
                            ],
                            "minimum_should_match": 1
                        }
                    },
                    {
                        "bool": {
                            "should": [
                                { "match": { "body": "banana" } },
                                {
                                    "knn": {
                                        "embedding_b": {
                                            "vector": [0.0, 1.0, 0.0],
                                            "k": 2
                                        }
                                    }
                                }
                            ],
                            "minimum_should_match": 1
                        }
                    }
                ]
            }
        }))
        .unwrap();

        let candidate_ids = index
            .search_candidate_ids_for_query_reduced("vectors", &query)
            .unwrap()
            .unwrap();
        assert_eq!(
            candidate_ids.into_iter().collect::<Vec<_>>(),
            vec!["c".to_string(), "e".to_string()]
        );
    }

