    #[test]
    fn hybrid_query_supports_nested_minimum_should_match_above_one_size_zero_top_hits_aggregation(
    ) {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "vectors".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "embedding": {
                            "type": "knn_vector",
                            "dimension": 3,
                            "space_type": "l2"
                        },
                        "body": { "type": "text" }
                    }
                }),
            })
            .unwrap();

        for (id, body, embedding) in [
            ("a", "apple alpha", Some(serde_json::json!([1.0, 0.0, 0.0]))),
            ("b", "apple beta", Some(serde_json::json!([0.0, 1.0, 0.0]))),
            ("c", "apple lexical only", None),
            ("d", "orange gamma", Some(serde_json::json!([1.0, 0.0, 0.0]))),
        ] {
            let mut source = serde_json::json!({ "body": body });
            if let Some(embedding) = embedding {
                source["embedding"] = embedding;
            }
            engine
                .index_document(IndexDocumentRequest {
                    index: "vectors".to_string(),
                    id: id.to_string(),
                    source,
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["vectors".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["vectors".to_string()],
                query: serde_json::json!({
                    "bool": {
                        "must": [
                            {
                                "bool": {
                                    "should": [
                                        { "match": { "body": "apple" } },
                                        {
                                            "knn": {
                                                "embedding": {
                                                    "vector": [1.0, 0.0, 0.0],
                                                    "k": 3
                                                }
                                            }
                                        },
                                        {
                                            "knn": {
                                                "embedding": {
                                                    "vector": [0.0, 1.0, 0.0],
                                                    "k": 3
                                                }
                                            }
                                        }
                                    ],
                                    "minimum_should_match": 2
                                }
                            }
                        ]
                    }
                }),
                aggregations: serde_json::json!({
                    "sample": {
                        "top_hits": {
                            "size": 1
                        }
                    }
                }),
                sort: Vec::new(),
                from: 0,
                size: 0,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 3);
        assert_eq!(response.hits.len(), 0);
        assert_eq!(
            response.aggregations["sample"]["hits"]["total"]["value"],
            3
        );
        assert_eq!(
            response.aggregations["sample"]["hits"]["hits"][0]["_id"],
            Value::String("a".to_string())
        );
        assert!(response.phase_results.iter().any(|phase| phase.phase == SearchPhase::Query));
    }

