    #[test]
    fn hybrid_query_supports_ids_lexical_leaf_candidates() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "vectors".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "embedding": {
                            "type": "knn_vector",
                            "dimension": 3,
                            "space_type": "l2"
                        },
                        "body": { "type": "text" }
                    }
                }),
            })
            .unwrap();

        for (id, body, embedding) in [
            ("a", "alpha vector", Some(serde_json::json!([1.0, 0.0, 0.0]))),
            ("b", "beta vector", Some(serde_json::json!([0.9, 0.1, 0.0]))),
            ("c", "ids lexical only", None),
        ] {
            let mut source = serde_json::json!({ "body": body });
            if let Some(embedding) = embedding {
                source["embedding"] = embedding;
            }
            engine
                .index_document(IndexDocumentRequest {
                    index: "vectors".to_string(),
                    id: id.to_string(),
                    source,
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["vectors".to_string()],
            })
            .unwrap();

        let hybrid = engine
            .search(SearchRequest {
                indices: vec!["vectors".to_string()],
                query: serde_json::json!({
                    "bool": {
                        "should": [
                            { "ids": { "values": ["c"] } },
                            {
                                "knn": {
                                    "embedding": {
                                        "vector": [1.0, 0.0, 0.0],
                                        "k": 2
                                    }
                                }
                            }
                        ],
                        "minimum_should_match": 1
                    }
                }),
                aggregations: serde_json::json!({}),
                sort: Vec::new(),
                from: 0,
                size: 10,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(search_hit_ids(&hybrid.hits), vec!["a", "c", "b"]);
        assert!(hybrid.phase_results.iter().any(|phase| phase.phase == SearchPhase::Query));
    }

