    #[test]
    fn engine_searches_with_source_derived_query_clauses() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "logs-000001".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "message": { "type": "text" },
                        "service": { "type": "keyword" },
                        "tags": { "type": "keyword" }
                    }
                }),
            })
            .unwrap();

        for (id, source) in [
            (
                "1",
                serde_json::json!({
                    "message": "Error from API",
                    "service": "api",
                    "tags": ["prod", "blue"]
                }),
            ),
            (
                "2",
                serde_json::json!({
                    "message": "worker completed",
                    "service": "worker",
                    "tags": ["batch"]
                }),
            ),
            ("3", serde_json::json!({ "message": "missing service" })),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "logs-000001".to_string(),
                    id: id.to_string(),
                    source,
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["logs-000001".to_string()],
            })
            .unwrap();

        let ids = |query| {
            engine
                .search(SearchRequest {
                    indices: vec!["logs-000001".to_string()],
                    query,
                    aggregations: serde_json::json!({}),
                    sort: Vec::new(),
                    from: 0,
                    size: 10,
                    stored_fields: None,
                    source_fields: None,
                    source_filter: None,
                    source_includes: None,
                    source_include: None,
                    source_excludes: None,
                    source_exclude: None,
                    highlight: None,
                    explain: false,
                })
                .unwrap()
                .hits
                .into_iter()
                .map(|hit| hit.metadata.id)
                .collect::<Vec<_>>()
        };

        assert_eq!(
            ids(serde_json::json!({ "match_none": {} })),
            Vec::<String>::new()
        );
        assert_eq!(
            ids(serde_json::json!({ "ids": { "values": ["2"] } })),
            vec!["2"]
        );
        assert_eq!(
            ids(serde_json::json!({ "exists": { "field": "service" } })),
            vec!["1", "2"]
        );
        assert_eq!(
            ids(serde_json::json!({ "terms": { "tags": ["prod", "green"] } })),
            vec!["1"]
        );
        assert_eq!(
            ids(serde_json::json!({ "prefix": { "service": "wo" } })),
            vec!["2"]
        );
        assert_eq!(
            ids(serde_json::json!({
                "wildcard": {
                    "message": {
                        "value": "err*api",
                        "case_insensitive": true
                    }
                }
            })),
            vec!["1"]
        );
    }

