    #[test]
    fn single_index_native_page_fetch_materializes_only_requested_page() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "logs-000001".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "bytes": { "type": "long" }
                    }
                }),
            })
            .unwrap();

        for (id, bytes) in [("1", 10), ("2", 20), ("3", 30), ("4", 40)] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "logs-000001".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "bytes": bytes
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["logs-000001".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["logs-000001".to_string()],
                query: serde_json::json!({ "match_all": {} }),
                aggregations: serde_json::json!({}),
                sort: vec![SortSpec {
                    field: "bytes".to_string(),
                    order: SortOrder::Desc,
                    unmapped_type: None,
                    geo_origin: None,
                    mode: None,
                    script: None,
}],
                from: 1,
                size: 2,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 4);
        assert_eq!(
            response
                .hits
                .iter()
                .map(|hit| hit.metadata.id.as_str())
                .collect::<Vec<_>>(),
            vec!["3", "2"]
        );
        assert!(response
            .phase_results
            .iter()
            .any(|phase| phase.phase == SearchPhase::Query));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.description == "materialized only the requested native page"
        }));
    }

    #[test]
    fn single_index_native_unsorted_page_fetch_materializes_only_requested_page() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "logs-000001".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "message": { "type": "text" },
                        "status": { "type": "keyword" }
                    }
                }),
            })
            .unwrap();

        for (id, message, status) in [
            ("1", "apple banana", "ok"),
            ("2", "apple banana cherry", "ok"),
            ("3", "apple", "warn"),
            ("4", "apple banana banana banana", "ok"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "logs-000001".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "message": message,
                        "status": status
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["logs-000001".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["logs-000001".to_string()],
                query: serde_json::json!({
                    "match": { "message": "banana" }
                }),
                aggregations: serde_json::json!({}),
                sort: Vec::new(),
                from: 1,
                size: 2,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 3);
        assert_eq!(response.hits.len(), 2);
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description == "matched refreshed documents with native paginated fetch"
        }));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.description == "materialized only the requested native page"
        }));
        assert!(response
            .hits
            .iter()
            .all(|hit| hit.source["message"] != serde_json::json!("apple")));
    }

