    #[test]
    fn single_index_text_case_insensitive_wildcard_size_zero_compatibility_path_skips_hit_materialization(
    ) {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "logs-000001".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "body": { "type": "text" }
                    }
                }),
            })
            .unwrap();

        for (id, body) in [
            ("1", "Apricot Alpha"),
            ("2", "apricot beta"),
            ("3", "banana"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "logs-000001".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({ "body": body }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["logs-000001".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["logs-000001".to_string()],
                query: serde_json::json!({
                    "wildcard": {
                        "body": {
                            "value": "APRI*",
                            "case_insensitive": true
                        }
                    }
                }),
                aggregations: serde_json::json!({}),
                sort: Vec::new(),
                from: 0,
                size: 0,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 2);
        assert!(response.hits.is_empty());
        assert_eq!(response.aggregations, serde_json::json!({}));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description == "matched refreshed documents without hit fetch"
        }));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.description
                    == "size=0 compatibility path avoided top-level hit materialization"
        }));
    }

    #[test]
    fn case_insensitive_wildcard_text_field_uses_source_candidate_native_page() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "logs-000001".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "body": { "type": "text" }
                    }
                }),
            })
            .unwrap();

        for (id, body) in [
            ("1", "Apricot Alpha"),
            ("2", "apricot beta"),
            ("3", "banana"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "logs-000001".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({ "body": body }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["logs-000001".to_string()],
            })
            .unwrap();

        let search_request = |size| SearchRequest {
            indices: vec!["logs-000001".to_string()],
            query: serde_json::json!({
                "wildcard": {
                    "body": {
                        "value": "APRI*",
                        "case_insensitive": true
                    }
                }
            }),
            aggregations: serde_json::json!({}),
            sort: Vec::new(),
            from: 0,
            size,
            stored_fields: None,
            source_fields: None,
            source_filter: None,
            source_includes: None,
            source_include: None,
            source_excludes: None,
            source_exclude: None,
            highlight: None,
            explain: false,
        };

        let page_response = engine.search(search_request(10)).unwrap();
        assert_eq!(search_hit_ids(&page_response.hits), vec!["1", "2"]);
        assert!(page_response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.description == "materialized only the requested native page"
        }));
        let telemetry = engine.search_cache_telemetry_snapshot().unwrap();
        assert_eq!(telemetry.materialized_response_fetches, 0);
        assert_eq!(telemetry.compatibility_materialized_response_fetches, 0);
        assert_eq!(telemetry.materialized_response_avoided_fetches, 0);

        let size_zero_response = engine.search(search_request(0)).unwrap();
        assert_eq!(size_zero_response.total_hits, 2);
        assert!(size_zero_response.hits.is_empty());
        let telemetry = engine.search_cache_telemetry_snapshot().unwrap();
        assert_eq!(telemetry.materialized_response_fetches, 0);
        assert_eq!(telemetry.compatibility_materialized_response_fetches, 0);
        assert_eq!(telemetry.materialized_response_avoided_fetches, 0);
    }

