    #[test]
    fn single_index_text_case_insensitive_wildcard_size_zero_compatibility_aggregation_path_skips_hit_materialization(
    ) {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "logs-000001".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "body": { "type": "text" },
                        "service": { "type": "keyword" }
                    }
                }),
            })
            .unwrap();

        for (id, body, service) in [
            ("1", "Apricot Alpha", "api"),
            ("2", "apricot beta", "worker"),
            ("3", "banana", "api"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "logs-000001".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({ "body": body, "service": service }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["logs-000001".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["logs-000001".to_string()],
                query: serde_json::json!({
                    "wildcard": {
                        "body": {
                            "value": "APRI*",
                            "case_insensitive": true
                        }
                    }
                }),
                aggregations: serde_json::json!({
                    "by_service": {
                        "terms": { "field": "service", "size": 10 }
                    },
                    "service_bucket_script_plugin": {
                        "plugin": {
                            "name": "demo",
                            "kind": "bucket_script",
                            "params": {
                                "aggregation": "by_service",
                                "path": "_count",
                                "script": "_value * params.scale",
                                "params": {
                                    "scale": 2.0
                                }
                            }
                        }
                    },
                    "service_bucket_sort_plugin": {
                        "plugin": {
                            "name": "demo",
                            "kind": "bucket_sort",
                            "params": {
                                "aggregation": "by_service",
                                "sort": [
                                    { "_count": "asc" },
                                    { "_key": "asc" }
                                ],
                                "from": 0,
                                "size": 1
                            }
                        }
                    },
                    "service_bucket_selector_plugin": {
                        "plugin": {
                            "name": "demo",
                            "kind": "bucket_selector",
                            "params": {
                                "aggregation": "by_service",
                                "path": "_count",
                                "op": "gt",
                                "value": 0.5
                            }
                        }
                    },
                    "service_serial_diff_plugin": {
                        "plugin": {
                            "name": "demo",
                            "kind": "serial_diff",
                            "params": {
                                "buckets_path": "by_service>_count",
                                "lag": 1
                            }
                        }
                    },
                    "service_derivative_plugin": {
                        "plugin": {
                            "name": "demo",
                            "kind": "derivative",
                            "params": {
                                "buckets_path": "by_service>_count"
                            }
                        }
                    }
                }),
                sort: Vec::new(),
                from: 0,
                size: 0,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 2);
        assert!(response.hits.is_empty());
        assert_eq!(
            response.aggregations.get("by_service"),
            Some(&serde_json::json!({
                "buckets": [
                    { "key": "api", "doc_count": 1 },
                    { "key": "worker", "doc_count": 1 }
                ]
            }))
        );
        assert_eq!(
            response.aggregations.get("service_bucket_script_plugin"),
            Some(&serde_json::json!({
                "buckets": [
                    { "key": "api", "value": 2.0 },
                    { "key": "worker", "value": 2.0 }
                ],
                "_plugin": "demo",
                "_type": "bucket_script",
                "params": {
                    "aggregation": "by_service",
                    "path": "_count",
                    "script": "_value * params.scale",
                    "params": {
                        "scale": 2.0
                    }
                }
            }))
        );
        assert_eq!(
            response.aggregations.get("service_bucket_sort_plugin"),
            Some(&serde_json::json!({
                "buckets": [
                    { "key": "api", "doc_count": 1 }
                ],
                "_plugin": "demo",
                "_type": "bucket_sort",
                "params": {
                    "aggregation": "by_service",
                    "sort": [
                        { "_count": "asc" },
                        { "_key": "asc" }
                    ],
                    "from": 0,
                    "size": 1
                }
            }))
        );
        assert_eq!(
            response.aggregations.get("service_bucket_selector_plugin"),
            Some(&serde_json::json!({
                "buckets": [
                    { "key": "api", "doc_count": 1 },
                    { "key": "worker", "doc_count": 1 }
                ],
                "_plugin": "demo",
                "_type": "bucket_selector",
                "params": {
                    "aggregation": "by_service",
                    "path": "_count",
                    "op": "gt",
                    "value": 0.5
                }
            }))
        );
        assert_eq!(
            response.aggregations.get("service_serial_diff_plugin"),
            Some(&serde_json::json!({
                "value": 0.0,
                "_plugin": "demo",
                "_type": "serial_diff",
                "params": {
                    "buckets_path": "by_service>_count",
                    "lag": 1
                }
            }))
        );
        assert_eq!(
            response.aggregations.get("service_derivative_plugin"),
            Some(&serde_json::json!({
                "value": 0.0,
                "_plugin": "demo",
                "_type": "derivative",
                "params": {
                    "buckets_path": "by_service>_count"
                }
            }))
        );
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description == "matched refreshed documents without hit fetch"
        }));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.description
                    == "size=0 compatibility aggregation path avoided top-level hit materialization"
        }));
    }

