    #[test]
    fn single_index_native_page_and_aggregation_fetch_returns_hits_and_terms() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "logs-000001".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "message": { "type": "text" },
                        "service": { "type": "keyword" }
                    }
                }),
            })
            .unwrap();

        for (id, message, service) in [
            ("1", "banana", "api"),
            ("2", "banana", "worker"),
            ("3", "banana", "api"),
            ("4", "apple", "other"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "logs-000001".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "message": message,
                        "service": service
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["logs-000001".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["logs-000001".to_string()],
                query: serde_json::json!({
                    "match": { "message": "banana" }
                }),
                aggregations: serde_json::json!({
                    "by_service": { "terms": { "field": "service", "size": 10 } },
                    "recent_hits": { "top_hits": { "from": 1, "size": 2 } }
                }),
                sort: Vec::new(),
                from: 1,
                size: 1,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 3);
        assert_eq!(response.hits.len(), 1);
        assert_eq!(response.hits[0].source["message"], serde_json::json!("banana"));
        assert_eq!(
            response.aggregations,
            serde_json::json!({
                "by_service": {
                    "buckets": [
                        { "key": "api", "doc_count": 2 },
                        { "key": "worker", "doc_count": 1 }
                    ]
                },
                "recent_hits": {
                    "hits": {
                        "total": {
                            "value": 3,
                            "relation": "eq"
                        },
                        "max_score": 1.0,
                        "hits": [
                            {
                                "_index": "logs-000001",
                                "_id": "2",
                                "_score": 1.0,
                                "_source": {
                                    "message": "banana",
                                    "service": "worker"
                                },
                                "_version": 1,
                                "_seq_no": 1,
                                "_primary_term": 1
                            },
                            {
                                "_index": "logs-000001",
                                "_id": "3",
                                "_score": 1.0,
                                "_source": {
                                    "message": "banana",
                                    "service": "api"
                                },
                                "_version": 1,
                                "_seq_no": 2,
                                "_primary_term": 1
                            }
                        ]
                    }
                }
            })
        );
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description == "matched refreshed documents with native page+aggregation fetch"
        }));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.description
                    == "materialized only the requested native page with native aggregation collection"
        }));
    }

