    #[test]
    fn aggregation_map_requires_all_hits_only_for_significant_terms_family() {
        let plain = parse_search_aggregation_map(&serde_json::json!({
            "by_service": { "terms": { "field": "service", "size": 10 } },
            "service_total": { "sum_bucket": { "buckets_path": "by_service>_count" } }
        }))
        .unwrap();
        let regular_sig = parse_search_aggregation_map(&serde_json::json!({
            "sig_service": { "significant_terms": { "field": "service", "size": 10 } }
        }))
        .unwrap();
        let plugin_sig = parse_search_aggregation_map(&serde_json::json!({
            "sig_service_plugin": {
                "plugin": {
                    "name": "demo",
                    "kind": "significant_terms",
                    "params": { "field": "service", "size": 10 }
                }
            }
        }))
        .unwrap();

        assert!(!aggregation_map_requires_all_hits(&plain));
        assert!(aggregation_map_requires_all_hits(&regular_sig));
        assert!(aggregation_map_requires_all_hits(&plugin_sig));
    }

    #[test]
    fn aggregation_map_top_hits_window_uses_largest_requested_window() {
        let aggregations = parse_search_aggregation_map(&serde_json::json!({
            "recent_hits": {
                "top_hits": {
                    "from": 1,
                    "size": 2
                }
            },
            "recent_hits_plugin": {
                "plugin": {
                    "name": "demo",
                    "kind": "top_hits",
                    "params": {
                        "from": 2,
                        "size": 3
                    }
                }
            }
        }))
        .unwrap();

        assert_eq!(aggregation_map_top_hits_window(&aggregations), Some(5));
        assert!(aggregation_map_top_hits_window(&aggregations).is_some());

        let sorted_plugin_aggregations = parse_search_aggregation_map(&serde_json::json!({
            "sorted_hits_plugin": {
                "plugin": {
                    "name": "demo",
                    "kind": "top_hits",
                    "params": {
                        "from": 0,
                        "size": 1,
                        "sort": [
                            { "_id": { "order": "desc" } }
                        ]
                    }
                }
            }
        }))
        .unwrap();

        assert_eq!(aggregation_map_top_hits_window(&sorted_plugin_aggregations), None);
    }

    #[test]
    fn aggregation_map_requires_hit_materialization_only_for_top_hits_family() {
        let document_only = parse_search_aggregation_map(&serde_json::json!({
            "by_service": { "terms": { "field": "service", "size": 10 } },
            "latency_avg": { "avg": { "field": "latency" } },
            "filtered": {
                "filter": {
                    "match": { "service": "api" }
                }
            },
            "service_plugin_terms": {
                "plugin": {
                    "name": "demo",
                    "kind": "terms",
                    "params": {
                        "field": "service",
                        "size": 10
                    }
                }
            },
            "plugin_filters": {
                "plugin": {
                    "name": "demo",
                    "kind": "filters",
                    "params": {
                        "filters": {
                            "api": { "match": { "service": "api" } }
                        }
                    }
                }
            }
        }))
        .unwrap();
        assert!(!aggregation_map_requires_hit_materialization(&document_only));

        let hit_required = parse_search_aggregation_map(&serde_json::json!({
            "sample_hits": {
                "top_hits": { "from": 0, "size": 2 }
            }
        }))
        .unwrap();
        assert!(aggregation_map_requires_hit_materialization(&hit_required));
    }

