    #[test]
    fn native_tantivy_geo_bounds_aggregation_preserves_shape() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "bench".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "location": { "type": "geo_point" },
                        "status": { "type": "keyword" }
                    }
                }),
            })
            .unwrap();

        for (id, lat, lon, status) in [
            ("1", 37.0, -122.0, "ok"),
            ("2", 38.5, -121.5, "ok"),
            ("3", 36.5, -123.5, "warn"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "bench".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "location": { "lat": lat, "lon": lon },
                        "status": status
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["bench".to_string()],
            })
            .unwrap();

        let query = parse_query(&serde_json::json!({
            "term": { "status": "ok" }
        }))
        .unwrap();
        let aggregations = parse_search_aggregation_map(&serde_json::json!({
            "geo": { "geo_bounds": { "field": "location" } }
        }))
        .unwrap();

        let mut store = engine.store.write().unwrap();
        let index = store.indices.get_mut("bench").unwrap();
        let native = index
            .collect_aggregations_native(&query, &aggregations)
            .unwrap()
            .expect("native geo_bounds aggregation");
        assert_eq!(
            native,
            serde_json::json!({
                "geo": {
                    "bounds": {
                        "top_left": { "lat": 38.5, "lon": -122.0 },
                        "bottom_right": { "lat": 37.0, "lon": -121.5 }
                    }
                }
            })
        );
    }

