    #[test]
    fn native_tantivy_date_histogram_supports_minute_hour_week_and_month_intervals() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "bench".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "event_time": { "type": "date", "fast": true }
                    }
                }),
            })
            .unwrap();

        for (id, event_time) in [
            ("1", "2024-01-01T08:15:00Z"),
            ("2", "2024-01-01T08:45:00Z"),
            ("3", "2024-01-01T09:05:00Z"),
            ("4", "2024-02-03T01:00:00Z"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "bench".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "event_time": event_time
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["bench".to_string()],
            })
            .unwrap();

        let query = parse_query(&serde_json::json!({
            "match_all": {}
        }))
        .unwrap();

        let hourly = parse_search_aggregation_map(&serde_json::json!({
            "recent_events": {
                "date_histogram": {
                    "field": "event_time",
                    "fixed_interval": "1h"
                }
            }
        }))
        .unwrap();
        let minutely = parse_search_aggregation_map(&serde_json::json!({
            "recent_events": {
                "date_histogram": {
                    "field": "event_time",
                    "fixed_interval": "1m"
                }
            }
        }))
        .unwrap();
        let weekly = parse_search_aggregation_map(&serde_json::json!({
            "recent_events": {
                "date_histogram": {
                    "field": "event_time",
                    "calendar_interval": "week"
                }
            }
        }))
        .unwrap();
        let monthly = parse_search_aggregation_map(&serde_json::json!({
            "recent_events": {
                "date_histogram": {
                    "field": "event_time",
                    "calendar_interval": "month"
                }
            }
        }))
        .unwrap();

        let mut store = engine.store.write().unwrap();
        let index = store.indices.get_mut("bench").unwrap();
        let minutely_native = index
            .collect_aggregations_native(&query, &minutely)
            .unwrap()
            .expect("native minute date_histogram aggregation");
        let hourly_native = index
            .collect_aggregations_native(&query, &hourly)
            .unwrap()
            .expect("native hourly date_histogram aggregation");
        let weekly_native = index
            .collect_aggregations_native(&query, &weekly)
            .unwrap()
            .expect("native weekly date_histogram aggregation");
        let monthly_native = index
            .collect_aggregations_native(&query, &monthly)
            .unwrap()
            .expect("native monthly date_histogram aggregation");

        assert_eq!(
            minutely_native,
            serde_json::json!({
                "recent_events": {
                    "buckets": [
                        {
                            "key": 1704096900000i64,
                            "key_as_string": "2024-01-01T08:15:00.000Z",
                            "doc_count": 1
                        },
                        {
                            "key": 1704098700000i64,
                            "key_as_string": "2024-01-01T08:45:00.000Z",
                            "doc_count": 1
                        },
                        {
                            "key": 1704099900000i64,
                            "key_as_string": "2024-01-01T09:05:00.000Z",
                            "doc_count": 1
                        },
                        {
                            "key": 1706922000000i64,
                            "key_as_string": "2024-02-03T01:00:00.000Z",
                            "doc_count": 1
                        }
                    ]
                }
            })
        );
        assert_eq!(
            hourly_native,
            serde_json::json!({
                "recent_events": {
                    "buckets": [
                        {
                            "key": 1704096000000i64,
                            "key_as_string": "2024-01-01T08:00:00.000Z",
                            "doc_count": 2
                        },
                        {
                            "key": 1704099600000i64,
                            "key_as_string": "2024-01-01T09:00:00.000Z",
                            "doc_count": 1
                        },
                        {
                            "key": 1706922000000i64,
                            "key_as_string": "2024-02-03T01:00:00.000Z",
                            "doc_count": 1
                        }
                    ]
                }
            })
        );
        assert_eq!(
            weekly_native,
            serde_json::json!({
                "recent_events": {
                    "buckets": [
                        {
                            "key": 1704067200000i64,
                            "key_as_string": "2024-01-01T00:00:00.000Z",
                            "doc_count": 3
                        },
                        {
                            "key": 1706486400000i64,
                            "key_as_string": "2024-01-29T00:00:00.000Z",
                            "doc_count": 1
                        }
                    ]
                }
            })
        );
        assert_eq!(
            monthly_native,
            serde_json::json!({
                "recent_events": {
                    "buckets": [
                        {
                            "key": 1704067200000i64,
                            "key_as_string": "2024-01-01T00:00:00.000Z",
                            "doc_count": 3
                        },
                        {
                            "key": 1706745600000i64,
                            "key_as_string": "2024-02-01T00:00:00.000Z",
                            "doc_count": 1
                        }
                    ]
                }
            })
        );
    }

