    #[test]
    fn multi_index_native_tantivy_plugin_date_histogram_reduce_preserves_shape() {
        let engine = TantivyEngine::default();
        for index_name in ["bench_a", "bench_b"] {
            engine
                .create_index(CreateIndexRequest {
                    index: index_name.to_string(),
                    settings: serde_json::json!({}),
                    mappings: serde_json::json!({
                        "properties": {
                            "event_time": { "type": "date", "fast": true }
                        }
                    }),
                })
                .unwrap();
        }

        for (index, id, event_time) in [
            ("bench_a", "1", "2024-01-01T08:00:00Z"),
            ("bench_a", "2", "2024-01-02T09:00:00Z"),
            ("bench_b", "3", "2024-01-02T11:00:00Z"),
            ("bench_b", "4", "2024-01-03T12:00:00Z"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: index.to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "event_time": event_time
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["bench_a".to_string(), "bench_b".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["bench_a".to_string(), "bench_b".to_string()],
                query: serde_json::json!({
                    "match_all": {}
                }),
                aggregations: serde_json::json!({
                    "event_hist_day_plugin": {
                        "plugin": {
                            "name": "demo",
                            "kind": "date_histogram",
                            "params": {
                                "field": "event_time",
                                "calendar_interval": "day"
                            }
                        }
                    }
                }),
                sort: Vec::new(),
                from: 0,
                size: 0,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 4);
        assert!(response.hits.is_empty());
        assert_eq!(
            response.aggregations,
            serde_json::json!({
                "event_hist_day_plugin": {
                    "buckets": [
                        {
                            "key": 1704067200000i64,
                            "key_as_string": "2024-01-01T00:00:00.000Z",
                            "doc_count": 1
                        },
                        {
                            "key": 1704153600000i64,
                            "key_as_string": "2024-01-02T00:00:00.000Z",
                            "doc_count": 2
                        },
                        {
                            "key": 1704240000000i64,
                            "key_as_string": "2024-01-03T00:00:00.000Z",
                            "doc_count": 1
                        }
                    ],
                    "_plugin": "demo",
                    "_type": "date_histogram",
                    "params": {
                        "field": "event_time",
                        "calendar_interval": "day"
                    }
                }
            })
        );
    }

    #[test]
    fn search_size_zero_multi_index_plugin_date_histogram_reduce_feeds_bucket_script_surface() {
        let engine = TantivyEngine::default();
        for index_name in ["bench_a", "bench_b"] {
            engine
                .create_index(CreateIndexRequest {
                    index: index_name.to_string(),
                    settings: serde_json::json!({}),
                    mappings: serde_json::json!({
                        "properties": {
                            "event_time": { "type": "date", "fast": true }
                        }
                    }),
                })
                .unwrap();
        }

        for (index, id, event_time) in [
            ("bench_a", "1", "2024-01-01T08:00:00Z"),
            ("bench_a", "2", "2024-01-02T09:00:00Z"),
            ("bench_b", "3", "2024-01-02T11:00:00Z"),
            ("bench_b", "4", "2024-01-03T12:00:00Z"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: index.to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "event_time": event_time
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["bench_a".to_string(), "bench_b".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["bench_a".to_string(), "bench_b".to_string()],
                query: serde_json::json!({
                    "match_all": {}
                }),
                aggregations: serde_json::json!({
                    "event_hist_day_plugin": {
                        "plugin": {
                            "name": "demo",
                            "kind": "date_histogram",
                            "params": {
                                "field": "event_time",
                                "calendar_interval": "day"
                            }
                        }
                    },
                    "event_hist_day_bucket_script_plugin": {
                        "plugin": {
                            "name": "demo",
                            "kind": "bucket_script",
                            "params": {
                                "aggregation": "event_hist_day_plugin",
                                "path": "_count",
                                "script": "_value * params.scale",
                                "params": {
                                    "scale": 10.0
                                }
                            }
                        }
                    }
                }),
                sort: Vec::new(),
                from: 0,
                size: 0,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 4);
        assert!(response.hits.is_empty());
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description
                    == "matched refreshed documents with multi-index native reduce"
        }));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.skipped
                && phase.description
                    == "size=0 multi-index native aggregation reduce avoided hit fetch"
        }));
        assert_eq!(
            response.aggregations,
            serde_json::json!({
                "event_hist_day_plugin": {
                    "buckets": [
                        {
                            "key": 1704067200000i64,
                            "key_as_string": "2024-01-01T00:00:00.000Z",
                            "doc_count": 1
                        },
                        {
                            "key": 1704153600000i64,
                            "key_as_string": "2024-01-02T00:00:00.000Z",
                            "doc_count": 2
                        },
                        {
                            "key": 1704240000000i64,
                            "key_as_string": "2024-01-03T00:00:00.000Z",
                            "doc_count": 1
                        }
                    ],
                    "_plugin": "demo",
                    "_type": "date_histogram",
                    "params": {
                        "field": "event_time",
                        "calendar_interval": "day"
                    }
                },
                "event_hist_day_bucket_script_plugin": {
                    "buckets": [
                        { "key": 1704067200000i64, "value": 10.0 },
                        { "key": 1704153600000i64, "value": 20.0 },
                        { "key": 1704240000000i64, "value": 10.0 }
                    ],
                    "_plugin": "demo",
                    "_type": "bucket_script",
                    "params": {
                        "aggregation": "event_hist_day_plugin",
                        "path": "_count",
                        "script": "_value * params.scale",
                        "params": {
                            "scale": 10.0
                        }
                    }
                }
            })
        );
    }

