    #[test]
    fn native_tantivy_plugin_top_hits_aggregation_preserves_shape() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "bench".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "message": { "type": "text" },
                        "bytes": { "type": "long" }
                    }
                }),
            })
            .unwrap();

        for (id, message, bytes) in [
            ("1", "banana", 10),
            ("2", "banana banana", 30),
            ("3", "banana cherry", 20),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "bench".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "message": message,
                        "bytes": bytes
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["bench".to_string()],
            })
            .unwrap();

        let query = parse_query(&serde_json::json!({
            "match": { "message": "banana" }
        }))
        .unwrap();
        let aggregations = parse_search_aggregation_map(&serde_json::json!({
            "recent_hits": {
                "plugin": {
                    "name": "demo",
                    "kind": "top_hits",
                    "params": { "from": 1, "size": 2 }
                }
            },
            "first_hit": {
                "plugin": {
                    "name": "demo",
                    "kind": "top_hits",
                    "params": { "from": 0, "size": 1 }
                }
            },
            "sorted_first_hit": {
                "plugin": {
                    "name": "demo",
                    "kind": "top_hits",
                    "params": {
                        "from": 0,
                        "size": 1,
                        "sort": [
                            { "_id": { "order": "desc" } }
                        ]
                    }
                }
            },
            "script_sorted_first_hit": {
                "plugin": {
                    "name": "demo",
                    "kind": "top_hits",
                    "params": {
                        "from": 0,
                        "size": 1,
                        "sort": [
                            {
                                "_script": {
                                    "order": "asc",
                                    "script": {
                                        "source": "doc['bytes'].value"
                                    }
                                }
                            }
                        ]
                    }
                }
            },
            "script_sorted_last_hit": {
                "plugin": {
                    "name": "demo",
                    "kind": "top_hits",
                    "params": {
                        "from": 0,
                        "size": 1,
                        "sort": [
                            {
                                "_script": {
                                    "order": "desc",
                                    "script": {
                                        "source": "doc['bytes'].value"
                                    }
                                }
                            }
                        ]
                    }
                }
            }
        }))
        .unwrap();

        let mut store = engine.store.write().unwrap();
        let index = store.indices.get_mut("bench").unwrap();
        let native = index
            .collect_aggregations_native(&query, &aggregations)
            .unwrap()
            .expect("native plugin top_hits aggregation");
        assert_eq!(native["recent_hits"]["hits"]["total"]["value"], serde_json::json!(3));
        assert_eq!(native["recent_hits"]["_plugin"], serde_json::json!("demo"));
        assert_eq!(native["recent_hits"]["_type"], serde_json::json!("top_hits"));
        assert_eq!(
            native["recent_hits"]["params"],
            serde_json::json!({ "from": 1, "size": 2 })
        );
        assert_eq!(
            native["recent_hits"]["hits"]["hits"]
                .as_array()
                .unwrap()
                .len(),
            2
        );
        assert_eq!(native["first_hit"]["hits"]["total"]["value"], serde_json::json!(3));
        assert_eq!(native["first_hit"]["_plugin"], serde_json::json!("demo"));
        assert_eq!(native["first_hit"]["_type"], serde_json::json!("top_hits"));
        assert_eq!(
            native["first_hit"]["params"],
            serde_json::json!({ "from": 0, "size": 1 })
        );
        assert_eq!(
            native["first_hit"]["hits"]["hits"]
                .as_array()
                .unwrap()
                .len(),
            1
        );
        assert_eq!(
            native["sorted_first_hit"]["hits"]["total"]["value"],
            serde_json::json!(3)
        );
        assert_eq!(native["sorted_first_hit"]["_plugin"], serde_json::json!("demo"));
        assert_eq!(native["sorted_first_hit"]["_type"], serde_json::json!("top_hits"));
        assert_eq!(
            native["sorted_first_hit"]["params"],
            serde_json::json!({
                "from": 0,
                "size": 1,
                "sort": [
                    { "_id": { "order": "desc" } }
                ]
            })
        );
        assert_eq!(
            native["sorted_first_hit"]["hits"]["hits"][0]["_id"],
            serde_json::json!("3")
        );
        assert_eq!(
            native["script_sorted_first_hit"]["hits"]["total"]["value"],
            serde_json::json!(3)
        );
        assert_eq!(
            native["script_sorted_first_hit"]["params"],
            serde_json::json!({
                "from": 0,
                "size": 1,
                "sort": [
                    {
                        "_script": {
                            "order": "asc",
                            "script": {
                                "source": "doc['bytes'].value"
                            }
                        }
                    }
                ]
            })
        );
        assert_eq!(
            native["script_sorted_first_hit"]["hits"]["hits"][0]["_id"],
            serde_json::json!("1")
        );
        assert_eq!(
            native["script_sorted_last_hit"]["hits"]["total"]["value"],
            serde_json::json!(3)
        );
        assert_eq!(
            native["script_sorted_last_hit"]["params"],
            serde_json::json!({
                "from": 0,
                "size": 1,
                "sort": [
                    {
                        "_script": {
                            "order": "desc",
                            "script": {
                                "source": "doc['bytes'].value"
                            }
                        }
                    }
                ]
            })
        );
        assert_eq!(
            native["script_sorted_last_hit"]["hits"]["hits"][0]["_id"],
            serde_json::json!("2")
        );
    }

    #[test]
    fn native_tantivy_plugin_filter_and_filters_aggregations_preserve_shape() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "bench".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "status": { "type": "keyword" },
                        "service": { "type": "keyword" }
                    }
                }),
            })
            .unwrap();

        for (id, status, service) in [
            ("1", "ok", "api"),
            ("2", "warn", "api"),
            ("3", "ok", "worker"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "bench".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "status": status,
                        "service": service
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["bench".to_string()],
            })
            .unwrap();

        let query = parse_query(&serde_json::json!({
            "match_all": {}
        }))
        .unwrap();
        let aggregations = parse_search_aggregation_map(&serde_json::json!({
            "ok_only": {
                "plugin": {
                    "name": "demo",
                    "kind": "filter",
                    "params": {
                        "filter": { "term": { "status": "ok" } }
                    }
                }
            },
            "service_split": {
                "plugin": {
                    "name": "demo",
                    "kind": "filters",
                    "params": {
                        "filters": {
                            "api_only": { "term": { "service": "api" } },
                            "warn_only": { "term": { "status": "warn" } }
                        }
                    }
                }
            }
        }))
        .unwrap();

        let mut store = engine.store.write().unwrap();
        let index = store.indices.get_mut("bench").unwrap();
        let native = index
            .collect_aggregations_native(&query, &aggregations)
            .unwrap()
            .expect("native plugin filter/filter aggregations");
        assert_eq!(
            native,
            serde_json::json!({
                "ok_only": {
                    "doc_count": 2,
                    "_plugin": "demo",
                    "_type": "filter",
                    "params": {
                        "filter": { "term": { "status": "ok" } }
                    }
                },
                "service_split": {
                    "buckets": {
                        "api_only": { "doc_count": 2 },
                        "warn_only": { "doc_count": 1 }
                    },
                    "_plugin": "demo",
                    "_type": "filters",
                    "params": {
                        "filters": {
                            "api_only": { "term": { "service": "api" } },
                            "warn_only": { "term": { "status": "warn" } }
                        }
                    }
                }
            })
        );

        let warn_aggregations = parse_search_aggregation_map(&serde_json::json!({
            "warn_only": {
                "plugin": {
                    "name": "demo",
                    "kind": "filter",
                    "params": {
                        "filter": { "term": { "status": "warn" } }
                    }
                }
            }
        }))
        .unwrap();
        let warn_native = index
            .collect_aggregations_native(&query, &warn_aggregations)
            .unwrap()
            .expect("native plugin filter warn aggregation");
        assert_eq!(
            warn_native,
            serde_json::json!({
                "warn_only": {
                    "doc_count": 1,
                    "_plugin": "demo",
                    "_type": "filter",
                    "params": {
                        "filter": { "term": { "status": "warn" } }
                    }
                }
            })
        );
    }

