    #[test]
    fn multi_index_native_tantivy_plugin_top_metrics_reduce_preserves_shape() {
        let engine = TantivyEngine::default();
        for index_name in ["bench_a", "bench_b"] {
            engine
                .create_index(CreateIndexRequest {
                    index: index_name.to_string(),
                    settings: serde_json::json!({}),
                    mappings: serde_json::json!({
                        "properties": {
                            "status": { "type": "keyword" },
                            "latency": { "type": "long" }
                        }
                    }),
                })
                .unwrap();
        }

        for (index, id, status, latency) in [
            ("bench_a", "1", "ok", 10),
            ("bench_a", "2", "warn", 30),
            ("bench_b", "3", "critical", 50),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: index.to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "status": status,
                        "latency": latency
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["bench_a".to_string(), "bench_b".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["bench_a".to_string(), "bench_b".to_string()],
                query: serde_json::json!({ "match_all": {} }),
                aggregations: serde_json::json!({
                    "slowest_status": {
                        "plugin": {
                            "name": "demo",
                            "kind": "top_metrics",
                            "params": {
                                "metrics": [
                                    { "field": "status" },
                                    { "field": "latency" }
                                ],
                                "sort": [
                                    { "latency": "desc" }
                                ]
                            }
                        }
                    }
                }),
                sort: Vec::new(),
                from: 0,
                size: 0,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 3);
        assert!(response.hits.is_empty());
        assert_eq!(
            response.aggregations,
            serde_json::json!({
                "slowest_status": {
                    "top": [{
                        "sort": [50],
                        "metrics": {
                            "status": "critical",
                            "latency": 50
                        }
                    }],
                    "_plugin": "demo",
                    "_type": "top_metrics",
                    "params": {
                        "metrics": [
                            { "field": "status" },
                            { "field": "latency" }
                        ],
                        "sort": [
                            { "latency": "desc" }
                        ]
                    }
                }
            })
        );
    }

