    #[test]
    fn native_tantivy_plugin_percentile_ranks_bucket_preserves_shape() {
        let aggregations = parse_search_aggregation_map(&serde_json::json!({
            "by_status": {
                "terms": {
                    "field": "status",
                    "size": 10
                }
            },
            "latency_sum_ranks_plugin": {
                "plugin": {
                    "name": "demo",
                    "kind": "percentile_ranks_bucket",
                    "params": {
                        "buckets_path": "by_status>latency_sum",
                        "values": [5.0, 30.0]
                    }
                }
            }
        }))
        .unwrap();

        let mut native = serde_json::Map::new();
        native.insert(
            "by_status".to_string(),
            serde_json::json!({
                "buckets": [
                    {
                        "key": "ok",
                        "doc_count": 2,
                        "latency_sum": { "value": 30.0 }
                    },
                    {
                        "key": "warn",
                        "doc_count": 1,
                        "latency_sum": { "value": 5.0 }
                    }
                ]
            }),
        );
        for (name, aggregation) in &aggregations {
            match aggregation {
                Aggregation::Pipeline(pipeline) => {
                    native.insert(name.clone(), collect_pipeline_aggregation(&native, pipeline));
                }
                Aggregation::Plugin(plugin) => {
                    if plugin_pipeline_aggregation(plugin).is_some() {
                        native.insert(
                            name.clone(),
                            plugin_pipeline_aggregation_value(&native, plugin),
                        );
                    }
                }
                _ => {}
            }
        }

        assert_eq!(
            serde_json::Value::Object(native),
            serde_json::json!({
                "by_status": {
                    "buckets": [
                        {
                            "key": "ok",
                            "doc_count": 2,
                            "latency_sum": { "value": 30.0 }
                        },
                        {
                            "key": "warn",
                            "doc_count": 1,
                            "latency_sum": { "value": 5.0 }
                        }
                    ]
                },
                "latency_sum_ranks_plugin": {
                    "values": {
                        "5.0": 50.0,
                        "30.0": 100.0
                    },
                    "_plugin": "demo",
                    "_type": "percentile_ranks_bucket",
                    "params": {
                        "buckets_path": "by_status>latency_sum",
                        "values": [5.0, 30.0]
                    }
                }
            })
        );
    }

