    #[test]
    fn search_size_zero_native_aggregations_skip_top_level_hit_fetch() {
        let engine = TantivyEngine::default();
        engine
            .create_index(CreateIndexRequest {
                index: "bench".to_string(),
                settings: serde_json::json!({}),
                mappings: serde_json::json!({
                    "properties": {
                        "event_time": { "type": "date", "fast": true },
                        "service": { "type": "keyword" }
                    }
                }),
            })
            .unwrap();

        for (id, event_time, service) in [
            ("1", "2024-01-01T08:00:00Z", "api"),
            ("2", "2024-01-01T10:00:00Z", "api"),
            ("3", "2024-01-02T09:00:00Z", "worker"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: "bench".to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "event_time": event_time,
                        "service": service
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["bench".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["bench".to_string()],
                query: serde_json::json!({
                    "match_all": {}
                }),
                aggregations: serde_json::json!({
                    "by_service": { "terms": { "field": "service", "size": 10 } },
                    "recent_events": {
                        "date_histogram": {
                            "field": "event_time",
                            "calendar_interval": "day"
                        }
                    }
                }),
                sort: Vec::new(),
                from: 0,
                size: 0,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 3);
        assert!(response.hits.is_empty());
        assert!(response
            .phase_results
            .iter()
            .any(|phase| phase.phase == SearchPhase::Fetch && phase.skipped));
        assert_eq!(
            response.aggregations,
            serde_json::json!({
                "by_service": {
                    "buckets": [
                        { "key": "api", "doc_count": 2 },
                        { "key": "worker", "doc_count": 1 }
                    ]
                },
                "recent_events": {
                    "buckets": [
                        {
                            "key": 1704067200000i64,
                            "key_as_string": "2024-01-01T00:00:00.000Z",
                            "doc_count": 2
                        },
                        {
                            "key": 1704153600000i64,
                            "key_as_string": "2024-01-02T00:00:00.000Z",
                            "doc_count": 1
                        }
                    ]
                }
            })
        );
    }

    #[test]
    fn search_size_zero_multi_index_native_aggregations_reduce_without_hit_fetch() {
        let engine = TantivyEngine::default();
        for index in ["bench-a", "bench-b"] {
            engine
                .create_index(CreateIndexRequest {
                    index: index.to_string(),
                    settings: serde_json::json!({}),
                    mappings: serde_json::json!({
                        "properties": {
                            "service": { "type": "keyword" },
                            "latency": { "type": "long" },
                            "weight": { "type": "long" },
                            "event_time": { "type": "date", "fast": true }
                        }
                    }),
                })
                .unwrap();
        }

        for (index, id, service, latency, weight, event_time) in [
            ("bench-a", "1", "api", 10, 1, "2024-01-01T08:00:00Z"),
            ("bench-a", "2", "worker", 15, 2, "2024-01-01T09:00:00Z"),
            ("bench-b", "3", "api", 20, 3, "2024-01-01T10:00:00Z"),
            ("bench-b", "4", "api", 5, 4, "2024-01-01T11:00:00Z"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: index.to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "service": service,
                        "latency": latency,
                        "weight": weight,
                        "event_time": event_time
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["bench-a".to_string(), "bench-b".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["bench-a".to_string(), "bench-b".to_string()],
                query: serde_json::json!({
                    "match_all": {}
                }),
                aggregations: serde_json::json!({
                    "by_service": { "terms": { "field": "service", "size": 10 } },
                    "service_percentiles_bucket": {
                        "percentiles_bucket": {
                            "buckets_path": "by_service>_count"
                        }
                    },
                    "service_plugin_stats_bucket": {
                        "plugin": {
                            "name": "demo",
                            "kind": "stats_bucket",
                            "params": {
                                "buckets_path": "by_service>_count"
                            }
                        }
                    },
                    "recent_hits": {
                        "top_hits": { "from": 0, "size": 2 }
                    },
                    "recent_hits_plugin": {
                        "plugin": {
                            "name": "demo",
                            "kind": "top_hits",
                            "params": { "from": 0, "size": 2 }
                        }
                    }
                }),
                sort: Vec::new(),
                from: 0,
                size: 0,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 4);
        assert!(response.hits.is_empty());
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description
                    == "matched refreshed documents with multi-index native reduce"
        }));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.skipped
                && phase.description
                    == "size=0 multi-index native aggregation reduce avoided hit fetch"
        }));

        let aggregations = &response.aggregations;
        assert_eq!(
            aggregations.get("by_service"),
            Some(&serde_json::json!({
                "buckets": [
                    { "key": "api", "doc_count": 3 },
                    { "key": "worker", "doc_count": 1 }
                ]
            }))
        );
        assert_eq!(
            aggregations.get("service_percentiles_bucket"),
            Some(&serde_json::json!({
                "values": {
                    "1.0": 1.02,
                    "5.0": 1.1,
                    "25.0": 1.5,
                    "50.0": 2.0,
                    "75.0": 2.5,
                    "95.0": 2.9,
                    "99.0": 2.98
                }
            }))
        );
        assert_eq!(
            aggregations.get("service_plugin_stats_bucket"),
            Some(&serde_json::json!({
                "count": 2,
                "min": 1.0,
                "max": 3.0,
                "avg": 2.0,
                "sum": 4.0,
                "_plugin": "demo",
                "_type": "stats_bucket",
                "params": {
                    "buckets_path": "by_service>_count"
                }
            }))
        );
        let recent_hits_ids = aggregations
            .get("recent_hits")
            .and_then(|value| value.get("hits"))
            .and_then(|value| value.get("hits"))
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default()
            .into_iter()
            .filter_map(|hit| hit.get("_id").and_then(Value::as_str).map(str::to_string))
            .collect::<Vec<_>>();
        assert_eq!(recent_hits_ids, vec!["1".to_string(), "2".to_string()]);
        assert_eq!(
            aggregations
                .get("recent_hits_plugin")
                .and_then(|value| value.get("_plugin")),
            Some(&Value::String("demo".to_string()))
        );
    }

