    #[test]
    fn multi_index_knn_uses_vector_native_page_and_aggregation_reduce() {
        let engine = TantivyEngine::default();
        for index in ["vectors-a", "vectors-b"] {
            engine
                .create_index(CreateIndexRequest {
                    index: index.to_string(),
                    settings: serde_json::json!({}),
                    mappings: serde_json::json!({
                        "properties": {
                            "embedding": {
                                "type": "knn_vector",
                                "dimension": 3,
                                "space_type": "l2"
                            },
                            "service": { "type": "keyword" },
                            "region": { "type": "keyword" },
                            "latency": { "type": "long" },
                            "weight": { "type": "long" },
                            "event_time": { "type": "date", "fast": true },
                            "location": { "type": "geo_point" }
                        }
                    }),
                })
                .unwrap();
        }

        for (index, id, service, region, latency, weight, event_time, lat, lon, embedding) in [
            ("vectors-a", "a", "api", "west", 10, 1, "2024-01-01T08:00:00Z", 37.0, -122.0, serde_json::json!([1.0, 0.0, 0.0])),
            ("vectors-a", "b", "worker", "west", 20, 2, "2024-01-01T09:00:00Z", 38.5, -121.5, serde_json::json!([0.9, 0.1, 0.0])),
            ("vectors-b", "c", "api", "east", 30, 3, "2024-01-01T10:00:00Z", 36.5, -123.5, serde_json::json!([0.8, 0.2, 0.0])),
            ("vectors-b", "d", "api", "west", 40, 4, "2024-01-01T11:00:00Z", 39.0, -120.0, serde_json::json!([0.7, 0.3, 0.0])),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: index.to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "service": service,
                        "region": region,
                        "latency": latency,
                        "weight": weight,
                        "event_time": event_time,
                        "location": { "lat": lat, "lon": lon },
                        "embedding": embedding
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["vectors-a".to_string(), "vectors-b".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["vectors-a".to_string(), "vectors-b".to_string()],
                query: serde_json::json!({
                    "knn": {
                        "embedding": {
                            "vector": [1.0, 0.0, 0.0],
                            "k": 4
                        }
                    }
                }),
                aggregations: serde_json::json!({
                    "by_service": { "terms": { "field": "service", "size": 10 } },
                    "service_plugin_terms": {
                        "plugin": {
                            "name": "demo",
                            "kind": "terms",
                            "params": { "field": "service", "size": 10 }
                        }
                    },
                    "service_percentiles_bucket": {
                        "percentiles_bucket": {
                            "buckets_path": "by_service>_count"
                        }
                    },
                    "service_plugin_stats_bucket": {
                        "plugin": {
                            "name": "demo",
                            "kind": "stats_bucket",
                            "params": {
                                "buckets_path": "by_service>_count"
                            }
                        }
                    },
                    "recent_hits": {
                        "top_hits": { "from": 0, "size": 2 }
                    }
                }),
                sort: Vec::new(),
                from: 1,
                size: 2,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 4);
        assert_eq!(search_hit_ids(&response.hits), vec!["b", "c"]);

        let aggregations = &response.aggregations;
        assert_eq!(
            aggregations.get("by_service"),
            Some(&serde_json::json!({
                "buckets": [
                    { "key": "api", "doc_count": 3 },
                    { "key": "worker", "doc_count": 1 }
                ]
            }))
        );
        assert_eq!(
            aggregations
                .get("service_plugin_terms")
                .and_then(|value| value.get("_plugin")),
            Some(&Value::String("demo".to_string()))
        );
        assert_eq!(
            aggregations.get("service_percentiles_bucket"),
            Some(&serde_json::json!({
                "values": {
                    "1.0": 1.02,
                    "5.0": 1.1,
                    "25.0": 1.5,
                    "50.0": 2.0,
                    "75.0": 2.5,
                    "95.0": 2.9,
                    "99.0": 2.98
                }
            }))
        );
        assert_eq!(
            aggregations.get("service_plugin_stats_bucket"),
            Some(&serde_json::json!({
                "count": 2,
                "min": 1.0,
                "max": 3.0,
                "avg": 2.0,
                "sum": 4.0,
                "_plugin": "demo",
                "_type": "stats_bucket",
                "params": {
                    "buckets_path": "by_service>_count"
                }
            }))
        );
        let recent_hits_ids = aggregations
            .get("recent_hits")
            .and_then(|value| value.get("hits"))
            .and_then(|value| value.get("hits"))
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default()
            .into_iter()
            .filter_map(|hit| hit.get("_id").and_then(Value::as_str).map(str::to_string))
            .collect::<Vec<_>>();
        assert_eq!(recent_hits_ids, vec!["a".to_string(), "b".to_string()]);
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description
                    == "matched refreshed documents with multi-index vector-native page+aggregation reduce"
        }));
        assert!(
            response
                .phase_results
                .iter()
                .any(|phase| phase.phase == SearchPhase::Fetch)
        );

        let id_sorted_response = engine
            .search(SearchRequest {
                indices: vec!["vectors-a".to_string(), "vectors-b".to_string()],
                query: serde_json::json!({
                    "knn": {
                        "embedding": {
                            "vector": [1.0, 0.0, 0.0],
                            "k": 4
                        }
                    }
                }),
                aggregations: serde_json::json!({
                    "by_service": { "terms": { "field": "service", "size": 10 } }
                }),
                sort: vec![SortSpec {
                    field: "_id".to_string(),
                    order: SortOrder::Asc,
                    unmapped_type: None,
                    geo_origin: None,
                    mode: None,
                    script: None,
                }],
                from: 1,
                size: 2,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();
        assert_eq!(id_sorted_response.total_hits, 4);
        assert_eq!(search_hit_ids(&id_sorted_response.hits), vec!["b", "c"]);
        assert!(id_sorted_response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description
                    == "matched refreshed documents with multi-index vector-native page+aggregation reduce"
        }));
        assert!(id_sorted_response
            .phase_results
            .iter()
            .any(|phase| phase.phase == SearchPhase::Fetch));

        let id_desc_sorted_response = engine
            .search(SearchRequest {
                indices: vec!["vectors-a".to_string(), "vectors-b".to_string()],
                query: serde_json::json!({
                    "knn": {
                        "embedding": {
                            "vector": [1.0, 0.0, 0.0],
                            "k": 4
                        }
                    }
                }),
                aggregations: serde_json::json!({
                    "by_service": { "terms": { "field": "service", "size": 10 } }
                }),
                sort: vec![SortSpec {
                    field: "_id".to_string(),
                    order: SortOrder::Desc,
                    unmapped_type: None,
                    geo_origin: None,
                    mode: None,
                    script: None,
                }],
                from: 1,
                size: 2,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();
        assert_eq!(id_desc_sorted_response.total_hits, 4);
        assert_eq!(search_hit_ids(&id_desc_sorted_response.hits), vec!["c", "b"]);
        assert!(id_desc_sorted_response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description
                    == "matched refreshed documents with multi-index vector-native page+aggregation reduce"
        }));
        assert!(id_desc_sorted_response
            .phase_results
            .iter()
            .any(|phase| phase.phase == SearchPhase::Fetch));
    }

