    #[test]
    fn multi_index_hybrid_uses_vector_native_page_and_aggregation_reduce_with_script_sort() {
        let engine = TantivyEngine::default();
        for index in ["vectors-a", "vectors-b"] {
            engine
                .create_index(CreateIndexRequest {
                    index: index.to_string(),
                    settings: serde_json::json!({}),
                    mappings: serde_json::json!({
                        "properties": {
                            "embedding": {
                                "type": "knn_vector",
                                "dimension": 3,
                                "space_type": "l2"
                            },
                            "body": { "type": "text" },
                            "service": { "type": "keyword" },
                            "latency": { "type": "long" }
                        }
                    }),
                })
                .unwrap();
        }

        for (index, id, body, service, latency, embedding) in [
            (
                "vectors-a",
                "a",
                "apple alpha",
                "api",
                10,
                Some(serde_json::json!([1.0, 0.0, 0.0])),
            ),
            (
                "vectors-a",
                "b",
                "apple beta",
                "worker",
                20,
                Some(serde_json::json!([0.9, 0.1, 0.0])),
            ),
            ("vectors-b", "c", "apple lexical only", "api", 30, None),
            (
                "vectors-b",
                "d",
                "banana only",
                "api",
                40,
                Some(serde_json::json!([0.7, 0.3, 0.0])),
            ),
        ] {
            let mut source =
                serde_json::json!({ "body": body, "service": service, "latency": latency });
            if let Some(embedding) = embedding {
                source["embedding"] = embedding;
            }
            engine
                .index_document(IndexDocumentRequest {
                    index: index.to_string(),
                    id: id.to_string(),
                    source,
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["vectors-a".to_string(), "vectors-b".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["vectors-a".to_string(), "vectors-b".to_string()],
                query: serde_json::json!({
                    "bool": {
                        "should": [
                            { "match": { "body": "apple" } },
                            {
                                "knn": {
                                    "embedding": {
                                        "vector": [1.0, 0.0, 0.0],
                                        "k": 2
                                    }
                                }
                            }
                        ],
                        "minimum_should_match": 1
                    }
                }),
                aggregations: serde_json::json!({
                    "by_service": { "terms": { "field": "service", "size": 10 } },
                    "plugin_sorted_first_hit": {
                        "plugin": {
                            "name": "demo",
                            "kind": "top_hits",
                            "params": {
                                "from": 0,
                                "size": 1,
                                "sort": [
                                    { "_id": { "order": "desc" } }
                                ]
                            }
                        }
                    }
                }),
                sort: vec![SortSpec {
                    field: "_script".to_string(),
                    order: SortOrder::Asc,
                    unmapped_type: None,
                    geo_origin: None,
                    mode: None,
                    script: Some(os_engine::SortScript {
                        source: "doc['latency'].value".to_string(),
                        params: BTreeMap::new(),
                    }),
                }],
                from: 1,
                size: 2,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 4);
        assert_eq!(search_hit_ids(&response.hits), vec!["b", "c"]);
        assert_eq!(
            response.aggregations.get("by_service"),
            Some(&serde_json::json!({
                "buckets": [
                    { "key": "api", "doc_count": 3 },
                    { "key": "worker", "doc_count": 1 }
                ]
            }))
        );
        let plugin_sorted_first_hit_ids = response
            .aggregations
            .get("plugin_sorted_first_hit")
            .and_then(|value| value.get("hits"))
            .and_then(|value| value.get("hits"))
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default()
            .into_iter()
            .filter_map(|hit| hit.get("_id").and_then(Value::as_str).map(str::to_string))
            .collect::<Vec<_>>();
        assert_eq!(plugin_sorted_first_hit_ids, vec!["d".to_string()]);
        assert_eq!(
            response
                .aggregations
                .get("plugin_sorted_first_hit")
                .and_then(|value| value.get("_plugin")),
            Some(&serde_json::json!("demo"))
        );
        assert_eq!(
            response
                .aggregations
                .get("plugin_sorted_first_hit")
                .and_then(|value| value.get("_type")),
            Some(&serde_json::json!("top_hits"))
        );
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description
                    == "matched refreshed documents with multi-index vector-native page+aggregation reduce"
        }));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.description
                    == "materialized only the requested multi-index vector-native page with native aggregation reduce"
        }));
    }

    #[test]
    fn multi_index_hybrid_compatibility_leaf_size_zero_skips_hit_materialization() {
        let engine = TantivyEngine::default();
        for index in ["vectors-a", "vectors-b"] {
            engine
                .create_index(CreateIndexRequest {
                    index: index.to_string(),
                    settings: serde_json::json!({}),
                    mappings: serde_json::json!({
                        "properties": {
                            "embedding": {
                                "type": "knn_vector",
                                "dimension": 3,
                                "space_type": "l2"
                            },
                            "body": { "type": "text" }
                        }
                    }),
                })
                .unwrap();
        }

        for (index, id, body, embedding) in [
            (
                "vectors-a",
                "a",
                "apple alpha vector",
                Some(serde_json::json!([1.0, 0.0, 0.0])),
            ),
            (
                "vectors-a",
                "b",
                "apple beta vector",
                Some(serde_json::json!([0.9, 0.1, 0.0])),
            ),
            ("vectors-b", "c", "apricot lexical only", None),
        ] {
            let mut source = serde_json::json!({ "body": body });
            if let Some(embedding) = embedding {
                source["embedding"] = embedding;
            }
            engine
                .index_document(IndexDocumentRequest {
                    index: index.to_string(),
                    id: id.to_string(),
                    source,
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["vectors-a".to_string(), "vectors-b".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["vectors-a".to_string(), "vectors-b".to_string()],
                query: serde_json::json!({
                    "bool": {
                        "should": [
                            { "wildcard": { "body": "apri*" } },
                            {
                                "knn": {
                                    "embedding": {
                                        "vector": [1.0, 0.0, 0.0],
                                        "k": 2
                                    }
                                }
                            }
                        ],
                        "minimum_should_match": 1
                    }
                }),
                aggregations: serde_json::json!({}),
                sort: Vec::new(),
                from: 0,
                size: 0,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 3);
        assert!(response.hits.is_empty());
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description
                    == "matched refreshed documents with multi-index vector-native page reduce"
        }));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.description
                    == "multi-index vector-native page reduce skipped hit materialization because size=0"
        }));
    }

