    #[test]
    fn multi_index_native_size_zero_page_reduce_skips_hit_materialization() {
        let engine = TantivyEngine::default();
        for index in ["logs-a", "logs-b"] {
            engine
                .create_index(CreateIndexRequest {
                    index: index.to_string(),
                    settings: serde_json::json!({}),
                    mappings: serde_json::json!({
                        "properties": {
                            "message": { "type": "text" }
                        }
                    }),
                })
                .unwrap();
        }

        for (index, id, message) in [
            ("logs-a", "a", "banana"),
            ("logs-a", "b", "banana"),
            ("logs-b", "c", "banana"),
            ("logs-b", "d", "apple"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: index.to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({
                        "message": message
                    }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["logs-a".to_string(), "logs-b".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["logs-a".to_string(), "logs-b".to_string()],
                query: serde_json::json!({
                    "match": { "message": "banana" }
                }),
                aggregations: serde_json::json!({}),
                sort: Vec::new(),
                from: 0,
                size: 0,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 3);
        assert!(response.hits.is_empty());
        assert_eq!(response.aggregations, serde_json::json!({}));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description
                    == "matched refreshed documents with multi-index native page reduce"
        }));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.description
                    == "multi-index native page reduce skipped hit materialization because size=0"
        }));
    }

