    #[test]
    fn multi_index_text_case_insensitive_wildcard_size_zero_compatibility_path_skips_hit_materialization(
    ) {
        let engine = TantivyEngine::default();
        for index in ["logs-a", "logs-b"] {
            engine
                .create_index(CreateIndexRequest {
                    index: index.to_string(),
                    settings: serde_json::json!({}),
                    mappings: serde_json::json!({
                        "properties": {
                            "body": { "type": "text" }
                        }
                    }),
                })
                .unwrap();
        }

        for (index, id, body) in [
            ("logs-a", "a", "Apricot Alpha"),
            ("logs-a", "b", "banana"),
            ("logs-b", "c", "apricot beta"),
            ("logs-b", "d", "cherry"),
        ] {
            engine
                .index_document(IndexDocumentRequest {
                    index: index.to_string(),
                    id: id.to_string(),
                    source: serde_json::json!({ "body": body }),
                })
                .unwrap();
        }
        engine
            .refresh(RefreshRequest {
                indices: vec!["logs-a".to_string(), "logs-b".to_string()],
            })
            .unwrap();

        let response = engine
            .search(SearchRequest {
                indices: vec!["logs-a".to_string(), "logs-b".to_string()],
                query: serde_json::json!({
                    "wildcard": {
                        "body": {
                            "value": "APRI*",
                            "case_insensitive": true
                        }
                    }
                }),
                aggregations: serde_json::json!({}),
                sort: Vec::new(),
                from: 0,
                size: 0,
                stored_fields: None,
                source_fields: None,
                source_filter: None,
                source_includes: None,
                source_include: None,
                source_excludes: None,
                source_exclude: None,
                highlight: None,
                explain: false,
            })
            .unwrap();

        assert_eq!(response.total_hits, 2);
        assert!(response.hits.is_empty());
        assert_eq!(response.aggregations, serde_json::json!({}));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Query
                && phase.description == "matched refreshed documents without hit fetch"
        }));
        assert!(response.phase_results.iter().any(|phase| {
            phase.phase == SearchPhase::Fetch
                && phase.description
                    == "size=0 compatibility path avoided top-level hit materialization"
        }));
    }

