    fn field<'a>(schema: &'a TantivyIndexSchema, name: &str) -> &'a TantivyFieldMapping {
        schema
            .fields
            .iter()
            .find(|field| field.name == name)
            .unwrap()
    }

    fn hit_ids(hits: &[VectorSearchHit]) -> Vec<&str> {
        hits.iter().map(|hit| hit.id.as_str()).collect()
    }

    trait SearchHitIdSource {
        fn search_hit_slice(&self) -> &[SearchHit];
    }

    impl SearchHitIdSource for [SearchHit] {
        fn search_hit_slice(&self) -> &[SearchHit] {
            self
        }
    }

    impl SearchHitIdSource for Vec<SearchHit> {
        fn search_hit_slice(&self) -> &[SearchHit] {
            self
        }
    }

    impl SearchHitIdSource for (u64, Vec<SearchHit>) {
        fn search_hit_slice(&self) -> &[SearchHit] {
            &self.1
        }
    }

    fn search_hit_ids<T: SearchHitIdSource + ?Sized>(hits: &T) -> Vec<&str> {
        hits.search_hit_slice()
            .iter()
            .map(|hit| hit.metadata.id.as_str())
            .collect()
    }

    fn document_ids<'a>(documents: &'a [&'a StoredDocument]) -> Vec<&'a str> {
        documents
            .iter()
            .map(|document| document.metadata.id.as_str())
            .collect()
    }

    fn test_search_hit(index: String, id: String, score: f32, source: Value) -> SearchHit {
        SearchHit {
            index,
            metadata: DocumentMetadata {
                id,
                version: 1,
                seq_no: 0,
                primary_term: 1,
            },
            score,
            source,
            sort: None,
            fields: None,
            highlight: None,
            explanation: None,
        }
    }

